(function (global) {
  'use strict';
  // Original example sentences. Coverage is deliberately explicit, not generated at runtime.
  const rows = [
    ["follow","Follow the instructions carefully.","指示に注意深く従ってください。","follow の直後に従う対象を置きます。follow to the instructions とはしません。"],
    ["consider","We are considering moving to a smaller house.","私たちはもっと小さな家へ引っ越すことを検討しています。","「〜することを検討する」は consider doing。consider to do と混同しないようにしましょう。"],
    ["increase","The number of visitors increased last year.","昨年、訪問者の数が増えました。","increase は「増える」と「増やす」の両方に使えます。この例では後ろに目的語がなく、「増える」です。"],
    ["expect","I expect the train to arrive soon.","電車はまもなく到着すると思います。","expect は予測や期待を表します。必ずしも「そうなってほしい」という願いではありません。expect A to do の形です。"],
    ["decide","We decided to walk home.","私たちは歩いて帰ることに決めました。","「〜することに決める」は decide to do。決定した内容を to の後ろに置きます。"],
    ["develop","She developed a new way to teach vocabulary.","彼女は語彙を教える新しい方法を開発しました。","この例は develop + 目的語で「〜を開発する」。Skills develop with practice. なら「技能が発達する」です。"],
    ["provide","The school provides students with lunch.","その学校は生徒に昼食を提供しています。","provide 人 with 物の形。provide lunch for students とも表せます。"],
    ["continue","The rain continued all night.","雨は一晩中降り続きました。","この例の continue は「続く」。continue studying のように、続ける行動を後ろに置くこともできます。"],
    ["include","The price includes breakfast.","料金には朝食が含まれています。","include は全体の中に何かを含むこと。朝食以外が含まれない、という意味ではありません。"],
    ["remain","Please remain calm.","落ち着いたままでいてください。","remain + 形容詞で「〜のままでいる」。この例の calm は動作ではなく状態を表します。"],
    ["reach","We reached the station before noon.","私たちは正午前に駅に着きました。","到着先は reach の直後に置きます。arrive at the station と違い、reach at the station とはしません。"],
    ["allow","My parents allow me to use their computer.","両親は私が両親のパソコンを使うことを許可しています。","allow 人 to do で「人が〜することを許す」。許可される人と行動を分けて読みます。"],
    ["force","The storm forced us to stay indoors.","嵐のため、私たちは屋内にとどまらざるを得ませんでした。","force 人 to do は「人に〜することを強いる」。人だけでなく状況も主語になります。"],
    ["offer","He offered to carry my bag.","彼は私のかばんを運ぼうかと申し出ました。","offer to do は自分から行動を申し出ること。相手に行動を求める ask とは区別します。"],
    ["realize","I realized that I had the wrong key.","私は違う鍵を持っていることに気づきました。","この例では、事実を理解して「気づく」。notice が見聞きして気づく場合に使われるのに対し、realize は理解に焦点があります。"],
    ["suggest","She suggested taking an earlier train.","彼女はもっと早い電車に乗ることを提案しました。","suggest doing で行動を提案します。この意味で suggest to take とはしません。"],
    ["require","This job requires patience.","この仕事には忍耐力が必要です。","require は必要条件を表します。単に「欲しい」を表す want と同じではありません。"],
    ["worry","Try not to worry about the test.","試験のことを心配しすぎないようにしてください。","心配の対象には worry about を使います。The news worried me. なら「その知らせが私を心配させた」です。"],
    ["wonder","I wonder why the shop is closed.","なぜその店が閉まっているのだろう。","wonder は「〜だろうかと思う」。why の後ろは the shop is の語順で、疑問文の is the shop にはしません。"],
    ["cost","This ticket costs 500 yen.","この切符は500円です。","費用がかかる物を主語にして cost + 金額。人を主語にする pay と区別しましょう。"],
    ["tend","I tend to forget names when I am nervous.","私は緊張していると名前を忘れがちです。","tend to do は『〜する傾向がある』。毎回必ずそうなる、という意味ではありません。to の後ろには動詞の原形を置きます。"],
    ["depend","The price depends on the size of the room.","料金は部屋の大きさによって決まります。","depend on は『〜次第である・〜に頼る』。この例は料金を決める条件を示しています。depend of とはしません。"],
    ["share","I share a kitchen with two other students.","私はほかの学生2人と台所を共用しています。","share 物 with 人で『物を人と共有する』。share は物を分配する場合にも使いますが、この例では同じ設備を一緒に使います。"],
    ["demand","The passengers demanded an explanation.","乗客たちは説明を要求しました。","demand は強く要求すること。ask for an explanation より強い表現です。丁寧な依頼で気軽に使うと強すぎる場合があります。"],
    ["support","My friends supported me during the competition.","友人たちは大会の間、私を支えてくれました。","support の直後に支える相手や支持する案を置きます。support me は金銭面の援助だけでなく、精神的に支える場合にも使えます。"],
    ["hire","The restaurant hired two new cooks.","そのレストランは新しい料理人を2人雇いました。","hire 人で『人を雇う』。人を募集する recruit と違い、この例では雇い入れることを表します。イギリス英語では車などを借りる意味もあります。"],
    ["regard","I regard this mistake as a chance to learn.","私はこの間違いを学ぶ機会だと考えています。","regard A as B で『AをBとみなす』。as を含めて覚えましょう。この例では mistake がA、a chance to learn がBです。"],
    ["base","The film is based on a true story.","その映画は実話に基づいています。","be based on は『〜に基づいている』。base A on B は『Aの基礎をBに置く』で、この例はその受け身です。"],
    ["improve","Reading aloud helped me improve my pronunciation.","音読は私が発音を改善するのに役立ちました。","improve は『〜を改善する』と『よくなる』の両方に使えます。My pronunciation improved. なら改善したもの自体が主語になります。"],
    ["recognize","I recognized her voice immediately.","私は彼女の声だとすぐに分かりました。","recognize は見聞きしたものが何か・誰かを識別する場合に使います。単に音が聞こえたという hear より、知っているものと結び付ける点が中心です。"],
    ["notice","I noticed a small crack in the window.","私は窓の小さなひびに気づきました。","notice は注意が向いて存在や変化に気づくこと。この例では目でひびを見つけています。考えて事実を理解する realize とは焦点が違います。"],
    ["suppose","I suppose the shop is still open.","その店はまだ開いていると思います。","I suppose ... は確信を少し控えて『〜だと思う』と言う表現。be supposed to do（〜することになっている）とは形と意味を区別しましょう。"],
    ["raise","Please raise your hand if you have a question.","質問があれば手を挙げてください。","raise はこの意味では目的語が必要です。raise your hand のように上げるものを示します。rise は The sun rises. のように、それ自体が上がるときに使います。"],
    ["prefer","I prefer tea to coffee.","私はコーヒーより紅茶が好きです。","prefer A to B で『BよりAを好む』。この比較では than ではなく to を使います。好みの対象が2つあるときは順番にも注意します。"],
    ["cheer","The crowd cheered the runners on.","観衆は走者たちに声援を送りました。","cheer 人 on は『人に声援を送る』。cheer 人 up は『人を元気づける』で、後ろの語によって意味が変わります。"],
    ["suffer","Many residents suffered from a lack of clean water.","多くの住民が清潔な水の不足に苦しみました。","suffer from は病気や問題に苦しむこと。suffer damage のように from を使わず『損害を受ける』と表す形もあります。"],
    ["describe","Can you describe the bag you lost?","なくしたかばんがどのようなものか説明できますか。","describe は特徴や様子を言葉で述べること。describe the bag to me のように、説明する相手には to を付けます。describe me the bag とは通常しません。"],
    ["prevent","The heavy snow prevented us from leaving.","大雪で私たちは出発できませんでした。","prevent 人 from doing で『人が〜するのを妨げる』。この例は出発を防いだ原因が主語です。from の後ろは leaving の形になります。"],
    ["reduce","We reduced the amount of paper we use.","私たちは使う紙の量を減らしました。","reduce は量・程度などを小さくすること。reduce by 20% は『20%分減らす』、reduce to 20% は『20%まで減らす』です。"],
    ["mistake","I mistook his silence for agreement.","私は彼の沈黙を同意だと勘違いしました。","動詞は mistake A for B（AをBと間違える）。過去形は mistook。名詞なら make a mistake（間違いをする）の形で使います。"],
    ["prepare","I prepared a short speech for the meeting.","私は会議のために短いスピーチを用意しました。","prepare a speech はスピーチ自体を用意すること。prepare for a meeting は会議に備えることです。for の有無で後ろの名詞との関係が変わります。"],
    ["encourage","Our teacher encouraged us to ask questions.","先生は私たちに質問するよう勧めてくれました。","encourage 人 to do は『人が〜するよう励ます・促す』。force と違い、無理にさせることを中心とする表現ではありません。"],
    ["prove","The task proved more difficult than we expected.","その作業は予想以上に難しいと分かりました。","prove + 形容詞は『〜だと分かる』。prove that ...（〜であると証明する）とは文の形が違います。この例では作業の難しさが明らかになっています。"],
    ["treat","Please treat the equipment with care.","機器を丁寧に扱ってください。","treat は『扱う』ほか『治療する』『おごる』などの意味があります。treat A as B は『AをBとして扱う』。文脈と後ろの語を確認しましょう。"],
    ["establish","They established a small company in 2018.","彼らは2018年に小さな会社を設立しました。","establish は組織・制度などを作り、成立させること。建物そのものを建てる build と区別します。establish a rule なら規則を定めることです。"],
    ["relate","These questions relate to the article we read.","これらの質問は私たちが読んだ記事に関係しています。","relate to は『〜に関係する』。relate A to B なら『AをBに関連付ける』です。目的語があるかどうかに注目します。"],
    ["compare","Compare your answer with the example.","自分の答えを例と比較してください。","compare A with B で両者の共通点や違いを比べます。compare A to B は比較にも使われ、何かにたとえる意味もあります。常に訳が一つに決まるわけではありません。"],
    ["spread","The news spread quickly through the town.","その知らせは町中にすぐに広まりました。","spread は『広がる』と『広げる』の両方に使えます。現在形・過去形・過去分詞がすべて spread なので、文脈から時を判断します。"],
    ["refer","The word they refers to the students in this sentence.","この文の they という語は、その生徒たちを指しています。","refer to は『〜を指す・〜に言及する・〜を参照する』。この例では代名詞の指す相手を説明しています。refer の後ろの to を忘れないようにします。"],
    ["supply","The farm supplies local shops with vegetables.","その農場は地元の店に野菜を供給しています。","supply A with B は『AにBを供給する』。supply vegetables to local shops のように、供給する物を先に置く形もあります。"],
    ["gain","She gained confidence through practice.","彼女は練習を通じて自信をつけました。","gain は努力や経験を通じて何かを得る場合に使います。gain confidence のほか gain experience（経験を積む）もよく使う組み合わせです。"],
    ["destroy","The fire destroyed the old warehouse.","火事で古い倉庫が破壊されました。","destroy は使えないほど破壊すること。damage は損傷を与えることで、完全に壊れているとは限りません。被害の程度に注意して使い分けます。"],
    ["apply","I applied for a part-time job at the library.","私は図書館のアルバイトに応募しました。","apply for は仕事・許可などに応募・申請する形。apply to は応募先を示したり、This rule applies to everyone. のように『当てはまる』を表したりします。"],
    ["seek","You should seek advice before signing the contract.","契約書に署名する前に助言を求めるべきです。","seek の直後に求めるものを置きます。seek advice に for は不要です。過去形・過去分詞は sought です。"],
    ["search","We searched the room for the missing key.","私たちはなくなった鍵を求めて部屋を捜しました。","search 場所 for 物で『場所を捜して物を探す』。search the room は捜す場所、search for the key は探している物を示します。"],
    ["claim","He claims that he saw a fox in the garden.","彼は庭でキツネを見たと主張しています。","claim は話し手が主張を紹介する語で、その内容が確認済みだとは限りません。claim that ... の内容と、裏付けがあるかを分けて読みます。"],
    ["draw","She drew the curtains to keep out the sunlight.","彼女は日差しを遮るためにカーテンを引きました。","draw は『描く』以外に『引く』の意味があります。draw the curtains は文脈によって開ける・閉めるの両方になり、この例は日差しを遮るので閉めています。"],
    ["refuse","He refused to answer the question.","彼はその質問に答えることを拒みました。","refuse to do は『〜することを拒む』。refuse an offer のように名詞も置けます。refuse answering より、この意味では refuse to answer を使います。"],
    ["respond","She responded to my message the next day.","彼女は翌日、私のメッセージに返答しました。","respond to は返答先や反応する対象を示します。answer my message には to が要らないので、動詞ごとの形に注意しましょう。"],
    ["mention","He mentioned the problem during lunch.","彼は昼食中にその問題に触れました。","mention の直後に話題を置きます。mention about the problem とは通常しません。詳しく説明する describe と違い、短く触れる場合にも使えます。"],
    ["judge","Do not judge a book by its cover.","本を表紙だけで判断してはいけません。","judge A by B は『Bを基準にAを判断する』。この表現は、人や物を外見だけで判断しないよう促すことわざとしても使われます。"],
    ["approach","We approached the entrance quietly.","私たちは静かに入り口に近づきました。","動詞 approach の直後に近づく対象を置き、approach to the entrance とはしません。名詞の an approach to learning では to を使えます。"],
    ["admit","He admitted making a mistake.","彼は間違えたことを認めました。","admit doing で『〜したことを認める』。admit that he had made a mistake とも言えます。入場を認める意味もあるので文脈を確認します。"],
    ["reflect","The lake reflected the mountains.","湖は山々を映していました。","この例は光や像を『反射する・映す』意味。reflect on an experience は『経験を振り返って考える』で、on を伴う別の使い方です。"],
    ["perform","The technician performed a safety check.","技術者は安全点検を行いました。","perform a check は点検を実施すること。perform は演奏や演技にも使われますが、後ろが task や check なら作業の実行を表します。"],
    ["bore","The long speech bored the audience.","長いスピーチに聴衆は退屈しました。","bore 人で『人を退屈させる』。退屈させるものは boring、退屈した人の気持ちは bored。I am boring. と I am bored. は意味が違います。"],
    ["survive","Several trees survived the storm.","何本かの木は嵐を生き延びました。","survive the storm のように、切り抜けた出来事を直接置けます。survive from the storm とは通常しません。目的語なしでも『生き残る』と表せます。"],
    ["represent","The blue line represents the average temperature.","青い線は平均気温を表しています。","represent は図や記号が何かを『表す』場合に使えます。represent a country なら国を『代表する』意味になります。"],
    ["argue","They argued that the park should remain open.","彼らは公園を開放したままにすべきだと主張しました。","argue that ... は理由を示して主張すること。argue with 人 about 事柄なら『人と事柄について口論する』場合もあり、必ずけんかの意味ではありません。"],
    ["grant","The council granted them permission to use the hall.","評議会は彼らにホールの使用許可を与えました。","grant 人 物で許可や権利などを正式に与えます。この例の permission to use は『使用する許可』というまとまりです。"],
    ["indicate","The arrow indicates the direction of the exit.","矢印は出口の方向を示しています。","indicate は記号や情報が何かを示すこと。示唆する意味の場合もあり、The results indicate ... だけで絶対的な証明を意味するわけではありません。"],
    ["belong","This umbrella belongs to my sister.","この傘は私の姉のものです。","belong to は所有者や所属先を示します。通常、この所有の意味で is belonging や is belonged とはしません。"],
    ["acquire","He acquired useful skills through volunteer work.","彼はボランティア活動を通じて役立つ技能を身につけました。","acquire skills は学習や経験を通じて技能を習得すること。物や権利を取得する意味にも使われ、対象によって訳が変わります。"],
    ["reply","Please reply to this email by Friday.","金曜日までにこのメールに返信してください。","reply to は返答する対象を示します。reply は答えを返す意味が中心で、respond は刺激への反応など、言葉以外にも使えます。"],
    ["feed","Please do not feed the birds.","鳥に餌を与えないでください。","feed の直後に食べ物を与える相手を置けます。feed the birds bread なら相手と食べ物の両方を示します。過去形・過去分詞は fed です。"],
    ["escape","The cat escaped from the cage.","猫はかごから逃げ出しました。","escape from は逃げ出した場所を示します。escape danger（危険を免れる）のように、避けたものを直接置く使い方もあります。"],
    ["replace","We replaced the old printer with a new one.","私たちは古いプリンターを新しいものに取り替えました。","replace A with B は『AをBに取り替える』。取り除かれるのはA、代わりに入るのはBです。順番を逆にしないようにしましょう。"],
    ["reveal","The test revealed a small error in the program.","テストでプログラムの小さな誤りが明らかになりました。","reveal は隠れていたことや未知だったことを明らかにする語。この例ではテストが誤りを作ったのではなく、存在を明らかにしています。"],
    ["surround","Tall trees surround the house.","高い木々がその家を取り囲んでいます。","surround A は『Aを取り囲む』。家を主語にすると The house is surrounded by tall trees. という受け身になります。"],
    ["suit","Friday afternoon suits me best.","金曜日の午後が私には一番都合がよいです。","suit は好みや都合に合うこと。服なら suit は似合う、fit はサイズが合う、match は色などが調和するという違いがあります。"],
    ["estimate","We estimate that the repair will take two days.","私たちは修理に2日かかると見積もっています。","estimate は情報を基におおよそを見積もること。正確に測った値とは限りません。estimate the cost なら費用を見積もります。"],
    ["aim","We aim to finish the project by June.","私たちは6月までにその計画を終えることを目指しています。","aim to do は『〜することを目指す』。aim at a target は『標的を狙う』で、後ろの形によって目標の示し方が変わります。"],
    ["earn","She earns money by teaching piano.","彼女はピアノを教えてお金を稼いでいます。","earn は仕事や努力により得ること。earn respect（尊敬を得る）のようにお金以外にも使えます。単に受け取る receive とは焦点が違います。"],
    ["decline","The number of customers declined in winter.","冬には客の数が減りました。","この例の decline は『減少する』。decline an invitation は『招待を辞退する』です。主語や目的語を見て意味を判断します。"],
    ["afford","We cannot afford to buy a new car this year.","私たちは今年、新車を買う余裕がありません。","can afford to do は『〜する余裕がある』。金銭だけでなく時間や損失に耐える余裕にも使えます。afford buying ではなく to buy の形です。"],
    ["confuse","I sometimes confuse these two words.","私はときどきこの2つの単語を混同します。","confuse A with B で『AとBを混同する』とも言えます。confused は混乱した気持ち、confusing は混乱させる性質を表します。"],
    ["graduate","She graduated from university last spring.","彼女は昨年の春、大学を卒業しました。","卒業した学校を示す基本形は graduate from。アメリカ英語では from を省く用法もありますが、学習では from を含む形を覚えると使いやすいです。"],
    ["vary","Opening hours vary from store to store.","営業時間は店によって異なります。","vary from A to A は『Aごとに異なる』。vary は違いや変動を表し、必ず増える・必ず減るという方向は示しません。"],
    ["remove","Please remove your shoes before entering.","入る前に靴を脱いでください。","remove はその場所から取り除くこと。remove the stain from the shirt なら『シャツから染みを落とす』です。必ず破壊する意味ではありません。"],
    ["insist","He insisted on paying for lunch.","彼は昼食代を払うと言って譲りませんでした。","insist on doing は『〜すると言って譲らない』。on の後ろは動名詞です。insist that ... という文を続ける形もあります。"],
    ["examine","The mechanic examined the engine carefully.","整備士はエンジンを注意深く調べました。","examine は状態を知るために詳しく調べること。単に見る look at よりも、点検・検査する目的がはっきりしています。"],
    ["remind","Please remind me to bring my notebook.","ノートを持ってくるよう、私に念を押してください。","remind 人 to do は『人に〜することを思い出させる』。remind 人 of 物は物事を思い出させる形。remember は本人が思い出すことです。"],
    ["contribute","Regular exercise contributes to good health.","定期的な運動は健康に役立ちます。","contribute to は『〜に貢献する・〜の一因となる』。to は前置詞なので、動作を続けるなら doing の形。悪い結果の一因を示す場合にも使います。"],
    ["warn","They warned us about the icy road.","彼らは道路が凍結していることについて私たちに注意を促しました。","warn 人 about 危険で『危険について人に警告する』。warn 人 not to do なら、危険な行動をしないよう警告します。"],
    ["connect","This bridge connects the island to the mainland.","この橋は島と本土をつないでいます。","connect A to B は『AをBにつなぐ』。connect A with B も使われます。名詞 connection と合わせて、つながりの意味を確認しましょう。"],
    ["match","Your scarf matches your coat.","あなたのマフラーはコートによく合っています。","match はこの例では色や柄などが調和すること。match your coat と直接目的語を置けます。match the record なら記録に並ぶ意味になります。"],
    ["focus","Let us focus on one problem at a time.","一度に1つの問題に集中しましょう。","focus on は『〜に集中する』。focus your attention on ... のように、何を集中させるかを目的語で示す形もあります。"],
    ["reject","The committee rejected the proposal.","委員会はその提案を却下しました。","reject は提案や申請などを受け入れないこと。refuse to do は行動することを拒む形ですが、この意味で reject to do とはしません。"],
    ["convince","The evidence convinced me that she was right.","その証拠によって、私は彼女が正しいと確信しました。","convince 人 that ... は『人に〜だと確信させる』。convince 人 of 名詞という形もあります。この例は証拠を基に考えが変わっています。"],
    ["associate","I associate this song with my school days.","私はこの歌を聞くと学生時代を連想します。","associate A with B は『AをBと結び付けて考える』。be associated with は『〜と関連がある』ですが、関連だけで因果関係があるとは限りません。"],
    ["rush","We rushed to the station.","私たちは駅へ急ぎました。","rush to + 場所で急いで向かうこと。rush through a task は作業を急いで済ませることです。"],
    ["stress","The teacher stressed the importance of practice.","先生は練習の重要性を強調しました。","ここでは動詞で『強調する』。名詞の stress（ストレス・強勢）と品詞を区別します。"],
    ["attract","The flowers attract butterflies.","その花はチョウを引きつけます。","attract の直後に引きつける対象を置きます。be attracted to は『〜に引かれる』です。"],
    ["rely","You can rely on her advice.","彼女の助言は頼りになります。","rely on で『〜に頼る』。reliable（信頼できる）も関連する形です。"],
    ["regret","I regret missing the meeting.","会議に出なかったことを後悔しています。","regret doing は過去の行動への後悔。regret to inform はこれから残念な知らせを伝えるときの表現です。"],
    ["adopt","The team adopted a new method.","チームは新しい方法を採用しました。","adopt は採用すること。adapt（適応する）と綴り・意味を混同しないようにします。"],
    ["shake","Shake the bottle before opening it.","開ける前に瓶を振ってください。","活用は shake–shook–shaken。shake hands は握手するという決まった表現です。"],
    ["hurt","I hurt my knee yesterday.","昨日、膝を痛めました。","hurt は過去形も同じ形。身体だけでなく hurt someone's feelings で感情を傷つけることも表します。"],
    ["operate","Only trained staff can operate this machine.","訓練を受けた職員だけがこの機械を操作できます。","operate a machine は機械を操作すること。手術する場合は operate on a patient の形です。"],
    ["extend","We extended the deadline by one week.","私たちは締め切りを1週間延ばしました。","by は延ばす長さ、to は延ばした先を示します。extend the deadline to Friday は金曜日まで延ばすことです。"],
    ["blame","Do not blame others for your mistakes.","自分の間違いを他人のせいにしてはいけません。","blame 人 for 事柄、または blame 事柄 on 人。人と事柄の位置に注意します。"],
    ["consist","The course consists of six lessons.","その講座は6回の授業から成ります。","consist of は構成要素を示します。通常 is consisted of という受け身にはしません。"],
    ["persuade","She persuaded me to join the club.","彼女は私を説得してクラブに入らせました。","persuade 人 to do は説得して行動へ導くこと。説得を試みただけなら try to persuade と言えます。"],
    ["admire","I admire her courage.","私は彼女の勇気に感心しています。","admire 人 for 性質なら、その性質を理由に人を称賛する形になります。"],
    ["disappoint","The result disappointed us.","その結果に私たちは失望しました。","人は disappointed、失望させる結果は disappointing。どちらの立場かで形を選びます。"],
    ["expand","The company plans to expand its business.","その会社は事業を拡大する計画です。","expand は規模や範囲を広げること。The business expanded. のように目的語なしでも使えます。"],
    ["preserve","We must preserve these historic buildings.","私たちはこれらの歴史的建造物を保存しなければなりません。","preserve は損なわれないよう保存・保護すること。予約する reserve と区別します。"],
    ["struggle","He struggled to open the heavy door.","彼は重いドアを開けようと苦労しました。","struggle to do は行動しようとして苦労すること。struggle with a problem は問題に苦闘することです。"],
    ["arrange","I arranged to meet her at noon.","私は正午に彼女と会う手はずを整えました。","arrange to do は自分がすることの手配。arrange for 人 to do は人がすることを手配する形です。"],
    ["disturb","Please do not disturb the sleeping baby.","眠っている赤ちゃんを起こさないようにしてください。","disturb は休息や集中を妨げること。interrupt は話や行動を途中で遮ることに重点があります。"],
    ["employ","The factory employs fifty people.","その工場は50人を雇っています。","employ は雇用すること。employ a method なら方法を用いる意味になり、対象によって訳が変わります。"],
    ["engage","The activity engaged all the children.","その活動は子どもたち全員の関心を引きました。","engage 人は人を引きつけること。engage in research は研究に従事することです。"],
    ["abandon","They abandoned the plan because of the cost.","彼らは費用のためにその計画を断念しました。","abandon は人や物を見捨てるだけでなく、計画を完全にやめる場合にも使います。"],
    ["display","The museum displays old maps.","その博物館は古い地図を展示しています。","display は見えるように示すこと。on display は『展示されている』という状態を表します。"],
    ["encounter","We encountered several problems.","私たちはいくつかの問題に直面しました。","encounter の直後に遭遇したものを置きます。予期しない人や問題との出会いに使われます。"],
    ["amuse","His funny stories amused the children.","彼のおもしろい話は子どもたちを楽しませました。","amused は楽しんだ人の気持ち、amusing は楽しませる話などの性質を表します。"],
    ["bother","Sorry to bother you.","お手数をおかけしてすみません。","bother 人は手間をかけたり困らせたりすること。bother to do はわざわざ行動するという使い方です。"],
    ["concentrate","I cannot concentrate on my homework here.","ここでは宿題に集中できません。","集中の対象には on を使います。concentration は名詞で『集中』です。"],
    ["adapt","It took time to adapt to the new schedule.","新しい予定に慣れるには時間がかかりました。","adapt to は環境に適応すること。adapt a novel for television は小説をテレビ向けに脚色することです。"],
    ["puzzle","His sudden departure puzzled me.","彼が突然出発したので私は困惑しました。","ここでは動詞で『困惑させる』。I was puzzled. なら困惑した人を主語にした表現です。"],
    ["appeal","This design appeals to young people.","このデザインは若者の心を引きつけます。","appeal to 人は人に魅力を感じさせること。appeal for help は助けを求めることです。"],
    ["combine","Combine the flour with the water.","小麦粉と水を混ぜ合わせてください。","combine A with B はAとBを結び合わせる形。combine work and study のように and でも並べられます。"],
    ["delay","They delayed starting the meeting.","彼らは会議の開始を遅らせました。","delay doing で行動を遅らせること。この形では delay to start とはしません。"],
    ["repair","Can you repair this bicycle?","この自転車を修理できますか。","repair は壊れたものを直すこと。replace は別のものに取り替えることで、修理とは違います。"],
    ["fascinate","The night sky fascinates me.","夜空に私は強く引きつけられます。","fascinate は強い興味を持たせること。fascinated は人の状態、fascinating は対象の魅力を表します。"],
    ["pardon","Please pardon my interruption.","話を遮ったことをお許しください。","pardon は許しを求める丁寧な表現。Pardon? は聞き返す表現にもなります。"],
    ["import","The company imports coffee from Brazil.","その会社はブラジルからコーヒーを輸入しています。","import は輸入すること。国外へ出す export（輸出する）と方向を区別します。"],
    ["remark","She remarked that the room was cold.","彼女は部屋が寒いと述べました。","remark that ... で気づいたことを述べます。名詞の a remark は発言・コメントです。"],
    ["reserve","I reserved a table for two.","私は2人分の席を予約しました。","reserve は将来使うために確保すること。book a table とも言えます。preserve（保存する）とは別です。"],
    ["amaze","Her memory amazed everyone.","彼女の記憶力にみんな驚きました。","amaze は驚嘆させること。amazed at her memory のように、驚いた対象を at で示せます。"],
    ["frighten","The loud noise frightened the dog.","大きな音に犬はおびえました。","frightened はおびえた状態、frightening は恐怖を与える性質。主語がどちら側かを確認します。"],
    ["release","They released the bird into the forest.","彼らは鳥を森に放しました。","release は拘束から解放すること。release a report や release a film では公表・公開する意味になります。"],
    ["rent","We rented a small apartment near the station.","私たちは駅の近くの小さなアパートを借りました。","rent は料金を払って借りること。borrow は通常、使用料を払わず借りる場合に使います。"],
    ["recover","He recovered from the illness.","彼は病気から回復しました。","recover from は病気や打撃から回復する形。recover a lost file は失われたファイルを取り戻す意味です。"],
    ["suspect","I suspect that the clock is slow.","その時計は遅れているのではないかと思います。","suspect that はそうかもしれないと考えること。疑わしいが確定していない内容を表します。"],
    ["deliver","They delivered the package this morning.","彼らは今朝その荷物を届けました。","deliver a package は荷物を届けること。deliver a speech なら演説をする意味です。"],
    ["identify","Can you identify this plant?","この植物が何か分かりますか。","identify は何であるかを特定すること。identify A as B はAをBだと特定する形です。"],
    ["locate","The hotel is located near the beach.","そのホテルは海辺の近くにあります。","場所にあることは be located の形。locate the hotel はホテルの場所を見つけるという動作を表します。"],
    ["manufacture","This company manufactures medical equipment.","この会社は医療機器を製造しています。","manufacture は通常、工業的な生産に使います。手作りの物も含めて広く使える make より範囲が限定されます。"],
    ["occupy","The desk occupies most of the room.","その机は部屋の大部分を占めています。","occupy は空間や時間を占めること。occupied は『使用中の・忙しい』という状態も表します。"],
    ["own","She owns a small bakery.","彼女は小さなパン屋を所有しています。","ここでは所有するという動詞。my own room の own は『自分自身の』と強調する使い方です。"],
    ["expose","Do not expose the film to light.","フィルムを光にさらさないでください。","expose A to B はAをBにさらす形。to の後ろに、接触させる環境や影響を置きます。"],
    ["translate","She translated the letter into Japanese.","彼女はその手紙を日本語に翻訳しました。","訳す先の言語は into で示します。translate from English into Japanese は英語から日本語に訳すことです。"],
    ["cure","The treatment cured his infection.","その治療で彼の感染症は治りました。","cure は治すという結果に焦点があります。treat は治療する行為で、必ず治るとは限りません。"],
    ["perceive","People perceive colors differently.","人によって色の感じ方は異なります。","perceive は感覚で捉えたり、あるように認識したりすること。perceive A as B でAをBと捉える形になります。"],
    ["adjust","Please adjust the height of the chair.","椅子の高さを調節してください。","adjust 物は調節すること。adjust to a new school は新しい学校に慣れることです。"],
    ["alarm","The sudden drop in sales alarmed us.","売上の急減に私たちは不安を覚えました。","alarm はここでは動詞で不安や恐れを感じさせること。目覚まし・警報という名詞の意味もあります。"],
    ["assist","She assisted me with the preparations.","彼女は準備を手伝ってくれました。","assist 人 with 事柄で援助の対象を示します。help より改まった表現として使われます。"],
    ["freeze","The lake froze last night.","昨夜、湖が凍りました。","活用は freeze–froze–frozen。freeze the food なら食べ物を凍らせる意味になります。"],
    ["spoil","The rain spoiled our picnic.","雨で私たちのピクニックは台無しになりました。","spoil は楽しみなどを損なうこと。食べ物が傷む、子どもを甘やかすという意味もあります。"],
    ["shift","We shifted our attention to the next problem.","私たちは次の問題へ注意を移しました。","shift A to B はAをBへ移す形。名詞の a night shift は夜間の勤務時間帯です。"],
    ["embarrass","His question embarrassed me.","彼の質問で私は恥ずかしい思いをしました。","embarrassed は恥ずかしいと感じた人の状態。embarrassing はそう感じさせる出来事に使います。"],
    ["approve","The council approved the new plan.","評議会は新しい計画を承認しました。","approve 物は正式に承認すること。approve of 物はよいと思う・賛成することで、形と意味が異なります。"],
    ["weigh","This bag weighs five kilograms.","このかばんは5キロあります。","weigh + 重さは重さがあること。weigh the bag は重さを量ることです。weigh the options なら選択肢を検討します。"],
    ["stretch","Stretch your arms above your head.","頭の上に腕を伸ばしてください。","stretch は伸ばす・広がること。stretch from A to B はAからBまで延びるという範囲を示します。"],
    ["participate","Everyone can participate in the discussion.","誰でも議論に参加できます。","参加する活動には in を付けます。take part in と近い意味で、participate the discussion とはしません。"],
    ["exhibit","The gallery exhibits local artists' work.","その画廊は地元の芸術家の作品を展示しています。","exhibit は作品などを展示すること。名詞なら an exhibit は展示物、exhibition は展覧会です。"],
    ["owe","I owe you ten dollars.","私はあなたに10ドル借りています。","owe 人 金額で借りがあること。owe A to B はAはBのおかげである、という意味にも使われます。"],
    ["celebrate","We celebrated her birthday together.","私たちは一緒に彼女の誕生日を祝いました。","celebrate の直後には祝う出来事を置きます。人を祝福するなら congratulate 人 on 出来事という形があります。"],
    ["decorate","They decorated the room with flowers.","彼らは花で部屋を飾りました。","decorate A with B で、飾る場所・物をA、飾りに使う物をBに置きます。"],
    ["forgive","Please forgive me for being late.","遅れたことを許してください。","forgive 人 for doing で許しを求める原因を示します。活用は forgive–forgave–forgiven です。"],
    ["seat","Please remain seated until the train stops.","電車が止まるまで座ったままでいてください。","seat は人を座らせる動詞。seated は座っている状態です。自分が座る動作には sit を使います。"],
    ["injure","He injured his ankle during practice.","彼は練習中に足首をけがしました。","injure は主に身体へのけがに使います。hurt は身体の痛みだけでなく感情を傷つける場合にも使えます。"],
    ["sew","She sewed a button onto the shirt.","彼女はシャツにボタンを縫い付けました。","sew は縫うこと。発音は so と同じです。過去形は sewed、過去分詞は sewn または sewed です。"],
    ["result","We are waiting for the results.","私たちは結果を待っています。","名詞で『結果』。動詞の result in は結果を、result from は原因を後ろに置きます。"],
    ["feature","The large windows are a useful feature of this house.","大きな窓はこの家の便利な特徴です。","feature は目立つ特徴や機能。動詞なら The film features a young actor. のように出演させる意味にもなります。"],
    ["society","Education plays an important role in society.","教育は社会で重要な役割を果たします。","社会一般を表す society は通常、冠詞なしで使います。a historical society は歴史研究の団体です。"],
    ["wheel","One wheel of my bicycle is damaged.","私の自転車は車輪が1つ傷んでいます。","wheel は車輪。the steering wheel は車のハンドルで、wheel だけでも文脈によってそれを指します。"],
    ["value","The value of the house has increased.","その家の価値は上がりました。","value は金銭的価値だけでなく重要性にも使います。values と複数形にすると価値観を表すことがあります。"],
    ["effect","The new rule had a positive effect.","新しい規則にはよい効果がありました。","have an effect on は『〜に影響を与える』。affect は通常動詞、effect は通常名詞として区別すると読みやすくなります。"],
    ["individual","Each individual has different needs.","一人ひとりに異なる必要があります。","individual は個人という名詞。形容詞の individual needs は個々の必要を表します。"],
    ["influence","Her advice had a strong influence on me.","彼女の助言は私に強い影響を与えました。","名詞では influence on 人の形。動詞なら Her advice influenced me. と直接目的語を置けます。"],
    ["fee","The entrance fee is five dollars.","入場料は5ドルです。","fee はサービスや参加の料金。交通機関の運賃は fare、商品の価格は price と言うのが基本です。"],
    ["rate","The population is growing at a steady rate.","人口は一定の割合で増えています。","rate は割合や速度。at a rate の形で変化の速さを示し、the exchange rate なら為替相場です。"],
    ["sign","Dark clouds can be a sign of rain.","暗い雲は雨の兆候であることがあります。","a sign of は何かの兆候。道路標識という意味もあり、動詞 sign は署名することです。"],
    ["service","The hotel provides a laundry service.","そのホテルは洗濯サービスを提供しています。","service は提供される業務・サービス。a bus service ならバスの運行を表します。"],
    ["advance","Please book your tickets in advance.","切符は前もって予約してください。","in advance は『前もって』という決まった表現。advance は前進や進歩という名詞・動詞にもなります。"],
    ["laughter","The room was filled with laughter.","部屋は笑い声でいっぱいでした。","laughter は通常数えない名詞。a laugh（一度の笑い）と違い、a laughter とは普通言いません。"],
    ["material","This material is light but strong.","この素材は軽いのに丈夫です。","material は素材。study materials のように複数形で教材や資料を表す使い方もあります。"],
    ["industry","Tourism is an important industry here.","ここでは観光が重要な産業です。","industry は工業だけでなく、観光などの産業・業界も表します。文脈に合った訳を選びます。"],
    ["attempt","Her first attempt was successful.","彼女の最初の試みは成功しました。","an attempt to do は『〜しようとする試み』。成功したかどうかは attempt 自体からは決まりません。"],
    ["trade","Trade between the two countries has increased.","その2か国間の貿易が増えました。","trade は貿易・取引。trade A for B という動詞の形ではAをBと交換することを表します。"],
    ["progress","You have made good progress.","あなたは順調に進歩しました。","progress は通常数えない名詞なので make a progress とはしません。make progress in English は英語で上達することです。"],
    ["excuse","That is not a good excuse for being late.","それは遅刻のもっともな言い訳にはなりません。","an excuse for doing で行動の言い訳を示します。Excuse me. は失礼を詫びたり呼びかけたりする動詞の用法です。"],
    ["custom","It is a local custom to remove your shoes.","靴を脱ぐのはその土地の習慣です。","custom は社会や集団の習慣。個人の習慣は habit。customs は税関を表すことがあります。"],
    ["passage","Read the passage and answer the questions.","文章を読んで質問に答えてください。","passage は文章の一節。通路・通行や the passage of time（時の経過）という意味もあります。"],
    ["economy","The local economy depends on tourism.","地域経済は観光に依存しています。","economy は経済の仕組みや状態。economics は経済学、economic は経済に関するという形容詞です。"],
    ["track","We followed a narrow track through the forest.","私たちは森の中の細い道を進みました。","track は小道・走路・跡など。keep track of は動きや状況を把握し続ける表現です。"],
    ["transportation","Public transportation is convenient here.","ここでは公共交通機関が便利です。","transportation は輸送・交通の手段をまとめて表す、通常数えない名詞。イギリス英語では transport もよく使われます。"],
    ["official","A city official answered our questions.","市の職員が私たちの質問に答えました。","official は役人・職員という名詞。an official announcement では『公式の』という形容詞です。"],
    ["sight","The mountains were a beautiful sight.","山々は美しい眺めでした。","sight は目に入る光景。lose sight of は見失うこと、at first sight は一目見たときの意味です。"],
    ["taste","This soup has a rich taste.","このスープは味が濃厚です。","名詞は味・好み。動詞の taste good はよい味がすることで、good を副詞にしません。"],
    ["range","The shop sells a wide range of books.","その店は幅広い種類の本を売っています。","a range of は一連の種類・範囲。range from A to B はAからBまで及ぶという動詞の形です。"],
    ["appointment","I have an appointment with the dentist.","私は歯科医の予約があります。","appointment は時間を決めた面会・診察など。友人との気軽な約束すべてに使う語ではありません。"],
    ["patient","The nurse spoke to the patient.","看護師はその患者に話しかけました。","a patient は患者という名詞。Please be patient. なら我慢強くいてください、という形容詞です。"],
    ["project","Our class started a recycling project.","私たちのクラスはリサイクルの計画を始めました。","project は目的と作業を伴う計画。単に将来の予定を述べる plan と使い分けます。"],
    ["favor","Could you do me a favor?","お願いを聞いていただけますか。","do 人 a favor は人のために親切な行為をすること。in favor of は賛成してという別の表現です。"],
    ["appearance","The building has a modern appearance.","その建物は現代的な外観です。","appearance は見た目。make an appearance は姿を見せることで、出現という意味もあります。"],
    ["risk","There is a risk of flooding.","洪水の危険があります。","a risk of doing は何かが起きる危険。動詞でも risk losing money のように動名詞を続けます。"],
    ["benefit","Regular practice has many benefits.","定期的な練習には多くの利点があります。","benefit は利益・利点。動詞の benefit from は何かから恩恵を受ける意味です。"],
    ["resident","Local residents use this park every day.","地元の住民は毎日この公園を利用しています。","resident はそこに住む人。観光客や一時的な訪問者 visitor と区別します。"],
    ["relative","We visited our relatives in Osaka.","私たちは大阪の親戚を訪ねました。","名詞は親族。形容詞では relative importance のように相対的な重要性を表します。"],
    ["region","Rice is grown in this region.","この地域では米が栽培されています。","region は地理や特徴で分けた比較的広い地域。必ず行政上の境界と一致するわけではありません。"],
    ["characteristic","Patience is an important characteristic of a good teacher.","忍耐力はよい教師の重要な特徴です。","characteristic は特徴という名詞。be characteristic of は『〜に特有である』という形です。"],
    ["pain","She felt a sharp pain in her shoulder.","彼女は肩に鋭い痛みを感じました。","痛む場所は pain in + 身体の部位。pain は身体的な痛みだけでなく精神的苦痛にも使います。"],
    ["twin","My brother and I are twins.","兄と私は双子です。","1人なら a twin、2人の双子なら twins。twin beds は同じ部屋にある2つのベッドを指します。"],
    ["occasion","We met on several occasions.","私たちは何度か会いました。","on an occasion はある機会に、on occasion はときどき。前置詞 on と組み合わせて覚えます。"],
    ["principle","Fairness is an important principle.","公平さは重要な原則です。","principle は原則。principal（主要な・校長）と発音は同じですが、綴りと意味が違います。"],
    ["department","She works in the sales department.","彼女は営業部で働いています。","department は組織内の部門や大学の学科。department store は百貨店です。"],
    ["duty","It is our duty to protect the environment.","環境を守ることは私たちの義務です。","duty は義務・職務。on duty は勤務中、customs duty は関税を表します。"],
    ["scene","The police arrived at the scene.","警察が現場に到着しました。","scene は出来事の現場や映画などの場面。scenery は風景をまとめて表す語です。"],
    ["jam","We were stuck in a traffic jam.","私たちは交通渋滞にはまっていました。","a traffic jam は1つの渋滞。traffic 自体は通常数えない名詞です。"],
    ["spirit","The team played with great spirit.","チームは強い意気込みでプレーしました。","spirit は精神・気力。in good spirits と複数形を使うと上機嫌であることを表します。"],
    ["medium","Radio is a useful medium for sharing information.","ラジオは情報共有に役立つ媒体です。","medium は伝達の手段・媒体。この意味の複数形 media は新聞・放送などの媒体を表します。"],
    ["mass","A mass of people gathered outside.","大勢の人々が外に集まりました。","a mass of は大量のまとまり。the masses は一般大衆を表し、科学では mass は質量です。"],
    ["audience","The audience listened quietly.","聴衆は静かに耳を傾けました。","audience は観客・聴衆をひとまとまりとして表します。人数の多さには large audience などを使います。"],
    ["element","Trust is an essential element of teamwork.","信頼はチームワークに欠かせない要素です。","element は構成要素。化学では酸素などの元素を表し、文脈で区別します。"],
    ["climate","This island has a mild climate.","この島は温暖な気候です。","climate は長期的な気候。今日の天気など短期の状態を表す weather と区別します。"],
    ["revolution","The invention caused a revolution in communication.","その発明は通信に大変革をもたらしました。","revolution は政治上の革命だけでなく、大きな変革にも使います。物体の回転という意味もあります。"],
    ["quarter","A quarter of the students walk to school.","生徒の4分の1は歩いて通学します。","a quarter は4分の1。a quarter of an hour は15分で、時刻の表現にも使います。"],
    ["furniture","We bought some furniture for the room.","私たちはその部屋用の家具を買いました。","furniture は通常数えない名詞。1点なら a piece of furniture と言い、a furniture とはしません。"],
    ["brain","The brain controls many functions of the body.","脳は身体の多くの機能を制御します。","brain は器官としての脳。頭のよさを表すときには brains という複数形も使われます。"],
    ["atmosphere","The cafe has a relaxing atmosphere.","そのカフェはくつろげる雰囲気です。","atmosphere は雰囲気。the Earth's atmosphere では地球を包む大気という意味になります。"],
    ["property","This land is private property.","この土地は私有地です。","property は財産・所有物。properties は物質などの性質を表すこともあります。"],
    ["reward","She received a reward for finding the lost dog.","彼女は迷子の犬を見つけて謝礼を受け取りました。","a reward for は行為への報酬。award は審査などを経て授与される賞を指すことが多い語です。"],
    ["security","The building has strict security.","その建物は警備が厳重です。","security は危険や侵入から守られた状態・警備。a security guard は警備員です。"],
    ["delight","To my delight, she accepted the invitation.","うれしいことに、彼女は招待を受けてくれました。","to one's delight はその人にとってうれしいことに、という表現。delighted は喜んでいる状態です。"],
    ["desert","Few plants grow in this desert.","この砂漠にはほとんど植物が育ちません。","desert は砂漠。dessert（デザート）は s が2つで、強勢の位置も違います。"],
    ["background","She has a background in engineering.","彼女には工学の経歴があります。","background は背景・生い立ち・経験。in the background は写真や状況の背景にあることです。"],
    ["trend","There is a growing trend toward online shopping.","オンラインで買い物する傾向が強まっています。","a trend toward はある方向への傾向。1回だけの変化ではなく、全体的な動きに使います。"],
    ["vote","Every member has one vote.","会員はそれぞれ1票を持っています。","vote は票・投票。動詞では vote for が賛成・支持、vote against が反対を表します。"],
    ["impact","The new road had a major impact on the town.","新しい道路は町に大きな影響を与えました。","have an impact on は『〜に影響を与える』。物理的な衝突の衝撃を表すこともあります。"],
    ["institution","The museum is an important cultural institution.","その博物館は重要な文化機関です。","institution は社会的役割を持つ機関。教育制度など、定着した制度や慣行にも使います。"],
    ["interaction","The course encourages interaction between students.","その講座は学生同士の交流を促します。","interaction は互いに働きかけること。between A and B で交流・相互作用する相手を示します。"],
    ["alternative","Cycling is an alternative to driving.","自転車は車で行くことの代わりになります。","an alternative to は『〜に代わる選択肢』。to は前置詞なので driving の形になります。"],
    ["harm","The chemicals may cause harm to wildlife.","その化学物質は野生生物に害を与えるかもしれません。","harm は通常数えない名詞。do harm to や cause harm to の形で害を与える対象を示します。"],
    ["agency","We booked the trip through a travel agency.","私たちは旅行代理店を通して旅行を予約しました。","agency は業務を代行する代理店や行政機関。agent はその業務を行う人を表します。"],
    ["capacity","The hall has a capacity of three hundred people.","そのホールの収容人数は300人です。","capacity は収容力・容量。a capacity for learning なら学ぶ能力を表します。"],
    ["minister","The minister announced a new policy.","大臣は新しい政策を発表しました。","minister は大臣。prime minister は首相で、宗教の文脈では聖職者を指すこともあります。"],
    ["volunteer","She works as a volunteer at the library.","彼女は図書館でボランティアとして活動しています。","a volunteer は自発的に活動する人。動詞 volunteer to do は自分から行動を申し出る形です。"],
    ["access","Students have access to the online library.","学生はオンライン図書館を利用できます。","名詞 access の対象には to を付けます。動詞 access the library は直接目的語を置きます。"],
    ["quantity","The factory uses large quantities of water.","その工場は大量の水を使います。","quantity は量、quality は質。a large quantity of と large quantities of はどちらも大量を表します。"],
    ["branch","A bird landed on a branch.","鳥が枝に止まりました。","branch は木の枝。a bank branch は銀行の支店、a branch of science は科学の一分野です。"],
    ["common","This is a common mistake.","これはよくある間違いです。","common はよくある・共通の。have something in common は共通点があるという表現です。"],
    ["rough","This is only a rough estimate.","これは大まかな見積もりにすぎません。","rough は精密でないという意味にも使います。a rough surface ならざらざらした表面です。"],
    ["likely","It is likely to rain tonight.","今夜は雨が降りそうです。","be likely to do は〜する可能性が高いこと。likely を『好きな』という like の意味にしないようにします。"],
    ["serious","This is a serious problem.","これは深刻な問題です。","serious は深刻な・真剣な。be serious about doing は行動について本気であることです。"],
    ["particular","Is there a particular book you need?","必要な特定の本はありますか。","particular はほかと区別した特定のもの。in particular は特に、という決まった表現です。"],
    ["available","This room is available tomorrow.","この部屋は明日利用できます。","available は物や人が「利用できる・対応できる」こと。possible は物事が「実現可能」であることです。部屋の空きを表すこの例では available を使います。"],
    ["bilingual","She grew up in a bilingual family.","彼女は2つの言語を使う家庭で育ちました。","bilingual は二言語を使うこと。bi- は2を表す接頭辞ですが、すべての bi で始まる単語に当てはまるわけではありません。"],
    ["ready","Are you ready to leave?","出発する準備はできていますか。","ready to do は行動の準備ができたこと。ready for the test のように名詞には for を使えます。"],
    ["correct","Your answer is correct.","あなたの答えは正しいです。","correct は正しいという形容詞。correct a mistake なら間違いを訂正するという動詞です。"],
    ["familiar","I am familiar with this area.","私はこの辺りをよく知っています。","人 is familiar with 物は人が物をよく知ること。物 is familiar to 人は物が人によく知られていることです。"],
    ["physical","Walking is a simple form of physical activity.","歩行は簡単な身体活動の一種です。","physical は身体の・物理的な。mental（精神の）との対比で使われることもあります。"],
    ["worth","This book is worth reading.","この本は読む価値があります。","be worth doing の形。worth to read とはしません。worth ten dollars は10ドルの価値があることです。"],
    ["involved","She is involved in the project.","彼女はその計画に参加しています。","be involved in は活動に関与していること。involved は複雑なという意味でも使われます。"],
    ["fantastic","We had a fantastic time.","私たちはすばらしい時間を過ごしました。","fantastic は会話で強くよい評価を表します。常に『幻想的な』という意味ではありません。"],
    ["private","This is a private conversation.","これは個人的な会話です。","private は私的な・非公開の。public（公の）との違いを意識します。"],
    ["obvious","The reason is obvious.","理由は明らかです。","It is obvious that ... で内容を文として示せます。副詞 obviously は明らかに、という意味です。"],
    ["native","Japanese is her native language.","日本語は彼女の母語です。","native language は母語。native plants はある地域にもともと生育している植物を指します。"],
    ["complex","The problem is more complex than it seems.","その問題は見かけより複雑です。","complex は複数の部分が関わる複雑さ。単に難しい difficult と必ずしも同じではありません。"],
    ["willing","He is willing to help us.","彼は私たちを手伝う気があります。","be willing to do は進んでする・してもよいという気持ち。能力を表す able とは別です。"],
    ["current","Please write your current address.","現在の住所を書いてください。","current は現在の、という意味が基本。必ず最も新しいという latest と同じではありません。"],
    ["male","The zoo has one male tiger.","その動物園には雄のトラが1頭います。","male は性別が男性・雄であること。人にも動物にも使い、female と対になります。"],
    ["proper","Use the proper tools for the job.","作業に適した道具を使ってください。","proper は状況に適切なこと。properly は適切に・きちんと、という副詞です。"],
    ["capable","She is capable of solving the problem.","彼女にはその問題を解く能力があります。","be capable of doing の形。capable to solve ではなく、of の後ろに動名詞を置きます。"],
    ["independent","He became financially independent.","彼は経済的に自立しました。","independent は他に依存しないこと。independent of は何から独立しているかを示します。"],
    ["positive","She has a positive attitude toward learning.","彼女は学習に前向きな姿勢を持っています。","positive は前向きな・肯定的な。検査では陽性を意味するため、いつもよい結果とは限りません。"],
    ["pleasant","We had a pleasant walk by the river.","私たちは川沿いを気持ちよく散歩しました。","pleasant は心地よいこと。pleased は人が喜んでいる状態で、使う対象が違います。"],
    ["significant","There has been a significant improvement.","大きな改善がありました。","significant は重要な・無視できない程度の。統計上の有意という専門的な意味は文脈で区別します。"],
    ["former","A former teacher visited the school.","元教師がその学校を訪ねました。","former は以前その立場だったこと。the former は2つ挙げたものの前者を指します。"],
    ["chemical","The experiment caused a chemical reaction.","実験で化学反応が起きました。","chemical は化学のという形容詞。a chemical は化学物質という名詞です。"],
    ["upset","She was upset about the cancellation.","彼女は中止になったことに動揺していました。","upset は心が乱れた状態。悲しみや怒りなどを含み、必ず怒っているだけとは限りません。"],
    ["previous","Please read the previous chapter first.","先に前の章を読んでください。","previous はある時点より前のもの。the previous day はその前日で、今日基準の yesterday と区別します。"],
    ["calm","Try to stay calm.","落ち着いているようにしてください。","stay calm は落ち着いた状態を保つこと。calm down は落ち着く・落ち着かせるという動作です。"],
    ["specific","Could you give a specific example?","具体的な例を挙げてもらえますか。","specific は具体的に特定されたこと。general（一般的な）との対比で意味を捉えられます。"],
    ["conscious","I am conscious of the need to improve.","私は改善の必要性を意識しています。","be conscious of は気づいていること。The patient is conscious. では患者に意識がある意味です。"],
    ["superior","This model is superior to the old one.","この機種は古いものより優れています。","superior to で比較します。superior than や more superior を基本形として使わないようにします。"],
    ["efficient","This is an efficient way to organize the files.","これはファイルを整理する効率的な方法です。","efficient は時間や労力の無駄が少ないこと。effective は望む効果があることで、焦点が違います。"],
    ["fundamental","Trust is fundamental to a good relationship.","信頼はよい関係の基礎となります。","fundamental to は〜にとって根本的に重要なこと。細かな付加要素ではなく土台を表します。"],
    ["narrow","The road is too narrow for a bus.","その道はバスには狭すぎます。","narrow は幅が狭いこと。narrow interests なら興味の範囲が狭いという比喩的な意味です。"],
    ["reasonable","The price seems reasonable.","値段は妥当なようです。","reasonable は理由に照らして妥当なこと。価格なら手頃という意味になりますが、必ず安いとは限りません。"],
    ["nervous","I felt nervous before the interview.","面接前に緊張しました。","nervous は不安や緊張を感じる状態。人物の性格だけでなく、一時的な気持ちにも使います。"],
    ["alike","The two houses look alike.","その2軒の家は似ています。","alike は通常、名詞の前より look alike や be alike の形で使います。名詞の前なら similar houses と言えます。"],
    ["domestic","This airport handles domestic flights.","この空港は国内線を扱っています。","domestic は国内の・家庭の。domestic flights は国際線 international flights と対比できます。"],
    ["negative","He gave a negative response.","彼は否定的な返答をしました。","negative は否定的な・負の。検査の陰性など、文脈によって評価のよしあしとは一致しません。"],
    ["moral","The story raises a moral question.","その物語は道徳的な問題を提起します。","moral は善悪に関すること。名詞の the moral of the story は話の教訓です。"],
    ["eager","The children are eager to learn.","子どもたちは学びたがっています。","be eager to do は強く行動したい気持ち。be willing to do より積極的な熱意を表します。"],
    ["remarkable","She made remarkable progress.","彼女は目覚ましい進歩を遂げました。","remarkable は注目に値すること。remark（述べる）から、取り上げて言う価値があるという意味につながります。"],
    ["evil","The story is about a battle against evil.","その物語は悪との戦いについてのものです。","evil は道徳的な悪という強い意味。a bad result のような単に望ましくない結果すべてには使いません。"],
    ["awake","I was still awake at midnight.","真夜中にも私はまだ起きていました。","awake は普通 be awake のように使います。名詞の前では an awake child より a child who is awake が自然です。"],
    ["aged","The course is for children aged ten to twelve.","その講座は10〜12歳の子ども向けです。","aged + 年齢は年齢を示す使い方。この例を『年老いた』と訳さず、後ろの数字まで確認します。"],
    ["anxious","She was anxious about the exam.","彼女は試験を心配していました。","anxious about は心配していること。anxious to do は強く望むことも表すので、後ろの形を確認します。"],
    ["tough","It was a tough decision.","それは難しい決断でした。","tough は難しい・厳しい・頑丈ななどの意味。発音は『タフ』に近く、gh を g の音で読まないようにします。"],
    ["nuclear","The article discusses nuclear energy.","その記事は原子力エネルギーを論じています。","nuclear は核に関すること。nucleus（核）が関連語で、発電や兵器など後ろの名詞で具体的な内容が変わります。"],
    ["legal","We sought legal advice.","私たちは法律上の助言を求めました。","legal は法律に関する・合法の。違法の illegal は否定を表す il- が付いた形です。"],
    ["curious","The children were curious about the machine.","子どもたちはその機械に興味津々でした。","curious about は〜について知りたがっていること。a curious event なら奇妙な出来事という意味にもなります。"],
    ["civil","Voting is a civil right.","投票は市民の権利です。","civil は市民の・民事の。civil war は内戦という決まった表現で、単語ごとの直訳では意味を取りにくい例です。"],
    ["recent","Have you read her recent book?","彼女の最近の本を読みましたか。","recent は名詞を修飾する形容詞。最近その行動をしたと言うなら副詞 recently を使います。"],
    ["senior","A senior engineer checked the design.","上級の技術者が設計を確認しました。","senior は年齢や役職が上であること。senior to me と比較し、senior than me とは通常しません。"],
    ["afterward","We had dinner and went for a walk afterward.","私たちは夕食を食べ、その後散歩に出ました。","afterward はその後という副詞。after dinner の after と違い、直後に出来事の名詞を続けません。"],
    ["nearly","The bottle is nearly empty.","瓶はほとんど空です。","nearly はほぼその状態だが完全ではないこと。near は近いという意味なので品詞と意味を区別します。"],
    ["therefore","The road was closed; therefore, we took another route.","道が閉鎖されていたので、別の道を通りました。","therefore はそれゆえという副詞。because のように理由の節を導く接続詞ではありません。"],
    ["exactly","The train arrived exactly on time.","電車はちょうど定刻に着きました。","exactly はずれがないことを強調。会話の Exactly. は『そのとおり』という同意にも使います。"],
    ["possibly","We could possibly finish today.","ひょっとすると今日終えられるかもしれません。","possibly は可能性を控えめに述べる副詞。必ずそうなるという確実さは示しません。"],
    ["contrary","Contrary to our expectations, it was sunny.","予想に反して晴れていました。","contrary to は〜に反して。on the contrary は直前の主張を否定して逆を言う表現です。"],
    ["occasionally","I occasionally walk to work.","私はときどき歩いて通勤します。","occasionally はときどきという頻度の副詞。通常は一般動詞の前などに置けます。"],
    ["somehow","Somehow, we managed to finish on time.","どうにか私たちは時間内に終えられました。","somehow は方法が明確でないまま『どうにか』、理由が不明なら『なぜか』と訳せます。"],
    ["seldom","She seldom watches television.","彼女はめったにテレビを見ません。","seldom 自体に否定的な意味があるため、この意味で not seldom としないようにします。"],
    ["thus","The price fell, thus attracting more buyers.","価格が下がり、その結果、より多くの買い手を引きつけました。","thus は結果として・このようにという副詞。やや改まった文章で使われます。"],
    ["throughout","It rained throughout the night.","夜通し雨が降りました。","throughout は期間の最初から最後まで、または場所の至る所にという全体を表します。"],
    ["unlike","Unlike his brother, he enjoys cooking.","兄とは違って、彼は料理を楽しみます。","unlike の後ろには名詞などを置きます。この例は『好きではない』ではなく『〜と違って』です。"],
    ["besides","Besides English, she speaks Spanish.","英語に加えて、彼女はスペイン語も話します。","besides は追加。beside はそばにという位置で、末尾の s の有無で意味が変わります。"],
    ["beyond","The village is beyond the river.","村は川の向こうにあります。","beyond は境界を越えた先。beyond my understanding は理解の範囲を超えていることです。"],
    ["within","Please reply within three days.","3日以内に返答してください。","within は期限の内側。in three days は通常3日後なので、期限との違いを確認します。"],
    ["nor","He neither called nor wrote.","彼は電話も手紙もしませんでした。","neither A nor B はAもBもないこと。並べる語の形を called と wrote のようにそろえます。"],
    ["unless","We will go unless it rains.","雨が降らない限り行きます。","unless はif notに近い条件。未来の条件でもこの例の節内では rains と現在形を使います。"],
    ["except","Everyone came except Ken.","ケン以外は全員来ました。","except は集合から除くこと。besides Ken ならケンに加えて、という追加の意味になります。"],
    ["ought","You ought to check the address.","住所を確認したほうがよいです。","ought to + 動詞の原形で助言や義務を表します。ought の後ろの to を忘れないようにします。"],
    ["in spite of","We went out in spite of the rain.","雨にもかかわらず外出しました。","in spite of の後ろは名詞や動名詞。文をそのまま続けるなら although it was raining などを使います。"],
    ["whether","I do not know whether she will come.","彼女が来るかどうか分かりません。","whether は2つの可能性を示します。whether to go のように不定詞を続ける形もあります。"],
    ["explain","Please explain the rule to me.","その規則を私に説明してください。","explain 物 to 人の順番。explain me the rule とは通常しません。"],
    ["accept","She accepted the invitation.","彼女は招待を受けました。","accept は受け入れる意思を含みます。receive は届く・受け取ることで、受諾したかは別です。"],
    ["produce","The farm produces cheese.","その農場はチーズを生産しています。","動詞 produce は生産すること。名詞の produce は農産物を指し、強勢の位置も変わります。"],
    ["exist","This species exists only on the island.","この種はその島だけに存在します。","exist は存在するという自動詞。is existed のような受け身には通常しません。"],
    ["express","He expressed his gratitude in a letter.","彼は手紙で感謝を表しました。","express の後ろには表す気持ちや意見を直接置きます。expression は表現・表情という名詞です。"],
    ["add","Add a little salt to the soup.","スープに少し塩を加えてください。","add A to B はAをBに加える形。add up は合計する意味です。"],
    ["avoid","Avoid touching the wet paint.","塗りたてのペンキに触れないでください。","avoid doing の形。avoid to touch とはしません。避ける対象が名詞なら直接置けます。"],
    ["marry","She married her college friend.","彼女は大学時代の友人と結婚しました。","marry 人は直接目的語を置きます。be married to 人なら結婚している状態です。"],
    ["protect","This coat protects you from the wind.","このコートは風から身を守ります。","protect A from B はBからAを守る形。何を何から守るかを確認します。"],
    ["affect","The weather affected our plans.","天候は私たちの計画に影響しました。","affect は通常動詞。an effect on our plans の effect は通常名詞で、綴りと働きが違います。"],
    ["determine","The test will determine the winner.","その試験によって勝者が決まります。","determine は決定する・明らかにすること。be determined to do は固く決意している状態です。"],
    ["solve","We solved the problem together.","私たちは一緒に問題を解決しました。","solve は解決に至ること。discuss a problem は議論するだけで、解決したとは限りません。"],
    ["contain","This box contains old photographs.","この箱には古い写真が入っています。","contain は中に含むこと。include は全体の一部として含めることに焦点があります。"],
    ["discuss","We discussed the plan after lunch.","私たちは昼食後に計画について話し合いました。","discuss の直後に話題を置きます。discuss about the plan とは通常しません。"],
    ["ignore","Do not ignore the warning.","その警告を無視しないでください。","ignore は注意を向けない・取り合わないこと。知らなかったことを表す not know とは違います。"],
    ["guess","Can you guess the answer?","答えを推測できますか。","guess は十分な情報がないまま推測すること。測定・検証した答えとは区別します。"],
    ["exchange","They exchanged phone numbers.","彼らは電話番号を交換しました。","exchange A for B はAをBと交換する形。ここではお互いの番号を渡し合っています。"],
    ["satisfy","The explanation did not satisfy me.","その説明では私は納得できませんでした。","satisfy 人は人を満足させること。be satisfied with は何に満足しているかを示します。"],
    ["complain","He complained about the noise.","彼は騒音に苦情を言いました。","complain about 事柄、complain to 人の形。complaint は苦情という名詞です。"],
    ["achieve","She achieved her goal.","彼女は目標を達成しました。","achieve は目標などを実現すること。try to achieve は達成を目指すだけで結果は未確定です。"],
    ["enable","The app enables users to share notes.","そのアプリは利用者がノートを共有できるようにします。","enable 人 to do で人の行動を可能にします。enable doing よりこの文型を基本に覚えます。"],
    ["intend","I intend to study abroad.","私は留学するつもりです。","intend to do は意図・予定を示します。実際に実行したことまでは意味しません。"],
    ["obtain","You must obtain permission first.","まず許可を得る必要があります。","obtain は得るという改まった語。許可や情報を取得する文脈でよく使います。"],
    ["divide","Divide the cake into six pieces.","ケーキを6つに分けてください。","divide A into B は分割した結果を示します。divide by three は数学で3で割ることです。"],
    ["annoy","The constant noise annoyed me.","絶え間ない騒音にいらいらしました。","annoyed は人の気持ち、annoying はいらいらさせる物事の性質です。"],
    ["differ","The two methods differ in cost.","その2つの方法は費用の点で異なります。","differ in は異なる点、differ from は比較相手を示します。different は形容詞です。"],
    ["educate","The program educates children about recycling.","その活動は子どもたちにリサイクルについて教えます。","educate 人 about 事柄の形。education は教育という名詞です。"],
    ["borrow","May I borrow your pen?","ペンを借りてもよいですか。","borrow は借りる側、lend は貸す側の動作。借りる相手には from を使います。"],
    ["invent","She invented a new tool.","彼女は新しい道具を発明しました。","invent は新しく作り出すこと。discover はすでにあるものを見つけることです。"],
    ["promote","The campaign promotes healthy eating.","その運動は健康的な食生活を促進します。","promote は促進すること。promote 人 to 役職なら人を昇進させる意味になります。"],
    ["advise","She advised me to take a break.","彼女は私に休憩するよう助言しました。","advise 人 to do の形。名詞は advice で、通常数えない名詞です。"],
    ["retire","He retired from teaching last year.","彼は昨年、教職を退きました。","retire from は仕事などから引退すること。一時的に作業をやめる stop と区別します。"],
    ["permit","They do not permit visitors to take photographs.","そこでは訪問者の写真撮影を許可していません。","permit 人 to do の形。人を置かない permit taking photographs も使えます。"],
    ["recommend","I recommend booking early.","早めの予約をお勧めします。","recommend doing は行動を勧める形。recommend to book と単純に不定詞を続けないようにします。"],
    ["apologize","I apologized to her for the mistake.","私はその間違いについて彼女に謝りました。","apologize to 人 for 事柄。謝る相手と理由を異なる前置詞で示します。"],
    ["inform","Please inform us of any changes.","変更があれば知らせてください。","inform 人 of 事柄で知らせる内容を示します。inform 人 that ... と文を続けることもできます。"],
    ["oppose","Many residents opposed the plan.","多くの住民がその計画に反対しました。","oppose は直接目的語を置きます。be opposed to the plan は反対している状態です。"],
    ["trust","I trust her judgment.","私は彼女の判断を信頼しています。","trust は人や判断を信用すること。trustworthy は信頼できるという形容詞です。"],
    ["select","Please select one answer.","答えを1つ選んでください。","select は候補の中から選ぶこと。selection は選択や選ばれたものを表す名詞です。"],
    ["praise","The teacher praised him for his effort.","先生は彼の努力をほめました。","praise 人 for 事柄の形。praise は名詞でも使え、その場合は通常数えません。"],
    ["handle","She handled the complaint calmly.","彼女は苦情に冷静に対処しました。","handle は扱う・対処すること。名詞なら a door handle のように取っ手を意味します。"],
    ["propose","He proposed changing the schedule.","彼は予定を変更することを提案しました。","propose doing は行動の提案。propose to do は自分の意図を示す場合もあり、形による違いに注意します。"],
    ["breathe","Breathe slowly and relax.","ゆっくり呼吸して、力を抜いてください。","breathe は呼吸する動詞。breath は息という名詞で、末尾の e と発音が違います。"],
    ["criticize","They criticized the decision.","彼らはその決定を批判しました。","criticize は問題点を指摘・批判すること。criticize 人 for doing は行動を理由に批判する形です。"],
    ["overcome","She overcame her fear of speaking.","彼女は話すことへの恐怖を克服しました。","活用は overcome–overcame–overcome。困難を実際に乗り越える意味を持ちます。"],
    ["possess","He possesses valuable experience.","彼には貴重な経験があります。","possess は所有・保有するという改まった語。日常の所有には have や own も使います。"],
    ["predict","It is difficult to predict the result.","結果を予測するのは難しいです。","predict は将来を予測すること。予測が必ず当たるとは限らず、prediction が名詞形です。"],
    ["publish","The report was published in June.","その報告書は6月に公表されました。","publish は本の出版だけでなく、報告や情報を一般に公表することにも使います。"],
    ["floating","We saw a floating leaf on the water.","私たちは水面に浮かぶ葉を見ました。","floating は float の -ing 形。この例では leaf を修飾し、浮いている状態を表します。"],
    ["recall","I cannot recall his name.","彼の名前を思い出せません。","recall は記憶から思い出すこと。recall meeting him のように過去の経験には動名詞を使えます。"],
    ["explore","We explored the old town on foot.","私たちは歩いて旧市街を見て回りました。","explore の直後に探索する場所を置きます。explore an idea なら考えを詳しく検討する意味です。"],
    ["pretend","He pretended to be asleep.","彼は眠っているふりをしました。","pretend to do は行動や状態を装う形。pretend that ... と文を続けることもできます。"],
    ["absorb","The towel absorbed the water.","タオルが水を吸収しました。","absorb は物質や情報を取り込むこと。be absorbed in a book は読書に夢中な状態です。"],
    ["resemble","She resembles her mother.","彼女は母親に似ています。","resemble の直後に似ている相手を置き、resemble to とは通常しません。look like と文型を区別します。"],
    ["tear","Be careful not to tear the paper.","紙を破らないよう気をつけてください。","動詞は tear–tore–torn。涙という名詞の tear とは同じ綴りでも発音が異なります。"],
    ["consume","This machine consumes little electricity.","この機械は電力をあまり消費しません。","consume は資源・時間などを消費すること。食べ物を摂取する意味もあります。"],
    ["compete","Teams from ten schools competed in the event.","10校のチームがその大会で競いました。","compete in は競技、compete with は相手、compete for は求める賞などを示します。"],
    ["quit","He quit smoking last year.","彼は昨年たばこをやめました。","quit doing の形。quit to smoke ではありません。仕事などを辞める意味にも使います。"],
    ["announce","They announced the results this morning.","彼らは今朝、結果を発表しました。","announce 物 to 人の形で発表先を示せます。announce 人 物としないようにします。"],
    ["react","How did she react to the news?","彼女はその知らせにどう反応しましたか。","react to は反応する対象を示します。reaction は反応という名詞です。"],
    ["wander","We wandered around the market.","私たちは市場をぶらぶら歩きました。","wander は決まった目的地なしに歩き回ること。wonder（疑問に思う）と綴りも発音も違います。"],
    ["text","Please text me when you arrive.","着いたら私にメッセージを送ってください。","text は携帯などで短い文字メッセージを送る動詞。電子メールの email と必ずしも同じではありません。"],
    ["generate","The panels generate electricity.","そのパネルは電気を生み出します。","generate はエネルギー・利益・関心などを生み出すこと。generator は発電機などを指します。"],
    ["score","She scored ten points.","彼女は10点取りました。","score は得点する動詞。名詞の a high score は高得点を表します。"],
    ["government","The government announced a new policy.","政府は新しい政策を発表しました。","government は統治を行う組織。govern は統治するという動詞です。"],
    ["knowledge","He has a good knowledge of history.","彼は歴史に詳しいです。","knowledge は通常数えない名詞。a good knowledge of のように形容詞を伴う決まった使い方もあります。"],
    ["nation","Athletes from many nations took part.","多くの国の選手が参加しました。","nation は国や国民というまとまり。national は国の・全国のという形容詞です。"],
    ["effort","Learning a language takes effort.","言語の習得には努力が必要です。","make an effort to do は行動するために努力すること。努力一般は数えずに表す場合もあります。"],
    ["period","The museum focuses on this historical period.","その博物館はこの歴史的時代を中心に扱っています。","period は一定の期間や時代。a period of three years なら3年間というまとまりです。"],
    ["population","The town has a population of twenty thousand.","その町の人口は2万人です。","人口の多さは large population、少なさは small population。人数そのものを尋ねるなら What is the population? と言えます。"],
    ["purpose","What is the purpose of this exercise?","この練習の目的は何ですか。","purpose は目的。on purpose は意図的にという表現で、目的地を表す語ではありません。"],
    ["behavior","His behavior surprised us.","彼の行動は私たちを驚かせました。","behavior は通常数えない名詞。個々の行為を数えるなら actions などを使えます。"],
    ["lack","The project failed because of a lack of funds.","資金不足でその計画は失敗しました。","a lack of は〜の不足。動詞では We lack funds. のように of を付けません。"],
    ["skill","Cooking is a useful skill.","料理は役立つ技能です。","skill は練習などで身につける技能。a skill と数える用法と、熟練一般を数えず表す用法があります。"],
    ["quality","The quality of the paper is excellent.","紙の品質はすばらしいです。","quality は質。量を表す quantity と区別します。personal qualities は人の資質を表します。"],
    ["environment","Plants need the right environment to grow.","植物の成長には適切な環境が必要です。","environment は周囲の条件全体。自然環境だけでなく a working environment（職場環境）にも使います。"],
    ["role","Teachers play an important role in society.","教師は社会で重要な役割を果たします。","play a role in は〜で役割を果たすこと。role と roll（転がる）は同音ですが別の語です。"],
    ["attitude","Her attitude toward work is positive.","彼女は仕事に前向きな姿勢を持っています。","attitude toward はある対象への考え方・態度。身体の姿勢だけを意味する語ではありません。"],
    ["author","Who is the author of this book?","この本の著者は誰ですか。","author は作品を書いた人。writer よりも特定の作品との関係を示して使われることが多い語です。"],
    ["research","She is doing research on birds.","彼女は鳥について研究しています。","research は通常数えない名詞。do research と言い、a research とは普通しません。"],
    ["opportunity","I had an opportunity to speak with her.","彼女と話す機会がありました。","an opportunity to do は行動できる機会。chance も近い意味ですが、確率を表す場合もあります。"],
    ["source","The river is a source of water for the town.","その川は町の水源です。","source は物や情報の出どころ。ソースという調味料の sauce とは綴りが違います。"],
    ["carbon","Carbon is found in all living things.","炭素はすべての生物に含まれています。","carbon は元素の炭素。carbon dioxide は二酸化炭素で、炭素そのものとは別の物質です。"],
    ["shape","The table is round in shape.","そのテーブルは丸い形です。","shape は形。in good shape はよい状態であることを表し、人の体調にも使います。"],
    ["advantage","Living near the station has many advantages.","駅の近くに住むことには多くの利点があります。","an advantage over は相手より有利な点。take advantage of は機会などを利用することです。"],
    ["method","We tried a different method of teaching.","私たちは別の教え方を試しました。","a method of doing は〜する方法。method は一定の手順を持つ方法に使われます。"],
    ["habit","Reading before bed is a good habit.","寝る前の読書はよい習慣です。","habit は個人が繰り返す習慣。地域や社会の慣習を表す custom と区別します。"],
    ["detail","Please explain the plan in detail.","その計画を詳しく説明してください。","in detail は詳しくという決まった表現。the details は具体的な細部を複数で表します。"],
    ["distance","What is the distance between the two stations?","その2つの駅の距離はどれくらいですか。","distance between A and B はAとBの間の距離。in the distance は遠くにという表現です。"],
    ["crowd","A large crowd gathered in the square.","広場に大勢の人が集まりました。","crowd は集まった人々のまとまり。crowded は混雑しているという形容詞です。"],
    ["instance","Some fruits, for instance apples, keep well.","リンゴなど、日持ちする果物もあります。","for instance は例えば。an instance of はある出来事の一例を表します。"],
    ["desire","She has a strong desire to travel.","彼女は旅行したいと強く望んでいます。","a desire to do は〜したいという願望。want より改まった響きを持つ語です。"],
    ["standard","The hotel maintains a high standard of service.","そのホテルは高水準のサービスを維持しています。","standard は評価の基準・水準。形容詞では標準的な、という意味になります。"],
    ["task","Our first task is to clean the room.","最初の仕事は部屋を掃除することです。","task は具体的な1つの作業。仕事全般を表す work は通常数えません。"],
    ["generation","Each generation faces different challenges.","世代ごとに異なる課題に直面します。","generation は同時代に生まれ育った人々。electricity generation では電力の生成を表します。"],
    ["responsibility","She took responsibility for the mistake.","彼女はその間違いの責任を引き受けました。","take responsibility for は〜の責任を持つこと。responsible for は形容詞を使った形です。"],
    ["experiment","We conducted an experiment in class.","私たちは授業で実験をしました。","conduct an experiment は実験を行うこと。experience（経験）と綴り・意味を区別します。"],
    ["athlete","The athletes trained every morning.","選手たちは毎朝練習しました。","athlete は競技をする選手。athletic は運動の・運動能力が高いという形容詞です。"],
    ["decade","The town has changed over the past decade.","町はこの10年間で変わりました。","a decade は10年間。a century は100年間、a millennium は1000年間です。"],
    ["loss","The company reported a financial loss.","その会社は損失を報告しました。","loss は失うこと・損失。lose が動詞、lost がその過去形・過去分詞です。"],
    ["fever","He had a fever yesterday.","彼は昨日熱がありました。","have a fever は発熱していること。暑い天候そのものを fever とは言いません。"],
    ["theory","The experiment supports the theory.","その実験は理論を裏付けています。","theory は説明の体系。日常では推測を指すこともありますが、科学の理論を単なる思いつきと同一視しないようにします。"],
    ["statement","The company issued a statement.","その会社は声明を出しました。","statement は述べられた内容・声明。state は動詞で述べるという意味にもなります。"],
    ["professor","The professor teaches chemistry.","その教授は化学を教えています。","professor は主に大学の教員の職位。すべての学校の先生を指す teacher とは範囲が違います。"],
    ["function","What is the function of this button?","このボタンの機能は何ですか。","function は機能・役割。動詞の function properly は正常に機能することです。"],
    ["surface","Leaves floated on the surface of the pond.","葉が池の表面に浮いていました。","surface は物の外側や上面。on the surface は表面的には、という比喩にも使います。"],
    ["envelope","Put the letter in an envelope.","手紙を封筒に入れてください。","envelope は封筒。envelop は包むという動詞で、末尾の e と発音の違いに注意します。"],
    ["organization","She works for an international organization.","彼女は国際機関で働いています。","organization は組織・団体。物事を整理することを表す場合には通常数えません。"],
    ["policy","The school has a clear policy on phones.","その学校には携帯電話に関する明確な方針があります。","policy は政府の政策だけでなく、学校や会社の方針。政治一般を指す politics とは違います。"],
    ["resource","Water is a valuable resource.","水は貴重な資源です。","resource は目的に使える資源・手段。learning resources は教材などの学習資源です。"],
    ["contrast","There is a sharp contrast between the two pictures.","その2枚の写真には際立った対照があります。","contrast between A and B は両者の相違。in contrast は対照的にという表現です。"],
    ["flood","The flood damaged many houses.","洪水で多くの家が被害を受けました。","flood は洪水。動詞なら The river flooded. と川が氾濫したことを表せます。"],
    ["mate","The bird called to its mate.","鳥はつがいの相手に鳴きかけました。","mate は仲間・つがいの相手。classmate は同級生、teammate は同じチームの仲間です。"],
    ["goods","The shop sells household goods.","その店は家庭用品を売っています。","商品という意味の goods は複数形で扱います。形容詞 good（よい）と混同しないようにします。"],
    ["creature","We saw tiny creatures in the pond.","私たちは池で小さな生き物を見ました。","creature は生き物。実在の動物だけでなく、物語の架空の生物にも使えます。"],
    ["structure","We studied the structure of the bridge.","私たちは橋の構造を調べました。","structure は部分の組み立て方・構造物。文の構造にも使います。"],
    ["tradition","The festival is a local tradition.","その祭りは地元の伝統です。","tradition は受け継がれる慣行。traditional は伝統的なという形容詞です。"],
    ["weight","The bridge has a weight limit.","その橋には重量制限があります。","weight は重さという名詞。weigh は重さがある・量るという動詞です。"],
    ["charity","They donated the money to charity.","彼らはそのお金を慈善活動に寄付しました。","charity は慈善活動。a charity と数えると慈善団体を指します。"],
    ["citizen","Every citizen has rights and responsibilities.","すべての市民に権利と責任があります。","citizen は市民・国民。resident は住民で、その国の国籍を持つとは限りません。"],
    ["impression","She made a good impression on the team.","彼女はチームによい印象を与えました。","make an impression on は〜に印象を与えること。最初の印象は first impression です。"],
    ["cartoon","The children watched a cartoon.","子どもたちはアニメを見ました。","cartoon はアニメや風刺画など。日本語の漫画全般と完全に同じ範囲ではありません。"],
    ["career","She began her career as a journalist.","彼女は記者として仕事の経歴を始めました。","career は職業生活全体や経歴。1つの職や作業を指す job と区別します。"],
    ["site","The building site is near the river.","建設現場は川の近くです。","site は特定の目的・出来事の場所。ウェブサイトにも使い、sight（光景）とは別語です。"],
    ["passenger","All passengers must show their tickets.","乗客は全員、切符を見せなければなりません。","passenger は乗り物で運ばれる人。通常、運転手や乗務員は含めません。"],
    ["violence","The film contains scenes of violence.","その映画には暴力の場面があります。","violence は通常数えない名詞。violent は暴力的な・激しいという形容詞です。"],
    ["income","Her monthly income has increased.","彼女の月収は増えました。","income は入ってくる収入全体。salary は定期的な給与、profit は費用を引いた利益です。"],
    ["temperature","The temperature dropped overnight.","一晩で気温が下がりました。","temperature は温度・気温。a high temperature は文脈により体温が高いことも表します。"],
    ["majority","The majority of students agreed.","生徒の過半数が賛成しました。","majority は半分を超える多数。必ず圧倒的大多数とは限らないため、文脈の人数を確認します。"],
    ["origin","We discussed the origin of the word.","私たちはその単語の起源について話しました。","origin は始まり・由来。country of origin は原産国や出身国を示します。"],
    ["literature","She studies Japanese literature.","彼女は日本文学を研究しています。","literature は文学。研究文献という意味でも使われ、通常数えない名詞です。"],
    ["equipment","The laboratory needs new equipment.","その実験室には新しい設備が必要です。","equipment は通常数えません。1点なら a piece of equipment と言います。"],
    ["stranger","A stranger asked me for directions.","知らない人に道を尋ねられました。","stranger は面識のない人。外国人という意味に限定されない点に注意します。"],
    ["strength","The bridge was tested for strength.","橋の強度が検査されました。","strength は強さ。a person's strengths と複数形にすると、その人の長所を表します。"],
    ["planet","Earth is a planet.","地球は惑星です。","planet は惑星。自ら光を出す恒星 star や衛星 moon と区別します。"],
    ["fiction","She enjoys reading science fiction.","彼女はSFを読むのが好きです。","fiction は創作の物語全般。小説1冊を数えるなら a novel などを使います。"],
    ["religion","The course explores different religions.","その講座はさまざまな宗教を扱います。","religion は宗教一般、a religion は個別の宗教。religious は宗教の・信心深いという形容詞です。"],
    ["pollution","Air pollution is a concern in the city.","その都市では大気汚染が懸念されています。","pollution は通常数えない名詞。pollute が汚染する動詞、pollutant は汚染物質です。"],
    ["wealth","The country has a wealth of natural resources.","その国には豊富な天然資源があります。","wealth は富。a wealth of は大量の・豊富なというまとまりで使います。"],
    ["document","Please sign this document.","この文書に署名してください。","document は記録された文書。紙だけでなく電子ファイルにも使います。"],
    ["profit","The company made a small profit.","その会社は少し利益を出しました。","profit は売上から費用を引いた利益。sales（売上）と同じではありません。"],
    ["technique","She taught us a new painting technique.","彼女は新しい絵の技法を教えてくれました。","technique は具体的な技法・手順。technology は技術体系、skill は身につけた技能です。"],
    ["emotion","His voice showed little emotion.","彼の声にはあまり感情が表れていませんでした。","emotion は感情一般。emotions と複数形なら喜び・怒りなど複数の感情を指せます。"],
    ["phenomenon","The rainbow is a natural phenomenon.","虹は自然現象です。","phenomenon は単数形。複数形は phenomena で、語尾の変化に注意します。"],
    ["horror","She stared at the damage in horror.","彼女は恐怖にかられて被害を見つめました。","in horror は恐怖を感じてという表現。horror films は恐怖を題材にした映画です。"],
    ["ladder","He climbed the ladder carefully.","彼は慎重にはしごを登りました。","ladder ははしご。階段 stairs や段差 step と区別します。"],
    ["billion","The project cost one billion yen.","その計画には10億円かかりました。","現代の通常の英語で billion は10億。数の後ろでは two billion のように s を付けません。"],
    ["status","You can check the status of your order online.","注文の状況をオンラインで確認できます。","status は地位だけでなく現在の状態。social status なら社会的地位です。"],
    ["youth","He spent his youth in the countryside.","彼は若い時期を田舎で過ごしました。","youth は青春期・若さ。若者全体を表すこともあり、a youth は若者1人を指します。"],
    ["confidence","Practice gave her confidence.","練習で彼女は自信を得ました。","confidence in は人や能力への信頼。confident は自信を持っているという形容詞です。"],
    ["edge","Do not stand near the edge of the platform.","ホームの端の近くに立たないでください。","edge は端・縁。周辺一般より、物や範囲の境界を意識する語です。"],
    ["household","Each household received a letter.","各世帯に手紙が届きました。","household は同じ家で暮らす世帯。必ず血縁のある家族 family と同じとは限りません。"],
    ["scholar","She is a scholar of ancient history.","彼女は古代史の研究者です。","scholar は学問の研究者。奨学金を受ける学生を指す用法もあります。"],
    ["survey","We conducted a survey of local residents.","私たちは地域住民への調査を行いました。","conduct a survey は調査を実施すること。questionnaire は質問票そのものを表します。"],
    ["vocabulary","Reading helps build vocabulary.","読書は語彙を増やす助けになります。","vocabulary は知っている語の集合。単語1つを言うときは a word を使います。"],
    ["enemy","The two countries were once enemies.","その2か国はかつて敵同士でした。","enemy は敵対する相手。競技上の対戦相手 opponent が必ず enemy とは限りません。"],
    ["construction","The bridge is under construction.","その橋は建設中です。","under construction は建設中・作成中。construction は文章などの組み立ても表せます。"],
    ["lecture","We attended a lecture on history.","私たちは歴史の講義に出席しました。","a lecture on はある話題の講義。attend a lecture の attend に前置詞は不要です。"],
    ["instruction","Read the instructions before using the machine.","機械を使う前に説明書の指示を読んでください。","手順の指示は instructions と複数形がよく使われます。instruction は指導一般を表すこともあります。"],
    ["crisis","The company faced a serious crisis.","その会社は深刻な危機に直面しました。","crisis は単数形、複数形は crises。critical は重大な・危機的なという形容詞です。"],
    ["instrument","She plays a musical instrument.","彼女は楽器を演奏します。","instrument は目的に使う器具。musical instrument は楽器、measuring instrument は測定器です。"],
    ["crop","The farmers harvested their crops.","農家は作物を収穫しました。","crop は栽培される作物や収穫物。植物すべてを表す plant より意味が限定されます。"],
    ["weapon","The museum displays ancient weapons.","その博物館は古代の武器を展示しています。","weapon は攻撃や防御に使う武器。特定の形や種類に限らない総称です。"],
    ["device","This device measures temperature.","この装置は温度を測ります。","device は目的を持つ装置。devise は考案する動詞で、綴りと語尾の音が違います。"],
    ["path","Follow the path through the woods.","林を通る小道を進んでください。","path は小道・進路。a path to success は成功への道筋という比喩です。"],
    ["earthquake","The earthquake shook the city.","地震がその都市を揺らしました。","earthquake は地震。earth は地球・地面、quake は揺れることを表します。"],
    ["stream","A small stream runs behind the house.","家の裏に小川が流れています。","stream は小川や流れ。a stream of visitors は途切れず続く訪問者の流れです。"],
    ["notion","I had no notion of how difficult it would be.","それがどれほど難しいか、私は見当もつきませんでした。","notion は考え・概念。必ず裏付けのある理論を意味するわけではありません。"],
    ["yard","The children played in the yard.","子どもたちは庭で遊びました。","yard は家の周囲の敷地。長さの単位としては1ヤード＝0.9144メートルです。"],
    ["victim","The flood victims needed clean water.","洪水の被災者たちはきれいな水を必要としていた。","victim は犯罪・災害などで被害を受けた人。必ずしも亡くなった人ではなく、a victim of fraud なら『詐欺の被害者』を表す。"],
    ["fuel","The bus uses less fuel than the old model.","そのバスは旧型より少ない燃料で走る。","燃料をまとめて指す fuel は通常数えない。動詞では fuel an argument のように『議論をあおる』という比喩的な使い方もある。"],
    ["ancestor","My ancestors lived near this river.","私の先祖はこの川の近くに住んでいた。","ancestor は何世代も前の先祖を指す数えられる名詞。子孫は descendant で、家族のつながりを逆向きに表す。"],
    ["soil","This soil is too dry for the plants.","この土壌はその植物には乾燥しすぎている。","植物が育つ地面の土を soil と呼ぶ。土を素材として述べるときは通常数えず、a soil とせずに rich soil『肥沃な土』などと言う。"],
    ["debate","We had a debate about school uniforms.","私たちは学校の制服について討論した。","have a debate about ... で『～について討論する』。動詞なら debate the issue のように、議論の対象を直接続けられる。"],
    ["crime","The police are investigating the crime.","警察はその犯罪を捜査している。","個々の犯罪は a crime、犯罪全般は crime と表す。commit a crime で『罪を犯す』という組み合わせになる。"],
    ["colleague","I asked a colleague to check the report.","私は同僚に報告書を確認してもらった。","colleague は仕事上の同僚。同じ職場や専門分野で働く相手を指し、学校の同級生を表す classmate とは区別する。"],
    ["shelf","Put the dictionary on the top shelf.","辞書をいちばん上の棚に置いてください。","棚の板・段を数える名詞で、複数形は shelves。棚の上にある物には on the shelf を使う。"],
    ["analysis","The analysis revealed a change in sales.","その分析によって売上の変化が明らかになった。","analysis は分析という行為やその結果。複数形は analyses で、動詞 analyze『分析する』と形を混同しないようにする。"],
    ["universe","We still have many questions about the universe.","宇宙について、私たちにはまだ多くの疑問がある。","宇宙全体を指すときは通常 the universe。space は『宇宙空間』という意味では無冠詞で使われることが多い。"],
    ["electricity","The storm cut off the electricity.","嵐によって電気の供給が止まった。","electricity は通常数えない名詞。save electricity は『節電する』、generate electricity は『発電する』を表す。"],
    ["insect","A small insect landed on my notebook.","小さな昆虫が私のノートにとまった。","insect は数えられる名詞で、母音の音で始まるため an insect。spider『クモ』は生物学的には昆虫ではない。"],
    ["web","A spider built a web between the branches.","クモが枝と枝の間に巣を作った。","クモの巣は a web または a spider's web。the web と言うと、インターネット上のウェブを指す場合もある。"],
    ["storm","We stayed indoors during the storm.","嵐の間、私たちは屋内にいた。","storm は強い風や雨などを伴う荒天。during the storm の during は出来事の間を表し、その後には名詞を置く。"],
    ["plenty","We have plenty of time before the train leaves.","電車が出るまでには十分な時間がある。","plenty of の後には time のような数えない名詞も、chairs のような複数名詞も置ける。『不足なく、たっぷり』という感覚。"],
    ["agriculture","Agriculture is an important industry in this region.","農業はこの地域の重要な産業だ。","agriculture は農業を指す通常数えない名詞。形容詞 agricultural を使えば agricultural products『農産物』となる。"],
    ["gene","This gene affects the color of the flowers.","この遺伝子は花の色に影響する。","gene は遺伝子を表す数えられる名詞。『遺伝的な』は genetic で、gene information ではなく genetic information という組み合わせが一般的。"],
    ["evidence","We need more evidence to support that claim.","その主張を裏づけるには、もっと証拠が必要だ。","evidence は通常数えない。証拠を一つと数えるなら a piece of evidence を使い、an evidence とはしない。"],
    ["consequence","Missing the deadline may have serious consequences.","締め切りに遅れると、重大な結果を招くかもしれない。","consequence は行動などから生じる結果で、特に悪い結果によく使う。as a consequence of ... は『～の結果として』。"],
    ["infant","The infant fell asleep in her father's arms.","その赤ちゃんは父親の腕の中で眠りについた。","infant は特に乳児やごく幼い子を指す、baby より改まった語。歩き始めた幼児を表す toddler よりも幼い子を指すことが多い。"],
    ["leisure","I enjoy reading in my leisure time.","私は余暇に読書を楽しむ。","leisure は仕事や義務から離れた自由な時間。leisure time『余暇』、leisure activities『余暇の活動』という組み合わせで覚える。"],
    ["cell","We examined a plant cell under a microscope.","私たちは顕微鏡で植物の細胞を観察した。","生物の細胞という意味の cell は数えられる。別の文脈では『独房』など、小さく区切られた部屋を表すこともある。"],
    ["talent","She has a talent for explaining difficult ideas.","彼女には難しい考えを説明する才能がある。","a talent for ... で『～の才能』。for の後に動作を置く場合は explaining のような -ing 形にする。"],
    ["advertising","The company spends a lot on online advertising.","その会社はオンライン広告に多くのお金を使っている。","advertising は広告活動全般を表す通常数えない名詞。一つ一つの広告は an advertisement や an ad と表す。"],
    ["extent","I agree with you to some extent.","私はある程度あなたに賛成だ。","to some extent は『ある程度』という定型表現。全面的な賛成ではないことを示せる。to what extent は『どの程度まで』。"],
    ["garbage","Please put the garbage in the bin.","ごみをそのごみ箱に入れてください。","garbage は主にアメリカ英語で使う、通常数えない名詞。『ごみ一袋』なら a bag of garbage と容器で量を表す。"],
    ["general","The guide gives a general introduction to the topic.","そのガイドはその話題の全般的な紹介をしている。","general は細部より全体に関わる『一般的な・全般的な』。in general は『一般に』という副詞的な表現になる。"],
    ["various","Students offered various solutions to the problem.","生徒たちはその問題に対してさまざまな解決策を示した。","various は『いろいろな種類の』という形容詞で、通常は複数名詞を修飾する。very のように形容詞を強める語ではない。"],
    ["similar","Your bag is similar to mine.","あなたのかばんは私のものに似ている。","be similar to ... で『～に似ている』。比較対象の前は to を使う。same『同じ』と違い、完全に一致している必要はない。"],
    ["complete","We need a complete list of the guests.","私たちは来客全員の一覧が必要だ。","形容詞 complete は『欠けた部分のない』。動詞として使うと complete the form『用紙への記入を完成させる』という意味になる。"],
    ["sharp","There was a sharp rise in electricity prices.","電気料金が急激に上昇した。","sharp は刃物の『鋭い』だけでなく、変化の『急激な』にも使う。a sharp rise と a sharp fall を対で覚えると便利。"],
    ["expensive","This coat is too expensive for me.","このコートは私には高すぎる。","物の値段が高いときは expensive を使う。price 自体を主語にするなら The price is high. と表すのが自然。"],
    ["political","They discussed the political situation in the country.","彼らはその国の政治情勢について話し合った。","political は名詞を修飾する『政治の・政治的な』。政治そのものは politics、政治家は politician と形が変わる。"],
    ["aware","Are you aware of the change in the schedule?","予定の変更を知っていますか。","be aware of + 名詞で『～を知っている・気づいている』。内容を文で続けるなら be aware that ... を使う。"],
    ["ancient","We visited the ruins of an ancient city.","私たちは古代都市の遺跡を訪れた。","ancient は非常に古い時代、特に古代に関係する語。単に少し古い物には old を使い、ancient と区別する。"],
    ["medical","The village needs better medical services.","その村には、よりよい医療サービスが必要だ。","medical は『医学の・医療の』という形容詞。medical care『医療』、medical school『医学部・医学校』などで使う。"],
    ["essential","Clean water is essential for daily life.","きれいな水は日常生活に不可欠だ。","be essential for ... で『～に不可欠である』。単に便利という意味ではなく、なくてはならない重要性を表す。"],
    ["huge","A huge crowd gathered outside the stadium.","大勢の人がスタジアムの外に集まった。","huge は big より強い『非常に大きい』。物理的な大きさ以外にも a huge difference『大きな違い』のように使える。"],
    ["terrible","We had terrible weather during our trip.","旅行中はひどい天気だった。","terrible はとても悪い状態を表す。be terrible at cooking なら『料理がとても苦手だ』で、at の後には名詞や -ing 形を置く。"],
    ["practical","The course provides practical advice for new teachers.","その講座は新任の先生に実用的な助言を提供する。","practical は実際に役立つことを強調する形容詞。理論に関わる theoretical と対比されることもある。"],
    ["entire","I spent the entire afternoon cleaning my room.","私は午後ずっと部屋の掃除をしていた。","the entire afternoon は『午後の時間を丸ごと』という意味。all を使えば all afternoon となり、語順や冠詞の違いに注意する。"],
    ["favorite","What is your favorite season?","いちばん好きな季節は何ですか。","favorite は『特に好きな・お気に入りの』。所有格の後に置く your favorite ... がよく使われる。イギリス式のつづりは favourite。"],
    ["comfortable","These shoes are comfortable even after a long walk.","この靴は長く歩いた後でも履き心地がよい。","comfortable は体や気持ちが楽な状態。物が使う人にとって便利だという convenient とは意味が異なる。"],
    ["minor","We made a few minor changes to the plan.","私たちは計画に小さな変更をいくつか加えた。","minor は重要度・程度が比較的小さいことを表す。a minor problem は『小さな問題』で、反対は major。"],
    ["typical","This is a typical example of his writing style.","これは彼の文体の典型的な例だ。","typical は特徴をよく示しているという意味。be typical of ... なら『～によく見られる・～らしい』という表現になる。"],
    ["ideal","This room is ideal for small meetings.","この部屋は少人数の会議に最適だ。","be ideal for ... で『～に理想的だ・最適だ』。idea『考え』に似たつづりだが、語尾の l を忘れないようにする。"],
    ["principal","The principal reason for the delay was bad weather.","遅延の主な理由は悪天候だった。","形容詞 principal は『主要な』、名詞なら『校長』などを表す。同じ発音の principle は『原則』で、つづりと意味が異なる。"],
    ["appropriate","Choose clothing appropriate for the weather.","天候に適した服を選んでください。","appropriate for ... は『～にふさわしい』。正しいかどうかだけでなく、その状況や目的に合っていることを表す。"],
    ["empty","The train was almost empty this morning.","今朝の電車はほとんど空いていた。","empty は中に物や人がない状態。動詞なら empty the box『箱を空にする』となり、中身を取り除く動作を表す。"],
    ["rapid","The town has experienced rapid growth.","その町は急速な成長を遂げてきた。","rapid は変化や進行の速さを表す形容詞。動詞を修飾するときは grow rapidly のように副詞 rapidly を使う。"],
    ["mental","A short break can reduce mental fatigue.","短い休憩は精神的な疲れを軽減することがある。","mental は心や思考に関係する『精神の』。physical『身体の』と対比して mental and physical health などと使う。"],
    ["excellent","She gave an excellent presentation.","彼女はすばらしい発表をした。","excellent は質がとても高いことを表す。母音の音で始まるので、例文では a ではなく an excellent presentation となる。"],
    ["convenient","Is Friday afternoon convenient for you?","金曜日の午後は都合がよいですか。","時刻や場所が人にとって都合がよいときに使う。人を主語に You are convenient. とせず、a time is convenient for you の形にする。"],
    ["potential","We discussed the potential benefits of the new system.","私たちは新しい仕組みから得られる可能性のある利点を話し合った。","potential は将来そうなる可能性があるという形容詞。名詞では『潜在能力・可能性』で、have potential『可能性を秘めている』と使う。"],
    ["financial","The club is facing financial difficulties.","そのクラブは財政的な困難に直面している。","financial は資金や財政に関係する形容詞。経済全体に関わる economic と区別し、financial support は『資金面での支援』と読む。"],
    ["enormous","Moving the library took an enormous amount of work.","図書館の移転には膨大な作業が必要だった。","enormous は大きさや量が非常に大きいことを表す。an enormous amount of の後には work などの数えない名詞を置く。"],
    ["rare","It is rare to see snow here in April.","ここで四月に雪を見るのは珍しい。","rare は頻度や存在数が少ないという形容詞。副詞 rarely は『めったに～ない』で、She rarely visits. のように使う。"],
    ["artificial","The room was lit by artificial light.","その部屋は人工の光で照らされていた。","artificial は自然にできたものではなく人が作ったもの。artificial flowers『造花』や artificial intelligence『人工知能』に使われる。"],
    ["tiny","A tiny bird was sitting on the fence.","とても小さな鳥が柵にとまっていた。","tiny は small より小ささを強く感じさせる語。a tiny amount『ごくわずかな量』のように量にも使える。"],
    ["considerable","The repairs will take considerable time.","その修理にはかなりの時間がかかるだろう。","considerable は無視できないほど大きい量・程度を表す。considerate『思いやりのある』とは別の語なので語尾まで確認する。"],
    ["sensitive","My eyes are sensitive to bright light.","私の目は強い光に敏感だ。","be sensitive to ... で『～に敏感だ』。人の気持ちについて使うと『傷つきやすい・細やかに感じ取る』という意味にもなる。"],
    ["intellectual","The puzzle offers an intellectual challenge.","そのパズルは知的な挑戦を与えてくれる。","intellectual は思考・知性に関わることを表す。単に頭がよいという intelligent と違い、知的活動の性質を述べる場合にも使う。"],
    ["thirsty","I felt thirsty after the long walk.","長く歩いた後、私はのどが渇いた。","thirsty は状態を表す形容詞なので be thirsty や feel thirsty と使う。『のどが渇いてきた』なら get thirsty。"],
    ["polite","It is polite to thank people for their help.","助けてくれた人に感謝するのは礼儀正しいことだ。","polite は相手への配慮を示す態度。be polite to someone で『人に礼儀正しく接する』、反対は impolite または rude。"],
    ["accurate","Check that the information is accurate.","情報が正確であることを確認してください。","accurate は情報・測定などが事実や正しい値に合っていること。動作の正確さを述べるなら副詞 accurately を使う。"],
    ["rude","It is rude to interrupt someone repeatedly.","人の話を何度も遮るのは失礼だ。","rude は相手に配慮のない失礼な態度。be rude to ... で『～に失礼な態度を取る』という形になる。"],
    ["sufficient","We have sufficient food for everyone.","全員に行き渡る十分な食料がある。","sufficient は必要な量を満たしていることを示す、enough より改まった語。『十分に』は sufficiently という副詞。"],
    ["urban","The survey compared urban and rural areas.","その調査は都市部と農村部を比較した。","urban は都市に関する形容詞。rural『農村の』と対で覚え、urban areas『都市部』という組み合わせで使う。"],
    ["temporary","This is a temporary solution until the parts arrive.","これは部品が届くまでの一時的な解決策だ。","temporary は限られた期間だけ続くことを表す。永続的な permanent と対になる。副詞は temporarily『一時的に』。"],
    ["primitive","The museum displays primitive stone tools.","その博物館は原始的な石器を展示している。","primitive は発達の初期段階にあることや、ごく簡単な構造を表す。現代の人々や文化を一括してこう呼ぶと、見下した響きになり得る。"],
    ["permanent","The museum now has a permanent home.","その博物館には今、恒久的な拠点がある。","permanent は一時的ではなく、長く続くことを表す形容詞。『永久』という日本語だけでなく permanent job『常勤の仕事』などの文脈でも捉える。"],
    ["elderly","The center provides activities for elderly residents.","その施設は高齢の住民向けの活動を提供している。","elderly は高齢の人を表す形容詞。the elderly では高齢者全体を指すが、個々の人なら an elderly person のように名詞を添える。"],
    ["severe","The region experienced a severe drought.","その地域は深刻な干ばつに見舞われた。","severe は問題・天候などの程度が厳しいことを示す。人や規則の厳格さを表す strict と、すべての場面で置き換えられるわけではない。"],
    ["brief","Please give us a brief explanation.","簡潔に説明してください。","brief は時間や文章が短いこと。in brief は『手短に言えば』、動詞 brief someone は『人に要点を説明する』となる。"],
    ["mobile","The library runs a mobile service for nearby villages.","その図書館は近隣の村に巡回サービスを提供している。","mobile は動かしたり移動したりできること。mobile library は『移動図書館』で、携帯電話以外の移動可能な物にも使う。"],
    ["latest","Have you read her latest book?","彼女の最新の本を読みましたか。","latest は時間的に最も新しいものを指す。last は『最後の・前回の』にもなるため、最新作なら latest が意味を明確にする。"],
    ["military","The old military base is now a public park.","その古い軍事基地は今では公園になっている。","形容詞 military は『軍の・軍事の』。the military の形では軍隊という集団を指す名詞になる。"],
    ["strict","The school has strict rules about phone use.","その学校には電話の使用について厳しい規則がある。","strict は規則を厳格に守らせること。be strict with children は『子どもに厳しい』、strict about time は『時間に厳しい』。"],
    ["solid","Water becomes solid when it freezes.","水は凍ると固体になる。","solid は『固体の』という形容詞で、a solid なら『固体』という名詞。liquid『液体』、gas『気体』と整理して覚える。"],
    ["stupid","Leaving my keys inside was a stupid mistake.","鍵を中に置いたままにしたのは、ばかな失敗だった。","stupid は判断や行動を強く否定する語。人に直接使うと侮辱的に響くため、語の強さも例文と一緒に覚えておく。"],
    ["biological","The students studied the biological effects of light.","生徒たちは光の生物学的な影響を研究した。","biological は生物や生命の仕組みに関する形容詞。学問としての『生物学』は biology、研究する人は biologist。"],
    ["probably","The shop will probably close early today.","その店は今日はおそらく早く閉まるだろう。","probably は可能性が高いと考えていることを表す副詞。助動詞がある例文では will と close の間に置いている。"],
    ["hardly","I could hardly hear the announcement.","私はそのアナウンスをほとんど聞き取れなかった。","hardly 自体に『ほとんど～ない』という否定的な意味がある。hard『一生懸命に』の意味で使わないよう注意する。"],
    ["immediately","Please call me immediately if the plan changes.","計画が変わったら、すぐに電話してください。","immediately は間を置かず『直ちに』という意味。immediately after lunch なら『昼食の直後に』と、after などの前にも置ける。"],
    ["eventually","After several attempts, we eventually solved the puzzle.","何度か試した末に、私たちはついにそのパズルを解いた。","eventually は時間や過程を経た末の結果を表す。『もしかすると』を意味する possibly とは異なり、結末に焦点がある。"],
    ["frequently","This bus route is frequently delayed by traffic.","このバス路線は交通渋滞でしばしば遅れる。","frequently は『頻繁に』という頻度の副詞で、often より改まった響き。形容詞 frequent は frequent delays『度重なる遅延』のように使う。"],
    ["extremely","The path becomes extremely slippery after rain.","その道は雨の後、非常に滑りやすくなる。","extremely は形容詞や副詞の程度を強める。例文では slippery を修飾しており、名詞 path を直接修飾しているわけではない。"],
    ["gradually","The sky gradually became brighter.","空はだんだん明るくなった。","gradually は少しずつ進む変化を表す。突然の変化を示す suddenly と対比すると、時間の進み方をイメージしやすい。"],
    ["instantly","I recognized her voice instantly.","私は彼女の声だとすぐにわかった。","instantly はほぼ一瞬で起こることを強調する。immediately と近いが、認識や反応の速さを表す場面にもよく合う。"],
    ["nevertheless","The task was difficult. Nevertheless, we finished it on time.","その作業は難しかった。それにもかかわらず、私たちは時間どおりに終えた。","nevertheless は前の内容から予想される流れに反することを導く副詞。文頭に置くときは例文のように後ろにコンマを置ける。"],
    ["moreover","The room is bright. Moreover, it is close to the station.","その部屋は明るい。そのうえ、駅にも近い。","moreover は前の内容に同じ方向の情報を付け加える、改まったつなぎ語。反対の情報を加える however とは役割が異なる。"],
    ["relatively","The test was relatively easy compared with the last one.","その試験は前回と比べて比較的簡単だった。","relatively は何かとの比較で程度を述べる副詞。絶対的に簡単という意味ではなく、比較の基準があることがポイント。"],
    ["apparently","Apparently, the meeting has been moved to Friday.","どうやら会議は金曜日に変更されたらしい。","apparently は見聞きした情報から『どうやら～らしい』と述べるときに使う。見たところそうでも実際は違う、という文脈にも使われる。"],
    ["definitely","I will definitely return the book tomorrow.","明日、必ずその本を返します。","definitely は話し手の強い確信を表す。例文では約束を強めているが、単語自体が客観的な保証になるわけではない。"],
    ["largely","The event succeeded largely because of the volunteers.","その行事が成功したのは、主にボランティアのおかげだった。","largely は理由や程度の大部分を表す。large『大きい』から形を連想しても、物の大きさを表す『大きく』と訳すとは限らない。"],
    ["mostly","The audience was mostly made up of local residents.","観客の大部分は地元の住民だった。","mostly は全体の大部分について述べる副詞。most people『大多数の人』の most と違い、mostly people と機械的に置き換えない。"],
    ["approximately","The walk takes approximately thirty minutes.","歩くと約三十分かかる。","approximately は数値が正確な値ではなく概算だと示す語。about と近い意味で、報告や説明ではより改まった響きになる。"],
    ["overnight","We left the dough in the fridge overnight.","私たちは生地を冷蔵庫に一晩入れておいた。","overnight は『一晩の間』という副詞。an overnight stay では形容詞として『一泊の滞在』を表す。"],
    ["accidentally","I accidentally sent the message to the wrong person.","私は誤って別の人にメッセージを送ってしまった。","accidentally は意図せず起きたことを示し、『うっかり・誤って』と訳す場合も多い。反対方向の表現は on purpose『わざと』。"],
    ["despite","We enjoyed the trip despite the rain.","雨にもかかわらず、私たちは旅行を楽しんだ。","despite は前置詞なので後ろは名詞や -ing 形。despite of とはしない。同じ意味の in spite of は三語で使う。"],
    ["proceed","After a short break, we proceeded with the discussion.","短い休憩の後、私たちは議論を続けた。","proceed with ... は『～を進める・続行する』。proceed to the next step なら『次の段階へ進む』で、後ろの前置詞にも注目する。"],
    ["ensure","Please ensure that all the windows are closed.","すべての窓が閉まっていることを確かめてください。","ensure that + 文で『～を確実にする』。ensure safety のように名詞も続けられる。人を安心させる assure と区別する。"],
    ["interpret","How do you interpret the final scene of the film?","その映画の最後の場面をどう解釈しますか。","interpret は意味を読み取って説明すること。interpret A as B は『AをBと解釈する』で、別の文脈では『通訳する』ともなる。"],
    ["cease","The factory ceased production last year.","その工場は昨年、生産を停止した。","cease は stop より改まった『やめる・終わる』。cease to exist『存在しなくなる』など、後ろに to 不定詞を置く形もある。"],
    ["ban","The city banned cars from the narrow street.","市はその狭い通りへの車の進入を禁止した。","ban A from ... は『Aが～すること・～に入ることを禁止する』。過去形 banned、-ing 形 banning では n を重ねる。"],
    ["obey","All drivers must obey the traffic rules.","すべての運転者は交通規則に従わなければならない。","obey は従う相手や規則を直接目的語に取る。obey to the rules とはせず、obey the rules とする。"],
    ["eliminate","The new design eliminates the need for extra cables.","新しい設計によって追加のケーブルが不要になる。","eliminate は不要なもの・問題などを取り除くこと。eliminate the need for ... は『～の必要をなくす』という便利な組み合わせ。"],
    ["resist","I could not resist buying another notebook.","私はもう一冊ノートを買わずにはいられなかった。","resist の後に動作を置くなら buying のような -ing 形。cannot resist ... は誘惑に抗えないという意味でも使う。"],
    ["accompany","A teacher will accompany the students on the trip.","その旅行には先生が生徒たちに同行する。","accompany は『～と一緒に行く』で、人を直接続ける。accompany with the students とはしない。"],
    ["commit","The team committed itself to reducing waste.","そのチームは廃棄物の削減に取り組むことを約束した。","commit oneself to ... は『～に専念する・身を入れる』。to は前置詞なので reducing を使う。commit a crime『罪を犯す』も重要。"],
    ["pursue","She moved to the city to pursue a career in design.","彼女はデザインの仕事を目指して都会へ移った。","pursue は目標などを追い求めること。pursue a goal や pursue a career のように対象を直接置き、pursue after とはしない。"],
    ["demonstrate","The experiment demonstrated that the material was strong.","実験によって、その材料が丈夫であることが示された。","demonstrate that ... は事実を示す用法。demonstrate how to use a tool なら『道具の使い方を実演する』となる。"],
    ["bet","I bet the train will be crowded today.","今日は電車が混むに違いないと思う。","会話の I bet ... は『きっと～だと思う』という強い予想。必ずしも実際に金銭を賭けているわけではない。"],
    ["ruin","The heavy rain ruined our picnic plans.","大雨で私たちのピクニックの計画は台無しになった。","ruin は価値や楽しみなどを大きく損なうこと。名詞の ruins は、the ruins of a castle『城跡』のように遺跡を表す。"],
    ["threaten","Rising water levels threatened the nearby houses.","水位の上昇が近くの家々を脅かした。","threaten は人による脅迫だけでなく、危険が何かを脅かす場合にも使う。threaten to do なら『～すると脅す・～しそうになる』。"],
    ["attach","Please attach a photo to the application form.","申込用紙に写真を添付してください。","attach A to B は『AをBに取り付ける・添付する』。メールの添付ファイルは attachment という名詞で表す。"],
    ["reverse","The company decided to reverse its earlier decision.","その会社は以前の決定を覆すことにした。","reverse は方向・順序・決定などを逆にすること。in reverse order は『逆の順序で』という表現。"],
    ["restrict","The museum restricts the number of visitors each hour.","その博物館は一時間あたりの入館者数を制限している。","restrict は許される範囲を狭めること。restrict A to B は『AをBに限定する』で、全面禁止を表す ban とは異なる。"],
    ["compose","The committee is composed of six members.","その委員会は六人の委員で構成されている。","be composed of ... で『～から構成されている』。compose a song では『曲を作る』という意味になり、目的語によって訳が変わる。"],
    ["lean","Do not lean against the glass door.","ガラスのドアにもたれかからないでください。","lean against ... は『～にもたれる』。lean forward なら『前に身を乗り出す』で、姿勢の傾きを表す。"],
    ["substitute","You can substitute yogurt for cream in this recipe.","このレシピではクリームの代わりにヨーグルトを使えます。","substitute A for B は『Bの代わりにAを使う』。新しく使うものがAなので、置き換える向きを逆にしないよう注意する。"],
    ["trace","We traced the river back to its source.","私たちは川を源流までさかのぼった。","trace は跡や経路をたどること。trace the cause of a problem なら『問題の原因を突き止める』という意味になる。"],
    ["interrupt","Sorry to interrupt, but your phone is ringing.","お話し中すみませんが、電話が鳴っています。","interrupt は話や作業の途中に割り込んで中断させること。Sorry to interrupt は話しかける際の断りとして使える。"],
    ["confront","We need to confront the problem instead of ignoring it.","その問題を無視せずに、向き合う必要がある。","confront は困難などに正面から向き合うこと。be confronted with a problem は『問題に直面する』という受け身の形。"],
    ["illustrate","This diagram illustrates how the machine works.","この図は機械がどう動くかを示している。","illustrate は例や図でわかりやすく示すこと。挿絵を描くという意味もあり、名詞 illustration もあわせて覚えたい。"],
    ["arrest","The police arrested a suspect near the station.","警察は駅の近くで容疑者を逮捕した。","arrest は人を逮捕すること。be arrested for theft は『窃盗の容疑で逮捕される』で、逮捕自体は有罪判決を意味しない。"],
    ["stimulate","The teacher used pictures to stimulate discussion.","先生は議論を活発にするために写真を使った。","stimulate は活動や反応を促すこと。stimulate interest『興味を刺激する』など、身体的な刺激以外にも広く使う。"],
    ["assure","The guide assured us that the path was safe.","ガイドは、その道は安全だと私たちに請け合った。","assure someone that ... は人に言葉で確信を与える形。確実な状態を実現する ensure と違い、通常は人を目的語に取る。"],
    ["consult","Consult the manual before changing the settings.","設定を変える前にマニュアルを参照してください。","consult a person は『人に相談する』、consult a book は『本を参照する』。この用法では相手・資料を直接続ける。"],
    ["depress","The long period of rainy weather depressed him.","長く続く雨の天気が彼を憂鬱にした。","depress は気分を落ち込ませる動詞。人の気分は depressed、その気分を起こさせる物事は depressing で表す。"],
    ["crash","The bicycle crashed into a fence.","その自転車は柵に激突した。","crash into ... は『～に激突する』。コンピューターについて The program crashed. と言えば『プログラムが異常終了した』となる。"],
    ["inspire","Her speech inspired me to try again.","彼女のスピーチを聞いて、私はもう一度挑戦する気になった。","inspire someone to do は『人を～する気にさせる』。やる気や発想を与えることを表し、名詞は inspiration。"],
    ["specialize","The shop specializes in handmade furniture.","その店は手作りの家具を専門に扱っている。","specialize in ... で『～を専門にする』。分野や商品を in の後ろに置く。イギリス式では specialise というつづりも使う。"],
    ["cultivate","Farmers cultivate rice in these fields.","農家はこれらの田で米を栽培している。","cultivate は土地を耕す・作物を育てること。cultivate a habit『習慣を育む』のように、時間をかけて養うという比喩にも使う。"],
    ["fulfill","She worked hard to fulfill her dream of opening a cafe.","彼女はカフェを開く夢を実現するために懸命に働いた。","fulfill a dream は『夢をかなえる』、fulfill a promise は『約束を果たす』。イギリス式のつづりは fulfil。"],
    ["transmit","The device transmits data to a nearby computer.","その装置は近くのコンピューターにデータを送信する。","transmit A to B は『AをBに送る・伝える』。過去形 transmitted では t を重ねる。情報や信号、病気などに使われる。"],
    ["found","They founded the club ten years ago.","彼らは十年前にそのクラブを設立した。","設立する found の活用は found–founded–founded。find『見つける』の過去形 found と混同しないよう、後ろの内容と形を見る。"],
    ["clap","The audience clapped at the end of the performance.","公演の終わりに観客が拍手した。","clap は手をたたく・拍手すること。clapped と clapping では p を重ねる。clap your hands と目的語を添えることもできる。"],
    ["burst","The balloon burst with a loud noise.","風船が大きな音を立てて破裂した。","burst は原形・過去形・過去分詞が同じ。burst into tears『突然泣き出す』のように、急に始まる動作にも使う。"],
    ["bow","The performers bowed to the audience.","出演者たちは観客におじぎをした。","bow to someone は『人におじぎする』。おじぎの bow は『バウ』に近い発音で、弓を表す bow とは発音が異なる。"],
    ["dismiss","Do not dismiss the idea without considering it.","検討もせずにその考えを退けないでください。","dismiss an idea は『考えを取り合わない・退ける』。人が目的語なら『解雇する』や『帰らせる』の意味になる場合がある。"],
    ["breed","These birds breed on the island in spring.","これらの鳥は春にその島で繁殖する。","breed は『繁殖する・繁殖させる』で、過去形・過去分詞は bred。名詞の a breed は動物の『品種』を指す。"],
    ["prohibit","The rules prohibit visitors from feeding the animals.","規則では来園者が動物に餌を与えることを禁じている。","prohibit someone from doing で『人が～するのを禁止する』。from の後ろは feeding のような -ing 形にする。"],
    ["oblige","The contract obliges us to finish by June.","契約により、私たちは六月までに終える義務がある。","oblige someone to do は『人に～する義務を負わせる』。be obliged to do の受け身で『～せざるを得ない』とも使う。"],
    ["qualify","This course qualifies you to teach beginners.","この講座を修了すると、初心者を教える資格が得られる。","qualify someone to do は『人に～する資格を与える』。qualify for the final は『決勝に進む資格を得る』という別の形。"],
    ["invest","The city invested in new public transport.","市は新しい公共交通に資金を投じた。","invest in ... は『～に投資する』。時間や労力にも使え、invest time in learning は『学習に時間をかける』となる。"],
    ["grasp","I finally grasped the main idea of the article.","私はようやくその記事の要点を理解した。","grasp は手でしっかりつかむ意味から、内容を理解する意味にもなる。grasp the meaning は『意味をつかむ』という組み合わせ。"],
    ["collapse","The old roof collapsed during the storm.","古い屋根が嵐の間に崩れ落ちた。","collapse は自ら崩れる・倒れること。建物のほか、計画や交渉が破綻する場面でも使われる。"],
    ["overlook","I overlooked a small error in the table.","私は表の小さな誤りを見落とした。","overlook は気づかず見逃すという意味。The room overlooks the sea. では『部屋から海が見渡せる』となるので文脈を確認する。"],
    ["accuse","He accused me of hiding the key.","彼は私が鍵を隠したと非難した。","accuse A of B で『BをしたとしてAを非難する・訴える』。動作を置くなら of hiding のように -ing 形にする。"],
    ["frustrate","The repeated delays frustrated the passengers.","度重なる遅延が乗客たちをいらだたせた。","frustrate は思いどおりにいかない気持ちにさせること。人は frustrated、そう感じさせる状況は frustrating と表す。"],
    ["deprive","The noise deprived us of sleep.","その騒音のせいで私たちは眠れなかった。","deprive A of B は『AからBを奪う』。奪われる人がA、失われるものがBで、前置詞 of を含めて覚える。"],
    ["astonish","The speed of her recovery astonished everyone.","彼女の回復の速さは皆を驚かせた。","astonish は非常に驚かせること。be astonished at ... は『～に驚く』で、驚く側と驚かせる側を区別する。"],
    ["register","Please register for the workshop by Friday.","金曜日までにワークショップに申し込んでください。","register for ... は催しなどに登録する形。register your name のように、登録する情報を直接続ける形もある。"],
    ["correspond","The numbers correspond to the labels on the map.","その番号は地図上のラベルに対応している。","correspond to ... は『～に対応する』。correspond with someone は手紙などで『人とやり取りする』という意味にもなる。"],
    ["cast","The tall tree cast a shadow over the bench.","高い木がベンチに影を落としていた。","cast a shadow は『影を投げかける』。cast は過去形・過去分詞も cast。cast a vote『票を投じる』という組み合わせもある。"],
    ["attribute","She attributed her success to regular practice.","彼女は成功を日々の練習のおかげだと考えた。","attribute A to B は『Aの原因をBだと考える』。結果がA、原因がBで、よい結果にも悪い結果にも使える。"],
    ["neglect","Do not neglect the small details.","細かい点をおろそかにしないでください。","neglect は必要な注意や世話を怠ること。neglect to reply は『返事をし忘れる・怠る』という形で使う。"],
    ["starve","Without enough food, the animals could starve.","十分な食料がなければ、その動物たちは飢えるおそれがある。","starve は食料がなく深刻に飢えること。会話の I'm starving. は『おなかがぺこぺこだ』という誇張表現にもなる。"],
    ["resolve","We resolved the disagreement through discussion.","私たちは話し合いで意見の対立を解消した。","resolve a problem は問題を解決すること。resolve to do では『～しようと決意する』となり、後ろの形で意味を見分ける。"],
    ["impose","The teacher imposed a time limit on the activity.","先生はその活動に制限時間を設けた。","impose A on B は『BにAを課す』。規則・負担・税など、相手が従う条件を上から設ける感覚がある。"],
    ["convert","They converted the old station into a cafe.","彼らは古い駅舎をカフェに改装した。","convert A into B は『AをBに変える』。用途や形態が変わる場面で使う。単位の換算にも convert を使える。"],
    ["scare","The sudden noise scared the cat.","突然の物音が猫をおびえさせた。","scare は怖がらせる動詞。怖がっている側は scared、怖さを与える物事は scary と表す。"],
    ["constitute","These five chapters constitute the first part of the book.","この五つの章が本の第一部を構成している。","constitute は部分が全体を構成するという改まった動詞。例文では五つの章が部分で、第一部が全体になっている。"],
    ["appoint","The club appointed her captain.","クラブは彼女を主将に任命した。","appoint someone + 役職で『人を～に任命する』。例文の captain のように、一つの役職名を無冠詞で続けることがある。"],
    ["imply","His silence seemed to imply agreement.","彼の沈黙は同意を示しているように思えた。","imply ははっきり言わずに意味を示すこと。infer は受け手が『推測する』ことで、情報を出す側と読む側が違う。"],
    ["assign","The teacher assigned a different topic to each group.","先生は各班に異なるテーマを割り当てた。","assign A to B は『BにAを割り当てる』。assign someone a task のように、人と仕事を続ける形も使える。"],
    ["nod","She nodded to show that she understood.","彼女は理解したことを示すためにうなずいた。","nod は首を縦に動かしてうなずくこと。過去形 nodded、-ing 形 nodding では d を重ねる。"],
    ["elect","The members elected him president of the club.","会員たちは彼をクラブの会長に選んだ。","elect は投票などで選ぶこと。単に候補を選択する choose よりも選挙の意味が強く、名詞は election。"],
    ["transfer","Please transfer the files to the new computer.","ファイルを新しいコンピューターへ移してください。","transfer A to B で『AをBに移す』。人の転勤や乗り換えにも使う。過去形 transferred は r を重ねる。"],
    ["rob","Someone robbed him of his wallet.","誰かが彼から財布を奪った。","rob A of B は『AからBを奪う』で、人・場所が直接の目的語。steal his wallet なら盗まれる物を直接置く。"],
    ["capture","The camera captured the moment the bird took off.","カメラは鳥が飛び立つ瞬間を捉えた。","capture は捕まえる意味のほか、映像や記録に捉える意味もある。capture attention は『注意を引きつける』という表現。"],
    ["undertake","The team undertook a survey of local wildlife.","そのチームは地域の野生生物の調査を引き受けた。","undertake は責任をもって仕事などを引き受ける改まった語。活用は undertake–undertook–undertaken。"],
    ["drown","The report said that several animals had drowned in the flood.","その報告によると、洪水で数頭の動物がおぼれ死んだ。","drown は通常、水中で呼吸できずに死ぬことを指す。almost drowned は『危うくおぼれ死ぬところだった』で、結果の違いに注意する。"],
    ["split","We split the class into two groups.","私たちはクラスを二つのグループに分けた。","split A into B は『AをBに分ける』。split は過去形・過去分詞も同じ形。split the cost は『費用を分担する』。"],
    ["resort","We had to resort to using candles during the power cut.","停電の間、私たちはろうそくを使わざるを得なかった。","resort to ... は他の方法がなく『～に頼る』こと。to は前置詞なので using のような -ing 形を続ける。"],
    ["descend","The hikers descended the mountain before sunset.","登山者たちは日没前に山を下りた。","descend は下へ移動すること。descend the stairs のように直接目的語を取れる。反対の ascend は『上る』。"],
    ["irritate","The constant clicking noise irritated me.","絶えず続くカチカチという音が私をいらだたせた。","irritate は不快にさせる・いらだたせること。皮膚などが目的語なら『刺激する・炎症を起こさせる』の意味にもなる。"],
    ["pronounce","How do you pronounce this word?","この単語はどう発音しますか。","pronounce は言葉を発音する動詞。名詞 pronunciation では noun の部分が nun になるので、つづりの変化に注意する。"],
    ["equip","The school equipped each classroom with a projector.","学校は各教室にプロジェクターを備え付けた。","equip A with B は『AにBを備え付ける』。過去形 equipped では p を重ねる。equipment は通常数えない名詞。"],
    ["cheat","It is unfair to cheat during a game.","試合中に不正をするのは不公平だ。","cheat は規則に反して有利になろうとすること。cheat someone out of money では『人をだまして金を奪う』となる。"],
    ["emerge","The sun emerged from behind the clouds.","太陽が雲の後ろから姿を現した。","emerge は隠れていたものが現れること。emerge from ... と出てくる場所を示せる。事実が明らかになる場合にも使う。"],
    ["devote","He devotes an hour each evening to reading.","彼は毎晩一時間を読書にあてている。","devote A to B は『AをBにささげる・あてる』。to は前置詞なので、動作には reading のような -ing 形を使う。"],
    ["heal","The small cut healed within a week.","その小さな切り傷は一週間以内に治った。","heal は傷などが治ること。heal a wound のように『傷を治す』という他動詞にもなる。病気を治療する treat とは焦点が違う。"],
    ["urge","The coach urged us to keep trying.","コーチは私たちに挑戦し続けるよう強く促した。","urge someone to do は『人に～するよう強く勧める』。単なる提案より強い働きかけを表す。"],
    ["envy","I envy your ability to remember names.","私はあなたの名前を覚える能力がうらやましい。","envy は人や能力などをうらやむ動詞で、対象を直接続ける。形容詞 envious なら be envious of ... の形にする。"],
    ["chase","The dog chased a ball across the grass.","犬は芝生を横切ってボールを追いかけた。","chase は捕まえようとして追うこと。chase a dream なら『夢を追う』という比喩的な使い方になる。"],
    ["prompt","The question prompted me to check the data again.","その質問がきっかけで、私はデータをもう一度確認した。","prompt someone to do は『人が～するきっかけになる・促す』。形容詞の prompt は『迅速な』で、a prompt reply と使う。"],
    ["withdraw","She withdrew her application before the interview.","彼女は面接の前に応募を取り下げた。","withdraw は引っ込める・取り下げること。withdraw money は『預金を引き出す』。活用は withdraw–withdrew–withdrawn。"],
    ["detect","The sensor can detect small changes in temperature.","そのセンサーは小さな温度変化を検知できる。","detect は見つけにくいものの存在や変化を発見すること。単に見る see よりも、調査や装置によって捉える感覚がある。"],
    ["interfere","The loud music interfered with my concentration.","大きな音楽が私の集中を妨げた。","interfere with ... は『～を妨げる』。interfere in someone's affairs は『人のことに干渉する』で、前置詞によって焦点が変わる。"],
    ["kid","I am only kidding; you did very well.","冗談を言っているだけだよ。あなたはとてもよくできた。","動詞 kid は冗談を言う・からかうこと。I'm kidding. は会話表現で、-ing 形では d を重ねる。名詞なら『子ども』。"],
    ["launch","The team launched a small rocket from the field.","そのチームは野原から小型ロケットを打ち上げた。","launch はロケットなどを送り出すこと。launch a service は『サービスを開始する』で、新しい事業や製品にも使う。"],
    ["endanger","Pollution can endanger wildlife in the river.","汚染は川の野生生物を危険にさらすおそれがある。","endanger は『～を危険にさらす』という動詞。endangered species は『絶滅の危機にある種』を表す。"],
    ["foster","The project aims to foster cooperation between schools.","その事業は学校間の協力を育むことを目指している。","foster は成長や発展を助けること。協力・理解・能力などを育てる場面で使い、植物を栽培する意味の cultivate とは区別する。"],
    ["diminish","The noise gradually diminished as the train moved away.","電車が遠ざかるにつれて、音は徐々に小さくなった。","diminish は量・強さ・重要性などが減ること。diminish the risk のように『～を減らす』という他動詞にもなる。"],
    ["spill","Be careful not to spill coffee on the keyboard.","キーボードにコーヒーをこぼさないよう気をつけてください。","spill は液体や小さな物を容器の外にこぼすこと。過去形・過去分詞には spilled と spilt の二つの形がある。"],
    ["infect","The virus can infect several kinds of plants.","そのウイルスは数種類の植物に感染することがある。","infect は病原体などが生物に感染する動詞。感染した側を主語にするなら be infected with ... という受け身を使う。"],
    ["stem","The confusion stemmed from an unclear message.","その混乱は不明瞭なメッセージから生じた。","stem from ... で『～に由来する・～から生じる』。原因を from の後ろに置く。過去形 stemmed では m を重ねる。"],
    ["tap","Tap the screen twice to open the picture.","画面を二回軽くたたくと画像が開きます。","tap は軽くたたくこと。画面操作の『タップする』も同じ語。過去形 tapped、-ing 形 tapping では p を重ねる。"],
    ["embrace","The team embraced the new approach.","そのチームは新しい方法を進んで受け入れた。","embrace は変化や考えを積極的に受け入れること。人が目的語なら『抱きしめる』という意味にもなる。"],
    ["proportion","A large proportion of the students walk to school.","生徒の大きな割合が歩いて通学している。","a proportion of ... は全体に占める割合。in proportion to ... は『～に比例して』という形になる。"],
    ["contract","We signed a contract with the builder.","私たちは建設業者と契約を結んだ。","sign a contract は『契約書に署名する』。名詞 contract は前半にアクセントがあり、動詞では通常後半を強く読む。"],
    ["chest","He held the box against his chest.","彼は箱を胸に抱えた。","chest は体の胸部を指す。a wooden chest なら収納用の『木製の大箱』で、文脈によって意味が変わる。"],
    ["treasure","The children drew a map showing the buried treasure.","子どもたちは埋められた財宝のありかを示す地図を描いた。","treasure は財宝をまとめて表せる。一つの大切な物は a treasure、動詞 treasure は『大切にする』。"],
    ["stock","She owns stock in several companies.","彼女は複数の会社の株を持っている。","stock は株式をまとめて指すことがある。店の商品について in stock と言えば『在庫がある』となる。"],
    ["facility","The town opened a new sports facility.","その町は新しいスポーツ施設を開設した。","facility は特定の目的に使う施設。複数形 facilities は建物内の設備やサービスをまとめて指す場合にも使う。"],
    ["sum","The repairs cost a large sum of money.","修理には多額のお金がかかった。","a sum of money は『ある金額』。数学では the sum of A and B が『AとBの和』を表す。"],
    ["rank","She rose to a senior rank in the organization.","彼女は組織内で上位の地位に昇進した。","rank は階級や順位。動詞なら rank first『第一位になる』、rank the options『選択肢に順位をつける』と使う。"],
    ["democracy","Free elections are important in a democracy.","民主国家では自由な選挙が重要だ。","政治体制としての民主主義は democracy。一つの民主国家を指すときは a democracy と数えられる。"],
    ["emergency","Keep this number in case of an emergency.","緊急時に備えて、この番号を控えておいてください。","in case of an emergency は『緊急の場合に備えて・緊急時には』。emergency exit は『非常口』を表す。"],
    ["protest","Residents held a protest against the closure.","住民はその閉鎖に反対する抗議活動を行った。","a protest against ... は『～に対する抗議』。動詞にもなり、protest against a decision と言える。"],
    ["immigrant","The program helps immigrants learn the local language.","そのプログラムは移民が現地の言語を学ぶのを支援している。","immigrant は移り住んできた人を受け入れ先から見た語。出身国を離れた側面を強調する emigrant と視点が異なる。"],
    ["vehicle","Only small vehicles can use this narrow road.","この狭い道路を通れるのは小型の車両だけだ。","vehicle は車・トラックなどの乗り物を広く指す。a vehicle for ideas なら『考えを伝える手段』という比喩になる。"],
    ["routine","Checking the calendar is part of my morning routine.","予定表を確認するのは私の朝の日課の一部だ。","routine は繰り返し行う一連の習慣。形容詞の a routine check は『定期的な・通常の点検』で、必ずしも退屈という意味ではない。"],
    ["stuff","Please move your stuff off the desk.","机の上からあなたの物をどけてください。","stuff はくだけた『物・持ち物』で、通常数えない。a stuff や複数形 stuffs ではなく、some stuff などと使う。"],
    ["row","We sat in the front row at the concert.","私たちはコンサートで最前列に座った。","row は横に並ぶ列。表では row『行』と column『列』を区別する。この意味の row は『ロウ』に近い発音。"],
    ["profile","The article includes a short profile of the artist.","その記事には画家の短い人物紹介が含まれている。","profile は人物の経歴や特徴をまとめた紹介。in profile は顔を横から見た状態、つまり『横顔で』という表現。"],
    ["dawn","We left the campsite at dawn.","私たちは夜明けにキャンプ場を出発した。","at dawn は『夜明けに』という組み合わせ。夕暮れの at dusk と対で覚え、通常は冠詞を入れない。"],
    ["welfare","The charity works for the welfare of children.","その慈善団体は子どもたちの福祉のために活動している。","welfare は健康・幸福・生活のよい状態を指す。social welfare は社会福祉で、単なる金銭給付だけを意味するわけではない。"],
    ["perspective","Try looking at the problem from her perspective.","その問題を彼女の立場から見てみてください。","from someone's perspective は『人の視点から』。別の見方を示すときに使え、a perspective on ... は『～についての見方』。"],
    ["enthusiasm","The students showed great enthusiasm for the project.","生徒たちはその企画に大きな熱意を示した。","enthusiasm for ... は『～への熱意』。通常は数えない名詞として使い、人の様子を形容するなら enthusiastic。"],
    ["faith","I have faith in your ability to solve this.","私はあなたにこれを解決する力があると信じている。","have faith in ... は『～を信頼する』。宗教的な信仰を指す場合もあるが、例文では能力への信頼を表す。"],
    ["occupation","Please write your name and occupation on the form.","用紙に氏名と職業を記入してください。","occupation は書類などで使う改まった『職業』。土地や建物については『占領・占有』という別の意味もある。"],
    ["witness","A witness described the accident to the police.","目撃者が警察に事故の様子を説明した。","witness は実際に見た人や証人。動詞 witness an event は『出来事を目撃する』で、対象を直接続ける。"],
    ["kingdom","The story takes place in an imaginary kingdom.","その物語の舞台は架空の王国だ。","kingdom は国王や女王が治める国。the animal kingdom は動物全体を指す『動物界』という表現。"],
    ["equivalent","This expression has no exact equivalent in Japanese.","この表現にぴったり対応する日本語はない。","名詞 equivalent は同等・対応するもの。形容詞では be equivalent to ...『～に相当する』と to を使う。"],
    ["objective","Our main objective is to reduce waiting times.","私たちの主な目標は待ち時間を減らすことだ。","名詞 objective は達成したい目標。形容詞 objective は『客観的な』で、個人の感情に左右されないという意味になる。"],
    ["pile","A pile of books was lying beside the bed.","ベッドの横に本の山があった。","a pile of ... は積み重なった物の山。例文の中心は単数の pile なので、動詞は was になっている。"],
    ["shelter","We took shelter from the rain under a bridge.","私たちは橋の下で雨宿りした。","take shelter from ... は『～を避けて避難する』。a shelter は避難場所などを指し、shelter は保護という意味でも使う。"],
    ["trial","The service offers a free trial for one week.","そのサービスは一週間の無料試用を提供している。","trial は試してみること。法律の文脈では『裁判』となり、on trial は『裁判を受けている』を表す。"],
    ["honor","It is an honor to speak at this event.","この催しでお話しできるのは光栄です。","an honor to do は『～できて光栄なこと』。h を発音しないため an を使う。イギリス式のつづりは honour。"],
    ["territory","The birds defend their territory during spring.","その鳥たちは春に自分たちの縄張りを守る。","territory は国の領土だけでなく動物の縄張りも指す。unfamiliar territory は『不慣れな領域』という比喩にもなる。"],
    ["frame","We put the photo in a wooden frame.","私たちはその写真を木製の額に入れた。","frame は物を囲む枠や骨組み。動詞 frame a picture なら『写真・絵を額に入れる』という意味になる。"],
    ["border","The river forms the border between the two countries.","その川が二国間の国境になっている。","the border between A and B は『AとBの間の境界』。cross the border は『国境を越える』という組み合わせ。"],
    ["statistics","The statistics show a rise in train travel.","その統計は鉄道利用の増加を示している。","統計数値を指す statistics は複数扱いで show を使う。学問の『統計学』なら Statistics is ... と単数扱いになる。"],
    ["enterprise","The bakery started as a small family enterprise.","そのパン屋は小さな家族経営の事業として始まった。","enterprise は企業や事業を指す改まった語。数えない名詞としては、新しい事業に取り組む積極性を表すこともある。"],
    ["context","You need to read the sentence in context.","その文は文脈の中で読む必要がある。","in context は前後の流れを踏まえて読むこと。out of context は文脈から切り離された状態を表す。"],
    ["load","The truck was carrying a heavy load of sand.","そのトラックは重い砂の荷を運んでいた。","load は運ぶ荷物や負荷。動詞なら load A onto B『AをBに積む』、load B with A『BにAを積む』という形がある。"],
    ["grain","The region produces grain for bread and animal feed.","その地域はパンや家畜の飼料用の穀物を生産している。","穀物全体は grain とまとめて表せる。a grain of rice なら米一粒で、grain は小さな粒を数える語にもなる。"],
    ["review","The plan is currently under review.","その計画は現在、再検討されている。","under review は検討・見直しの途中という意味。a book review は書評、review vocabulary は『単語を復習する』になる。"],
    ["prejudice","The lesson encouraged students to question their prejudices.","その授業は自分たちの偏見を問い直すよう生徒に促した。","prejudice は十分に確かめず持つ偏った判断。prejudice against ... で『～に対する偏見』を表す。"],
    ["strain","The extra work put a strain on the team.","追加の仕事がチームに負担をかけた。","put a strain on ... は『～に負担をかける』。心身・お金・関係など、無理がかかる場面で使う。"],
    ["trap","The mouse escaped from the trap.","ネズミはそのわなから逃げた。","trap は逃げられなくするわな。動詞の be trapped in ... は『～に閉じ込められている』を表す。"],
    ["temper","He lost his temper when the printer stopped again.","プリンターがまた止まると、彼はかっとなった。","lose one's temper は『腹を立てる・かっとなる』という熟語。keep one's temper なら怒りを抑えること。"],
    ["slave","The exhibition tells the stories of people forced to live as slaves.","その展示は奴隷として生きることを強いられた人々の物語を伝えている。","slave は自由を奪われ他人の支配下に置かれた人。enslaved people という表現は、奴隷にされた状況を明確にする。"],
    ["wound","The nurse cleaned the wound on his arm.","看護師は彼の腕の傷を洗浄した。","wound は皮膚などが損傷した傷。『傷』の wound は『ウーンド』に近く、wind の過去形 wound とは発音が違う。"],
    ["divorce","They decided to get a divorce.","二人は離婚することにした。","get a divorce は『離婚する』。動詞 divorce なら divorce someone と相手を直接続け、通常 with は入れない。"],
    ["tune","I remember the tune but not the words.","曲のメロディーは覚えているが、歌詞は覚えていない。","tune は旋律や曲。動詞 tune a guitar は『ギターを調律する』で、音程を整えることを表す。"],
    ["height","What is the height of this building?","この建物の高さはどのくらいですか。","height は高いという性質の名詞で、形容詞は high。at the height of ... は『～の最盛期に』という比喩的な表現。"],
    ["faculty","She joined the Faculty of Engineering last year.","彼女は昨年、工学部に加わった。","faculty は大学の学部や教員集団を指し、地域で使い方が異なる。a faculty for ... では『～する能力』という意味にもなる。"],
    ["span","The work was completed within a span of three months.","その作業は三か月の期間内に完了した。","a span of ... はある長さの期間。life span は『寿命』、attention span は『集中が続く時間』を表す。"],
    ["dimension","The discussion added a new dimension to the problem.","その議論によって、問題に新しい側面が加わった。","dimension は物事の側面や次元。複数形 dimensions は物の縦・横・高さなどの寸法を指すこともある。"],
    ["version","Please download the latest version of the file.","そのファイルの最新版をダウンロードしてください。","a version of ... は同じ物の異なる版や形。someone's version of events は『その人による出来事の説明』という意味。"],
    ["parallel","There is a clear parallel between the two stories.","その二つの物語には明らかな類似点がある。","名詞 parallel は類似点・対応するもの。形容詞なら parallel lines『平行線』、parallel to ...『～に平行な』と使う。"],
    ["horizon","A ship appeared on the horizon.","水平線上に船が現れた。","地平線・水平線には通常 the horizon を使う。broaden one's horizons は知識や経験の『視野を広げる』という表現。"],
    ["acquaintance","I met an old acquaintance at the station.","私は駅で昔の知り合いに会った。","acquaintance は顔や名前を知っている知人で、親しい friend とは限らない。an acquaintance of mine は『私の知り合い』。"],
    ["burden","The long commute became a burden on the family.","長い通勤が家族の負担になった。","a burden on ... は『～にとっての重荷』。身体的な荷物だけでなく、費用や責任などの負担にも使う。"],
    ["basis","The decision was made on the basis of the survey.","その決定は調査をもとに下された。","on the basis of ... は『～を根拠に』。単数 basis の複数形は bases で、語尾の形が変わる。"],
    ["poison","The label warns that the liquid contains poison.","ラベルには、その液体に毒が含まれると警告されている。","poison は毒となる物質。形容詞 poisonous は『有毒な』で、動詞 poison は『毒を入れる・中毒にさせる』を表す。"],
    ["constitution","The constitution sets out the basic rules of government.","憲法は政治の基本的な規則を定めている。","constitution は国の基本法である憲法。a strong constitution という別の文脈では『丈夫な体質』を指す。"],
    ["administration","The school administration announced a new schedule.","学校の運営側が新しい予定を発表した。","administration は組織の運営やその担当者たち。国の政治では『行政・政権』という意味でも使われる。"],
    ["charm","The old town has a charm of its own.","その古い町には独自の魅力がある。","charm は人や物が人を引きつける魅力。a lucky charm は身につける『お守り』という別の意味になる。"],
    ["organ","The heart is an organ that pumps blood.","心臓は血液を送り出す臓器だ。","organ は体の中で特定の働きをする器官・臓器。同じつづりで楽器のオルガンも表すので、文脈で判断する。"],
    ["prey","The owl watched its prey from a branch.","フクロウは枝から獲物を見つめていた。","prey は捕食される動物をまとめて指す通常数えない名詞。a bird of prey は『猛禽類の鳥』を表す。"],
    ["venture","Their first business venture was a small bookshop.","彼らの最初の事業は小さな書店だった。","venture はリスクを伴う新しい事業や試み。動詞 venture into ... は『思い切って～に入る』という意味になる。"],
    ["mission","The team's mission is to map the sea floor.","そのチームの任務は海底の地図を作ることだ。","mission は重要な任務や目的。on a mission は『任務について』で、単なる日常の作業より大きな目的を感じさせる。"],
    ["inquiry","We received an inquiry about the evening course.","私たちは夜間講座についての問い合わせを受けた。","an inquiry about ... は『～についての問い合わせ』。an inquiry into ... は事件などへの調査を表すことが多い。"],
    ["award","The film won an award for its music.","その映画は音楽に対して賞を受けた。","win an award は『賞を受ける』。動詞 award は賞などを与えることで、award someone a prize と使う。"],
    ["strip","Cut the paper into narrow strips.","紙を細長い帯状に切ってください。","a strip of paper は細長い紙の一片。動詞 strip は取り除く意味があり、strip paint off a door などと使う。"],
    ["distress","The sudden loss caused the family great distress.","突然の喪失が家族に大きな苦しみをもたらした。","distress は強い心痛や苦境を表す。in distress は『苦しんで・困難に陥って』で、救助を必要とする場面にも使う。"],
    ["circulation","Exercise increases blood circulation.","運動は血液の循環を促進する。","circulation は循環や流通。新聞の circulation は『発行部数』で、何が回っているのかを文脈で確かめる。"],
    ["shade","We rested in the shade of a large tree.","私たちは大きな木の陰で休んだ。","shade は日光の当たらない場所。形のある影を指す shadow と異なり、涼しく休む場所には in the shade を使う。"],
    ["stereotype","The story challenges the stereotype of the quiet scientist.","その物語は無口な科学者という固定観念に疑問を投げかけている。","stereotype は集団や人物像を単純化した決めつけ。動詞でも使え、stereotype people は『人を型にはめて見る』となる。"],
    ["client","The designer met the client to discuss the website.","デザイナーはウェブサイトについて話すために依頼人に会った。","client は専門的なサービスの依頼人。店で商品を買う customer と重なる場合もあるが、相談や継続的な仕事でよく使う。"],
    ["output","The factory increased its output last month.","その工場は先月、生産量を増やした。","output は作業や装置が生み出す量・出力。投入する資源や入力を表す input と対で覚えるとわかりやすい。"],
    ["lord","The hymn refers to God as the Lord.","その賛美歌では神を主と呼んでいる。","キリスト教などの文脈で the Lord は『主・神』。小文字の lord は領主などの称号にも使われ、常に神を指すわけではない。"],
    ["convention","The city hosts a science fiction convention every summer.","その市では毎夏、SFの大会が開かれる。","convention は共通の関心を持つ人の大会・会議。social conventions では社会の慣習やしきたりという別の意味になる。"],
    ["mine","The village grew around a coal mine.","その村は炭鉱を中心に発展した。","a mine は鉱山、coal mine は炭鉱。This bag is mine. の mine『私のもの』とは文中の役割が異なる。"],
    ["craft","She learned the craft of making wooden bowls.","彼女は木の器を作る技術を学んだ。","craft は手作業の技術・工芸。動詞 craft a message は文章などを『念入りに作る』ことを表す。"],
    ["core","Trust is at the core of our partnership.","信頼が私たちの協力関係の中心にある。","at the core of ... は『～の核心に』。リンゴの芯のような物理的な中心から、考えの重要部分まで表せる。"],
    ["stroke","The musician struck the drum with a single stroke.","演奏者は一打で太鼓をたたいた。","stroke は一回の打撃や筆の一運び。医療の文脈の a stroke は『脳卒中』で、一般的な発作すべてを指す語ではない。"],
    ["frontier","The travelers crossed the frontier at sunrise.","旅行者たちは日の出の時刻に国境を越えた。","frontier は国境や開拓地の境界。the frontiers of science は知識の限界に挑む『科学の最先端』という比喩になる。"],
    ["peer","Students discussed their work with their peers.","生徒たちは同じ立場の仲間と作品について話し合った。","peer は年齢や地位などが同じ程度の仲間。動詞 peer into ... は『～をじっとのぞき込む』という別の用法。"],
    ["vessel","Blood flows through a network of vessels.","血液は網の目のように広がる血管を流れる。","blood vessel は血管。vessel 単独では船や容器にもなるため、前後の語と合わせて意味を選ぶ。"],
    ["disability","The design makes the building easier to use for people with disabilities.","その設計は障害のある人が建物を利用しやすくしている。","a disability は身体・感覚・認知などの機能に関わる障害。people with disabilities のように人を主語にした表現もよく使う。"],
    ["gravity","Gravity keeps the planets in orbit around the sun.","重力が惑星を太陽の周りの軌道にとどめている。","gravity は通常数えない『重力』。the gravity of the situation では『状況の重大さ』という意味になる。"],
    ["ethic","The team shares a strong work ethic.","そのチームには勤勉に働く姿勢が共有されている。","a work ethic は仕事に対する倫理観・姿勢。倫理学という学問は通常 ethics と s をつけて表す。"],
    ["terminal","The bus leaves from the terminal near the airport.","そのバスは空港近くのターミナルから出発する。","terminal は交通の発着施設や終点。コンピューターの端末も terminal と呼び、どの設備かは文脈で判断する。"],
    ["tide","The beach becomes much wider at low tide.","干潮になると、その浜辺はずっと広くなる。","tide は潮の満ち引き。high tide は満潮、low tide は干潮で、at と組み合わせて時点を表せる。"],
    ["abuse","The organization works to prevent child abuse.","その団体は児童虐待の防止に取り組んでいる。","abuse は虐待や不適切な使用。abuse of power は『権力の乱用』で、強い立場を悪く使うことを表す。"],
    ["guilty","I felt guilty about forgetting her birthday.","彼女の誕生日を忘れてしまい、私は後ろめたく思った。","feel guilty about ... は『～を後ろめたく思う』。法律の文脈では guilty of a crime『罪を犯して有罪の』と使う。"],
    ["vital","Clear communication is vital to the project.","明確な意思疎通はその事業にきわめて重要だ。","vital to ... は成功や存続に不可欠な重要性を示す。very important に近いが、なくては困るという意味合いが強い。"],
    ["fellow","She shared her notes with her fellow students.","彼女は仲間の学生たちとノートを共有した。","fellow + 人を表す名詞で『同じ立場の仲間の』。fellow workers や fellow passengers のように共通の立場を示す。"],
    ["contemporary","The gallery displays contemporary art.","その画廊は現代美術を展示している。","contemporary は現代の、または同時代のという意味。歴史の文章では contemporary accounts が『当時の記録』を指すこともある。"],
    ["annual","The club holds its annual meeting in April.","そのクラブは毎年恒例の会議を四月に開く。","annual は年に一度の、または一年間の。annual income は『年収』で、副詞 annually は『毎年』を表す。"],
    ["accustomed","I am accustomed to getting up early.","私は早起きに慣れている。","be accustomed to ... は『～に慣れている』。to は前置詞なので、動作には getting のような -ing 形を使う。"],
    ["steady","She made steady progress throughout the course.","彼女は講座を通して着実に進歩した。","steady は大きな揺れや変動がなく安定した状態。a steady hand は『ぶれない手』、steady progress は『着実な進歩』。"],
    ["dull","The lecture was dull until the speaker showed the experiment.","講演は実験が披露されるまで退屈だった。","dull は刺激がなく退屈なこと。刃物については『切れ味が鈍い』、光や色については『鈍い・くすんだ』ともなる。"],
    ["keen","She is keen to learn how to repair bicycles.","彼女は自転車の修理方法をぜひ学びたいと思っている。","be keen to do は『しきりに～したがる』。keen on ... は『～が好きだ・熱心だ』で、後ろに名詞や -ing 形を置く。"],
    ["loose","One of the screws is loose.","ねじの一つが緩んでいる。","loose は固定が緩い状態を表す形容詞。lose『失う』とはつづりも発音も違い、loose の語尾は濁らない s の音になる。"],
    ["delicate","Handle the delicate glass figures carefully.","繊細なガラス細工を丁寧に扱ってください。","delicate は壊れやすく丁寧な扱いを要すること。a delicate issue は『慎重な対応が必要な微妙な問題』を表す。"],
    ["internal","The company is conducting an internal review.","その会社は内部で見直しを行っている。","internal は組織や物の内部に関する形容詞。外部の external と対になり、internal organs は『内臓』となる。"],
    ["casual","Casual clothes are fine for the picnic.","ピクニックには普段着で構いません。","casual は形式ばらない・気軽なこと。a casual conversation は『気軽な会話』で、必ずしも無責任という意味ではない。"],
    ["mature","The garden contains several mature trees.","その庭には十分に育った木が数本ある。","mature は十分に成長した状態。人について使うと年齢だけでなく、判断や振る舞いが大人びていることも表す。"],
    ["concrete","Can you give a concrete example?","具体的な例を挙げられますか。","形容詞 concrete は抽象的でなく具体的なこと。名詞なら建材の『コンクリート』になり、同じつづりで役割が変わる。"],
    ["awful","There was an awful smell coming from the bin.","ごみ箱からひどい臭いがしていた。","awful は非常に悪いという意味。awe『畏敬』と関連する形でも、日常では通常『ひどい・不快な』として使う。"],
    ["exhausted","We were exhausted after moving all the boxes.","箱をすべて運び終えて、私たちは疲れ切っていた。","exhausted は疲れ切った側の状態。疲れさせる作業は exhausting work と表し、-ed と -ing を区別する。"],
    ["overall","The overall result was better than we expected.","全体的な結果は予想よりよかった。","overall は全体をまとめて評価するときの語。副詞として文頭に置く Overall, ... は『全体としては』を表す。"],
    ["tight","These shoes are too tight around the toes.","この靴はつま先の周りがきつすぎる。","tight は隙間や余裕が少ないこと。a tight schedule は『余裕のない予定』で、服や靴以外にも使う。"],
    ["prime","Our prime concern is the safety of the visitors.","私たちの最優先の関心事は来場者の安全だ。","prime は最も重要な、主要なという意味。a prime example は『代表的な例』、prime minister は『首相』という組み合わせ。"],
    ["genuine","The museum confirmed that the painting was genuine.","博物館はその絵が本物であると確認した。","genuine は偽物でないこと。genuine concern は『心からの心配』で、感情や態度がうわべでない場合にも使う。"],
    ["modest","They live in a modest house near the station.","彼らは駅の近くの質素な家に住んでいる。","modest は規模が控えめなこと。人については『謙虚な』で、modest about one's success は成功を自慢しない態度を表す。"],
    ["intimate","The letters reveal an intimate friendship.","その手紙から親密な友情がうかがえる。","intimate は個人的で非常に近い関係を表す。intimate knowledge は『詳しい知識』という意味で使われることもある。"],
    ["minimum","The minimum age for this class is twelve.","このクラスに参加できる最低年齢は十二歳だ。","minimum は最小・最低の限度。名詞でも使え、keep noise to a minimum は『騒音を最小限に抑える』となる。"],
    ["sophisticated","The laboratory uses sophisticated measuring equipment.","その研究室は高度な測定機器を使っている。","sophisticated は仕組みが高度で精巧なこと。人や趣味については『洗練された』という意味にもなる。"],
    ["latter","Of the train and the bus, I prefer the latter.","電車とバスなら、私は後者のほうが好きだ。","the latter は二つ挙げたものの後者。この例では bus を指す。前者は the former で、later『より後に』とは別の語。"],
    ["bitter","The tea tasted bitter because I left it too long.","長く置きすぎたので、お茶は苦かった。","bitter は味の苦さ。a bitter disappointment は『つらい失望』で、感情の強い苦痛や恨みにも使う。"],
    ["peculiar","This expression is peculiar to the region.","この表現はその地域特有のものだ。","be peculiar to ... は『～に特有だ』。単独の a peculiar noise は『妙な音』という意味になる。"],
    ["passive","The teacher encouraged passive students to join the discussion.","先生は消極的な生徒たちに議論への参加を促した。","passive は自分から働きかけず受け身であること。文法用語の the passive voice は『受動態』を指す。"],
    ["ethnic","The festival celebrates the traditions of different ethnic groups.","その祭りはさまざまな民族集団の伝統をたたえている。","ethnic は共通の文化や出自に関する形容詞。ethnic group『民族集団』のように使い、国籍を表す national と区別する。"],
    ["noble","Helping others was a noble goal for the young leader.","他人を助けることは、その若い指導者にとって気高い目標だった。","noble は道徳的に立派な・気高いという意味。a noble family なら貴族の家系を指す場合もある。"],
    ["vain","We searched in vain for the missing key.","私たちはなくした鍵を捜したが、見つからなかった。","in vain は『むなしく・成果なく』という熟語。人を形容する vain には『うぬぼれた』という別の意味もある。"],
    ["innocent","The evidence showed that she was innocent.","証拠によって、彼女に罪がないことが示された。","innocent は罪がないこと。an innocent question は悪意のない質問を表し、法律以外の文脈でも使う。"],
    ["underlying","We need to identify the underlying cause of the delay.","遅延の根本的な原因を特定する必要がある。","underlying は表面に見える現象の下にあること。underlying cause『根本原因』、underlying assumption『前提となる考え』などで使う。"],
    ["alien","The customs felt alien to the visitor.","その訪問者には、その習慣がなじみのないものに感じられた。","alien to ... は『～になじみのない・異質な』。物語の名詞 an alien は『宇宙人』だが、形容詞の意味と区別する。"],
    ["relevant","Please include only information relevant to the topic.","その話題に関係のある情報だけを含めてください。","relevant to ... で『～に関連する』。話題や判断に役立つつながりを示し、反対語は irrelevant。"],
    ["inclined","I am inclined to agree with your suggestion.","私はどちらかというとあなたの提案に賛成だ。","be inclined to do は『～する気がある・～する傾向がある』。確定した決定よりも、気持ちがそちらに傾いていることを表す。"],
    ["awkward","There was an awkward silence after the question.","その質問の後、気まずい沈黙があった。","awkward は場の気まずさや扱いにくさを表す。an awkward shape は持ったり扱ったりしにくい形という意味。"],
    ["brilliant","She came up with a brilliant solution.","彼女はすばらしい解決策を思いついた。","brilliant はとても優れた・才能のあるという意味。brilliant sunlight のように光の『まぶしい』にも使う。"],
    ["desperate","We made a desperate effort to finish before sunset.","私たちは日没前に終わらせようと必死に努力した。","desperate は追い詰められた状況での必死さを表す。be desperate for water は『水を切実に必要としている』となる。"],
    ["refreshing","The cool breeze was refreshing after the long walk.","長く歩いた後の涼しい風はさわやかだった。","refreshing は気分や元気を回復させる側の性質。人がさっぱりした気分なら I feel refreshed. と -ed を使う。"],
    ["thrilled","I was thrilled to receive an invitation.","招待を受けて、私はとてもうれしかった。","be thrilled to do は『～して大喜びする』。喜びや興奮を感じる側の状態で、出来事には thrilling を使える。"],
    ["inner","The jacket has an inner pocket for small items.","その上着には小物用の内ポケットがある。","inner は内側にあること。outer『外側の』と対になり、inner feelings は心の内面の感情を指す。"],
    ["consistent","Her explanation is consistent with the records.","彼女の説明は記録と矛盾しない。","be consistent with ... は『～と一致する・矛盾しない』。consistent effort はむらなく続く努力を表す。"],
    ["plain","Please explain the rules in plain language.","規則をわかりやすい言葉で説明してください。","plain は複雑でなく明瞭なこと。plain yogurt は味付けのないヨーグルト、a plain shirt は無地のシャツになる。"],
    ["vivid","She gave a vivid description of the market.","彼女は市場の様子を生き生きと描写した。","vivid は色や印象が鮮明なこと。a vivid memory は今もはっきり思い浮かぶ記憶を表す。"],
    ["miserable","I felt miserable when I lost my favorite notebook.","お気に入りのノートをなくして、私はひどく落ち込んだ。","miserable はとても不幸・不快に感じる状態。天候などについて miserable weather と言えば『うっとうしいひどい天気』となる。"],
    ["substantial","The change led to a substantial reduction in waste.","その変更によって、ごみが大幅に減った。","substantial は量や程度がかなり大きいこと。単に存在するだけでなく、十分に意味のある規模を示す。"],
    ["fond","My grandmother is fond of gardening.","祖母は園芸が好きだ。","be fond of ... は『～が好きだ』。of の後には名詞か -ing 形を置く。a fond memory は愛情を感じる懐かしい思い出。"],
    ["false","The report was based on false information.","その報告は誤った情報に基づいていた。","false は事実に反する・本物でないという意味。意図的な嘘だけでなく、単に誤っている情報にも使う。"],
    ["lazy","We spent a lazy afternoon reading by the window.","私たちは窓辺で読書をして、のんびりした午後を過ごした。","lazy は人に使うと『怠けた』という否定的な語。a lazy afternoon のように、活動せずゆっくり過ごす時間も表せる。"],
    ["precisely","The train arrived at precisely nine o'clock.","電車は九時ちょうどに到着した。","precisely はずれがなく正確にという副詞。That is precisely my point. では『まさにそれが私の言いたいことだ』になる。"],
    ["meanwhile","I prepared the vegetables. Meanwhile, my brother cooked the rice.","私は野菜を準備した。その間に弟は米を炊いた。","meanwhile は同じ時間帯に別のことが起きていると示す副詞。while のように直後へ節をつなぐ接続詞ではない。"],
    ["altogether","The new plan is altogether different from the old one.","新しい計画は古い計画とまったく異なる。","altogether は『完全に』や『全部で』。all together は『全員一緒に』という二語の表現で、意味を区別する。"],
    ["lately","I have been reading more novels lately.","私は最近、小説を読むことが増えている。","lately は最近の状態や傾向を表し、現在完了とよく使う。late『遅く』に -ly をつけただけの意味ではない。"],
    ["barely","We barely caught the last bus.","私たちはかろうじて最終バスに間に合った。","barely は必要な程度にほんの少しだけ達していること。例文では間に合っているが、余裕がほとんどなかったとわかる。"],
    ["scarcely","I could scarcely see the path in the fog.","霧の中で道はほとんど見えなかった。","scarcely は『ほとんど～ない』という否定的な副詞。通常さらに not を重ねず、scarcely any time『ほとんど時間がない』とも使う。"],
    ["accordingly","The forecast changed, so we adjusted our plans accordingly.","予報が変わったので、私たちはそれに合わせて計画を調整した。","accordingly は状況に応じて相応にという意味。文と文をつなぎ『したがって』と結果を示す場合もある。"],
    ["deliberately","She deliberately left a blank space for comments.","彼女はコメント用の空欄を意図的に残した。","deliberately は偶然でなく意図した行動を示す。『わざと』でも悪意があるとは限らず、例文では目的のある設計を表す。"],
    ["beneath","A small stream flows beneath the bridge.","橋の下を小さな川が流れている。","beneath は『～の下に』で、under より文章的な響き。表面の下という意味でも使え、beneath the surface と言える。"],
    ["whereas","I prefer tea, whereas my sister prefers coffee.","私は紅茶が好きだが、姉はコーヒーが好きだ。","whereas は二つの事実を対比する接続詞。後ろには主語と動詞を含む文を続ける。場所を尋ねる where とは別の語。"],
    ["declare","The mayor declared the new bridge open.","市長は新しい橋の開通を宣言した。","declare は公に明言すること。declare that ... で内容を文として示せるほか、税関で物品を申告する場合にも使う。"],
    ["alter","We need to alter the schedule slightly.","私たちは予定を少し変更する必要がある。","alter は性質や内容を変えること。服を直す alter a jacket など、元の物を残しつつ調整する場合にも合う。"],
    ["arise","Several questions arose during the discussion.","議論の間にいくつか疑問が生じた。","arise は問題や機会などが生じる自動詞。活用は arise–arose–arisen。何かを上げる raise とは区別する。"],
    ["transform","They transformed the empty lot into a community garden.","彼らは空き地を共同菜園に変えた。","transform A into B は『AをBへ大きく変える』。小さな修正より、外観や性質がはっきり変わることを強調する。"],
    ["defeat","Our team defeated the visitors by two points.","私たちのチームは来訪チームを二点差で破った。","defeat の目的語は負かした相手。試合に勝つなら win the game、相手を破るなら defeat the team と使い分ける。"],
    ["investigate","The researchers investigated the cause of the unusual sound.","研究者たちはその奇妙な音の原因を調査した。","investigate は事実や原因を詳しく調べること。investigate the cause のように対象を直接続け、通常 about は不要。"],
    ["distinguish","Can you distinguish the original from the copy?","原本とコピーを見分けられますか。","distinguish A from B は『AをBと見分ける』。distinguish between A and B という形でも二つの違いを述べられる。"],
    ["bury","The dog buried a bone under the tree.","犬は木の下に骨を埋めた。","bury の過去形 buried は y を i に変える。発音は『ベリー』に近く、つづりの u から音を決めつけないようにする。"],
    ["cope","She found a way to cope with the extra work.","彼女は追加の仕事に対処する方法を見つけた。","cope with ... は難しい状況に対応すること。cope the problem とはせず、with を入れる。"],
    ["occur","The problem occurs only when the battery is low.","その問題は電池残量が少ないときだけ起こる。","occur は自動詞なので、通常 be occurred とはしない。過去形 occurred では r を重ねる。"],
    ["accomplish","We accomplished all three tasks before lunch.","私たちは昼食前に三つの作業をすべてやり遂げた。","accomplish は目標や仕事を完了すること。accomplish a task と対象を直接続け、努力の結果としての達成に焦点を置く。"],
    ["hesitate","Do not hesitate to ask for help.","遠慮せずに助けを求めてください。","hesitate to do は『～するのをためらう』。否定の案内文では、気兼ねなく行動してよいと勧める表現になる。"],
    ["endure","The hikers endured hours of heavy rain.","登山者たちは何時間もの大雨に耐えた。","endure は苦しい状態を我慢して持ちこたえること。endure pain のように、耐える対象を直接続ける。"],
    ["conclude","We concluded that the first design was the safest.","私たちは最初の設計が最も安全だと結論づけた。","conclude that ... は情報から結論を出す形。conclude a meeting なら『会議を終える』という別の意味になる。"],
    ["guarantee","A high price does not guarantee good quality.","値段が高いからといって品質がよいとは限らない。","guarantee は結果や品質を確約すること。guarantee that ... と文を続けることもでき、単なる期待より強い語になる。"],
    ["dominate","A large clock tower dominates the town square.","大きな時計塔が町の広場でひときわ目立っている。","dominate は支配することのほか、大きさなどで圧倒的な存在感を持つこと。dominate a discussion は議論を独占する意味。"],
    ["confirm","The second test confirmed the original result.","二回目の検査が最初の結果を裏づけた。","confirm は確かめる・裏づけること。confirm a reservation は予約の確認で、どの事実を確かにするかが目的語になる。"],
    ["greet","She greeted the visitors with a smile.","彼女は笑顔で来訪者を迎えた。","greet は人にあいさつして迎える動詞。greet someone with a smile のように、with で迎え方を添えられる。"],
    ["entertain","The storyteller entertained the children with funny tales.","語り手は面白い話で子どもたちを楽しませた。","entertain someone with ... は『～で人を楽しませる』。entertain guests には客をもてなすという意味もある。"],
    ["defend","The walls were built to defend the town from attack.","その城壁は攻撃から町を守るために築かれた。","defend A from/against B は『BからAを守る』。意見を擁護するときも defend an opinion と使える。"],
    ["forbid","The rules forbid players to leave the field without permission.","規則では選手が許可なく競技場を離れることを禁じている。","forbid someone to do は『人が～するのを禁じる』。活用は forbid–forbade–forbidden となる。"],
    ["broadcast","The station will broadcast the concert live.","その放送局はコンサートを生放送する。","broadcast はテレビ・ラジオなどで放送すること。broadcast live の live は『ライブ』に近い発音で、『生で』を表す。"],
    ["sacrifice","She sacrificed her weekend to finish the project.","彼女は企画を終えるために週末を犠牲にした。","sacrifice は別の目的のために大切なものを手放すこと。sacrifice A for B なら犠牲にするものがA、目的がB。"],
    ["punish","The school punished the students for damaging the desk.","学校は机を壊したことで、その生徒たちを罰した。","punish A for B は『BのことでAを罰する』。行為を続ける場合は for damaging のように -ing 形にする。"],
    ["glance","He glanced at the clock before answering.","彼は答える前に時計をちらりと見た。","glance at ... は短時間さっと見ること。じっと見る stare at ... と、見ている時間の長さが異なる。"],
    ["retain","The renovated building retains its original entrance.","改修された建物は元の入り口を残している。","retain は失わずに保持するという改まった語。retain information は学んだ情報を記憶にとどめること。"],
    ["calculate","We calculated the total cost of the trip.","私たちは旅行の総費用を計算した。","calculate は数値を計算して求めること。calculate how much ... と、どれほどかを表す節を続ける形もある。"],
    ["sinking","The boat was sinking when the rescuers arrived.","救助隊が着いたとき、その船は沈みかけていた。","sinking は動詞 sink の -ing 形で、この例では過去進行形。基本の活用は sink–sank–sunk になる。"],
    ["rescue","Firefighters rescued the cat from the roof.","消防隊員が屋根から猫を救助した。","rescue A from B は『BからAを救い出す』。come to someone's rescue は『人の救助に駆けつける』という名詞の用法。"],
    ["beg","The child begged her father to stay a little longer.","その子は父親にもう少し長くいてほしいと懇願した。","beg someone to do は人に強くお願いすること。beg for help は『助けを乞う』で、過去形 begged は g を重ねる。"],
    ["define","The guide defines the term in simple language.","その案内書はその用語を簡単な言葉で定義している。","define A as B は『AをBと定義する』。意味や範囲を明確にする動詞で、名詞は definition。"],
    ["deceive","The false label deceived customers about the product's origin.","その偽の表示は商品の産地について客をだました。","deceive は真実でないことを信じさせること。deceive someone into doing は『人をだまして～させる』という形。"],
    ["convey","The photograph conveys a sense of calm.","その写真は穏やかな雰囲気を伝えている。","convey は考えや感情を相手に伝えること。言葉以外でも使え、convey a message to someone と相手を示せる。"],
    ["sustain","The village cannot sustain such rapid growth.","その村はこれほど急速な成長を維持できない。","sustain は状態や活動を続けられるよう支えること。sustain an injury は『けがを負う』という別の組み合わせ。"],
    ["purchase","The school purchased new computers for the library.","学校は図書館用に新しいコンピューターを購入した。","purchase は buy より改まった『購入する』。名詞の proof of purchase は『購入を証明するもの』を表す。"],
    ["fade","The colors of the poster faded in the sunlight.","ポスターの色が日光で薄れた。","fade は色・音・記憶などが徐々に弱まること。fade away は『だんだん消えていく』という形になる。"],
    ["regulate","The rules regulate the use of water during dry periods.","その規則は乾燥期の水の使用を規制している。","regulate は規則や仕組みで調整・管理すること。必ずしも全面的に禁止する意味ではなく、量や方法を制御する場合にも使う。"],
    ["distribute","Volunteers distributed maps to the visitors.","ボランティアは来訪者に地図を配った。","distribute A to B は『BにAを配る』。複数の人や場所に分けて行き渡らせることを表す。"],
    ["enhance","The new lighting enhances the colors of the paintings.","新しい照明は絵画の色を引き立てている。","enhance は価値や効果を高めること。enhance understanding は『理解を深める』で、もともとあるものをよりよくする感覚。"],
    ["chat","We chatted about our weekend plans.","私たちは週末の予定についておしゃべりした。","chat about ... は気軽な話題について話すこと。過去形 chatted と -ing 形 chatting では t を重ねる。"],
    ["exceed","The number of visitors exceeded our expectations.","来訪者数は私たちの予想を上回った。","exceed は限度や予想を超えること。exceed the limit のように対象を直接続け、通常 over を追加しない。"],
    ["wipe","Please wipe the table with a clean cloth.","きれいな布でテーブルを拭いてください。","wipe A with B は『BでAを拭く』。wipe the table clean のように、拭いた後の状態を続けることもできる。"],
    ["cooperate","The two schools cooperated on the project.","二つの学校はその事業で協力した。","cooperate with someone は『人と協力する』、cooperate on a project は『事業で協力する』。相手と内容で前置詞が変わる。"],
    ["inherit","She inherited a collection of books from her uncle.","彼女は叔父から蔵書を受け継いだ。","inherit A from B は『BからAを受け継ぐ』。財産だけでなく、遺伝的な特徴や引き継いだ状況にも使う。"],
    ["unite","The shared goal united the two teams.","共通の目標が二つのチームを団結させた。","unite は別々の人や集団を一つにすること。unite against ... は『～に対して団結する』という形になる。"],
    ["leap","The cat leaped over the puddle.","猫は水たまりを跳び越えた。","leap は大きく跳ぶこと。過去形・過去分詞には leaped と leapt があり、a leap forward は大きな前進という比喩。"],
    ["exaggerate","He exaggerated the size of the fish he caught.","彼は釣った魚の大きさを大げさに話した。","exaggerate は実際以上に大きく・深刻に表現すること。完全な作り話とは限らず、程度を膨らませる点が中心。"],
    ["conquer","She gradually conquered her fear of public speaking.","彼女は人前で話す恐怖を徐々に克服した。","conquer は領土を征服するだけでなく、恐怖や困難を克服する意味でも使う。conquer a fear という組み合わせを覚える。"],
    ["melt","The ice melted in the warm sun.","氷は暖かい日差しで溶けた。","melt は熱で固体が液体になること。砂糖が水に溶ける dissolve とは仕組みが異なる。"],
    ["invade","Tourists invaded the quiet streets during the festival.","祭りの間、観光客が静かな通りにどっと押し寄せた。","invade は侵略・侵入すること。例文は多くの人が押し寄せる様子を比喩的に表している。"],
    ["modify","We modified the design to make it easier to carry.","持ち運びやすくするために設計を修正した。","modify は目的に合わせて一部を変えること。名詞 modification は『修正・変更』を表す。"],
    ["scatter","The wind scattered the papers across the floor.","風で書類が床一面に散らばった。","scatter はばらばらに散らすこと。be scattered around ... は『～のあちこちに散在する』となる。"],
    ["undergo","The building is undergoing major repairs.","その建物では大規模な修理が行われている。","undergo は変化や処置を経験すること。活用は undergo–underwent–undergone で、目的語を直接続ける。"],
    ["evaluate","We evaluated the plan using three different criteria.","私たちは三つの異なる基準で計画を評価した。","evaluate は基準に照らして価値や成果を判断すること。単にほめるという意味ではない。"],
    ["bend","She bent down to pick up the coin.","彼女は硬貨を拾うために身をかがめた。","bend down は『かがむ』。bend a wire は『針金を曲げる』で、過去形・過去分詞は bent。"],
    ["derive","The word derives from an ancient name.","その単語は古い名前に由来する。","derive from ... は『～に由来する』。derive A from B なら『BからAを得る』という形になる。"],
    ["screaming","The children were screaming with excitement on the ride.","子どもたちは乗り物に乗って興奮の叫び声を上げていた。","screaming は scream の -ing 形。怖さだけでなく、喜びや興奮で大声を上げる場合にも使う。"],
    ["gaze","We gazed at the stars for a long time.","私たちは長い間、星を見つめた。","gaze at ... は関心や感動をもってじっと眺めること。ちらりと見る glance at ... と区別する。"],
    ["pray","They prayed for a safe journey.","彼らは旅の安全を祈った。","pray for ... は『～を祈る』。pray to ... は祈りを向ける神などを示す。"],
    ["polish","He polished his shoes before the ceremony.","彼は式典の前に靴を磨いた。","polish は磨いてつやを出すこと。polish an essay なら文章を推敲して完成度を上げる意味になる。"],
    ["classify","The books are classified by subject.","本は分野別に分類されている。","classify A by B は『Bを基準にAを分類する』。classify A as B は『AをBに分類する』。"],
    ["assert","The author asserts that sleep affects memory.","著者は睡眠が記憶に影響すると主張している。","assert that ... は強く断言すること。主張が正しいと証明済みであることまでは意味しない。"],
    ["grab","She grabbed her bag and ran for the bus.","彼女はかばんをつかみ、バスへ走った。","grab は素早くつかむこと。grabbed と grabbing では b を重ね、急な動作を表す。"],
    ["fold","Fold the paper in half.","紙を半分に折ってください。","fold A in half は『Aを二つ折りにする』。fold your arms は腕を組むという表現。"],
    ["sweep","Please sweep the leaves off the path.","道の落ち葉を掃き除いてください。","sweep はほうきなどで掃くこと。活用は sweep–swept–swept で、off は取り除く方向を示す。"],
    ["whisper","He whispered the answer to his partner.","彼は相手に答えをささやいた。","whisper は息のような小さな声で話すこと。whisper something to someone と内容と相手を示せる。"],
    ["imitate","The child tried to imitate the bird's song.","その子は鳥の鳴き声をまねようとした。","imitate は動作や音などをまねること。imitate someone は人の話し方・振る舞いをまねる意味になる。"],
    ["stare","He stared at the screen in surprise.","彼は驚いて画面をじっと見つめた。","stare at ... は目を大きく開けてじっと見ること。人を凝視すると失礼に受け取られる場面もある。"],
    ["emphasize","The guide emphasized the importance of keeping quiet.","ガイドは静かにすることの重要性を強調した。","emphasize は重要さを目立たせて伝えること。emphasize the importance of ... という組み合わせで使える。"],
    ["rid","We need to get rid of these broken chairs.","この壊れた椅子を処分する必要がある。","get rid of ... は不要なものを取り除く熟語。rid だけでなく get と of を含めて覚える。"],
    ["pour","She poured some tea into my cup.","彼女は私のカップに紅茶を注いだ。","pour A into B は『AをBの中へ注ぐ』。雨について It's pouring. と言えば『土砂降りだ』になる。"],
    ["vanish","The rabbit vanished into the bushes.","ウサギは茂みの中へ姿を消した。","vanish は見えなくなるという自動詞。通常は目的語を直接取らず、場所には into などを添える。"],
    ["restore","The museum restored the damaged painting.","博物館は傷んだ絵画を修復した。","restore は元のよい状態に戻すこと。restore A to B は『AをBの状態・場所へ戻す』という形。"],
    ["deserve","You deserve a break after all that work.","それだけ働いたのだから、あなたは休憩を取ってよい。","deserve は報酬・扱いなどを受けるに値すること。deserve to do も使え、必ずしもよい結果だけとは限らない。"],
    ["laboratory","The samples were sent to a laboratory for testing.","試料は検査のために研究所へ送られた。","laboratory は実験や検査のための施設・部屋。会話では短く lab と呼ぶことも多い。"],
    ["conference","She presented her research at an international conference.","彼女は国際会議で研究を発表した。","conference は共通のテーマを話し合う会議や学会。出席・発表の場には at a conference を使う。"],
    ["continent","The exhibition features animals from different continents.","その展示はさまざまな大陸の動物を紹介している。","continent は大陸で、country『国』より広い地理的な区分。continental は『大陸の』という形容詞。"],
    ["insurance","The company provides insurance for the equipment.","その会社は機器に対する保険を提供している。","insurance は通常数えない。個々の保険契約は an insurance policy と表す。"],
    ["crew","The ship's crew prepared for the storm.","船の乗組員たちは嵐に備えた。","crew は船・航空機などで働く人の集団。一人なら a crew member と表す。"],
    ["poverty","The report examines the causes of poverty.","その報告書は貧困の原因を調べている。","poverty は貧困という状態を表す通常数えない名詞。live in poverty は『貧困の中で暮らす』。"],
    ["shortage","The town is facing a shortage of teachers.","その町は教員不足に直面している。","a shortage of ... は必要な量に対して足りない状態。不足しているものを of の後に置く。"],
    ["affair","She takes a keen interest in international affairs.","彼女は国際情勢に強い関心を持っている。","affairs は公的な事柄・情勢をまとめて指す。単数 affair は出来事や問題など、文脈で意味が変わる。"],
    ["exception","Everyone arrived on time, with one exception.","一人を除いて、全員が時間どおりに到着した。","exception は一般的な規則から外れる例。an exception to the rule は『規則の例外』となる。"],
    ["wage","The workers asked for higher wages.","労働者たちは賃金の引き上げを求めた。","wages は労働に対して支払われる賃金。an hourly wage は時間あたりの賃金、つまり時給。"],
    ["wisdom","Her advice reflects years of experience and wisdom.","彼女の助言には長年の経験と知恵が表れている。","wisdom は経験を踏まえたよい判断力・知恵。情報としての knowledge と区別すると意味を捉えやすい。"],
    ["tax","The price includes sales tax.","価格には売上税が含まれている。","tax は税金。pay tax on income は『所得に対する税を払う』で、課税対象には on を使える。"],
    ["evolution","The book explains the evolution of birds.","その本は鳥類の進化を説明している。","evolution は世代を経た生物の変化や、物事の漸進的な発展。動詞は evolve になる。"],
    ["barrier","Language can be a barrier to communication.","言語が意思疎通の障壁になることがある。","a barrier to ... は『～を妨げるもの』。物理的な柵だけでなく、行動を難しくする条件にも使う。"],
    ["category","Put each word into the correct category.","各単語を適切な分類に入れてください。","category は性質が共通するものの分類・範疇。複数形 categories では y を ies に変える。"],
    ["unit","The meter is a unit of length.","メートルは長さの単位だ。","a unit of ... は『～の単位』。教材の一課や、まとまった組織の一単位を指す場合もある。"],
    ["reputation","The restaurant has a reputation for friendly service.","その店は親切な接客で評判がよい。","have a reputation for ... は『～で評判だ』。reputation 自体は評価全般で、悪い評判にも使える。"],
    ["virtue","Patience is a useful virtue when teaching beginners.","初心者を教える際、忍耐は役立つ美徳だ。","virtue は道徳的に望ましい性質。the virtues of a plan は計画の長所という意味にもなる。"],
    ["courage","It took courage to admit the mistake.","間違いを認めるには勇気が必要だった。","It takes courage to do は『～するには勇気が要る』。courage は通常数えない名詞。"],
    ["sympathy","She expressed sympathy for the families affected by the flood.","彼女は洪水で被災した家族への同情を示した。","sympathy for ... は苦しむ相手への思いやり。相手の感情を理解する empathy と近いが、常に同じではない。"],
    ["union","The workers formed a union to discuss working conditions.","労働者たちは労働条件を話し合うために組合を作った。","union は複数の人や組織が結びついた集団。労働組合なら a labor union または trade union。"],
    ["civilization","The class studied an ancient civilization along the river.","そのクラスは川沿いの古代文明を学んだ。","a civilization は特定の社会の文明。文明全体を表す場合は civilization と数えずに使うこともある。"],
    ["volume","This history is published in three volumes.","この歴史書は三巻で出版されている。","本の volume は巻・冊。音量や容積という別の意味もあるので、周囲の名詞から判断する。"],
    ["blossom","The cherry trees are in blossom.","桜の木々は花が咲いている。","in blossom は開花中という表現。blossom は特に果樹などの花を指し、動詞なら『花が咲く』。"],
    ["era","The invention marked the beginning of a new era.","その発明は新しい時代の始まりを示した。","era はある特徴を持つ時代・長い期間。a new era of ... は『～の新時代』と使う。"],
    ["dispute","The neighbors settled their dispute over the fence.","隣人同士は柵をめぐる争いを解決した。","a dispute over ... は『～をめぐる争い』。settle a dispute で対立を解決することを表す。"],
    ["tourism","Tourism provides many jobs in the town.","観光業はその町で多くの雇用を生み出している。","tourism は観光という活動・産業全般。個々の観光客は a tourist と言い分ける。"],
    ["mankind","The exhibit explores mankind's attempts to understand space.","その展示は宇宙を理解しようとする人類の試みを紹介している。","mankind は人類全体。性別を明示しない同じ範囲の語として humankind や humanity も使われる。"],
    ["murder","The novel begins with a mysterious murder.","その小説は謎めいた殺人事件から始まる。","murder は意図的で違法な殺人を指す。kill は殺すこと全般で、意味の範囲がより広い。"],
    ["landscape","The train passed through a landscape of hills and lakes.","列車は丘と湖のある風景の中を進んだ。","landscape はある地域の眺め・地形。一つの景観は a landscape、風景画も landscape と呼べる。"],
    ["destination","We reached our destination just before dark.","私たちは暗くなる直前に目的地に着いた。","destination は向かっている先。reach our destination では reach の後に to を入れない。"],
    ["tale","Grandfather told us a tale about a clever fox.","祖父は賢いキツネの話をしてくれた。","tale は物語・お話で、想像上の話によく使う。fairy tale は『おとぎ話』という組み合わせ。"],
    ["reform","The report calls for reform of the examination system.","その報告書は試験制度の改革を求めている。","reform は制度などを改善するための改革。個々の変更は reforms と複数形でまとめられる。"],
    ["muscle","Climbing stairs uses the muscles in your legs.","階段を上ると脚の筋肉を使う。","個々の筋肉は a muscle。筋肉組織や筋肉量をまとめて指す場合は muscle と数えず使うこともある。"],
    ["prospect","The prospect of moving abroad excited her.","海外へ移る見通しに彼女はわくわくした。","the prospect of ... は将来起こりそうなことへの見込み。job prospects は仕事が見つかる見通しを表す。"],
    ["corporation","The corporation has offices in several countries.","その企業は複数の国に事務所を持っている。","corporation は法人としての企業を表す改まった語。corporate は『企業の』という形容詞になる。"],
    ["colony","The history course examines life in the former colony.","その歴史講座は、かつての植民地の生活を考察している。","colony は他国の支配下に置かれた植民地。an ant colony はアリの集団という別の用法。"],
    ["quarrel","They had a quarrel about whose turn it was.","彼らは誰の番なのかをめぐって口論した。","have a quarrel with someone は『人と口論する』。about で口論の話題を続けられる。"],
    ["profession","She chose teaching as her profession.","彼女は職業として教職を選んだ。","profession は特に専門知識や訓練を要する職業。by profession は『職業は～で』という表現。"],
    ["aspect","We considered every aspect of the plan.","私たちは計画のあらゆる側面を検討した。","an aspect of ... は『～の一側面』。物事全体ではなく、取り上げる一つの面に焦点を当てる。"],
    ["pause","There was a short pause before she answered.","彼女が答えるまでに少し間があった。","pause は後で再開する一時的な休止。動詞 pause to think は『立ち止まって考える』を表す。"],
    ["conflict","There is a conflict between the two schedules.","二つの予定がかち合っている。","conflict は対立や両立しない状態。武力紛争だけでなく、予定・意見・利益の衝突にも使う。"],
    ["privilege","It was a privilege to work with such skilled people.","これほど熟練した人々と働けたのは光栄だった。","privilege は特別な権利や恵まれた機会。例文は機会への感謝を表し、法的な権利に限らない。"],
    ["prosperity","The new railway brought prosperity to the town.","新しい鉄道はその町に繁栄をもたらした。","prosperity は経済的に豊かで順調な状態。形容詞は prosperous『繁栄している』。"],
    ["genius","The young composer was considered a genius.","その若い作曲家は天才とみなされていた。","a genius は天才的な人。能力としての天才性は genius と数えず使う場合がある。"],
    ["seed","Plant the seeds in a sunny place.","日当たりのよい場所に種をまいてください。","seed は植物の種。the seeds of change なら後の変化につながる『変化の芽』という比喩。"],
    ["symptom","The leaflet lists the common symptoms of the illness.","その案内には病気によく見られる症状が載っている。","a symptom of ... は『～の症状』。the symptom of a wider problem なら問題の表れという比喩になる。"],
    ["merit","Each proposal has its own merits.","それぞれの提案には独自の長所がある。","merit は評価できるよい点。on its merits は評判などでなく、それ自体のよさに基づいて判断すること。"],
    ["layer","Cover the seeds with a thin layer of soil.","種を薄い土の層で覆ってください。","a layer of ... は重なった一つの層。衣服にも使え、wear layers は重ね着をすること。"],
    ["clue","The letter gave us a clue to the answer.","その手紙は答えへの手がかりを与えてくれた。","a clue to ... は『～の手がかり』。I have no clue. は会話で『見当もつかない』となる。"],
    ["circumstances","We changed the plan because of the circumstances.","私たちは状況を考慮して計画を変更した。","周囲の事情を表すときは通常複数形 circumstances。under the circumstances は『その事情では』という表現。"],
    ["district","The school is in a quiet residential district.","その学校は静かな住宅地区にある。","district は特徴や行政上の境界で区分した地区。business district は商業地区、school district は学区。"],
    ["prison","The story follows a man who escapes from prison.","その物語は刑務所から脱走する男を描いている。","in prison は収監されている状態で、通常無冠詞。in the prison は特定の刑務所の建物内を指せる。"],
    ["companion","Her dog was her constant companion on walks.","彼女の犬はいつも散歩に付き添う仲間だった。","companion は一緒に時間や行動を共にする相手。職場仲間という意味に限定されない。"],
    ["executive","A company executive explained the decision.","会社の幹部がその決定を説明した。","executive は企業などの経営幹部。形容詞なら executive power『行政権』など、実行・運営に関わる意味を持つ。"],
    ["justice","The campaign called for justice for the victims.","その運動は被害者のための正義の実現を求めた。","justice は公正な扱いや正義。通常数えない名詞で、a justice は裁判官を表す別の用法。"],
    ["procedure","Please follow the procedure described in the manual.","マニュアルに書かれた手順に従ってください。","procedure は決まった手順・手続き。個々の方法を a procedure と数えることができる。"],
    ["ray","A ray of sunlight came through the curtain.","一筋の日光がカーテンの隙間から差し込んだ。","a ray of light は一筋の光。a ray of hope は困難な状況での『一筋の希望』を表す。"],
    ["heaven","The painting shows angels in heaven.","その絵には天国の天使たちが描かれている。","宗教上の天国は通常 heaven と無冠詞。the heavens は文章で『空・天空』を表す場合がある。"],
    ["luxury","Having a whole afternoon free felt like a luxury.","午後ずっと自由に過ごせるのは贅沢に感じられた。","a luxury は必需品ではない特別な楽しみや便利さ。live in luxury は『贅沢に暮らす』という形。"],
    ["oxygen","Fish obtain oxygen from water through their gills.","魚はえらを通して水中の酸素を取り入れる。","oxygen は酸素という物質を表す通常数えない名詞。an oxygen tank は酸素を入れたタンク。"],
    ["fund","The school created a fund for new library books.","学校は図書館の新しい本のための基金を設けた。","a fund は目的別に蓄えた資金・基金。複数形 funds は利用できる資金全般を表すことがある。"],
    ["theme","Friendship is the main theme of the novel.","友情がその小説の主題だ。","theme は作品や議論を貫く中心的な主題。a theme song は作品を代表する主題歌。"],
    ["boundary","The fence marks the boundary of the property.","その柵は敷地の境界を示している。","boundary は土地や範囲を区切る境界。personal boundaries は人との関係で守りたい個人的な限度を表す。"],
    ["ambition","Her ambition is to design affordable homes.","彼女の大望は手頃な価格の住宅を設計することだ。","ambition は達成を強く望む目標や向上心。an ambition to do は『～したいという大志』になる。"],
    ["forecast","The weather forecast predicts rain this evening.","天気予報は今夜雨になると予測している。","a weather forecast は天気予報。動詞 forecast は天気や需要など将来の状態を予測すること。"],
    ["psychology","She studies psychology at university.","彼女は大学で心理学を学んでいる。","psychology は心や行動を研究する学問。語頭の p は発音せず、研究する人は psychologist。"],
    ["labor","Building the wall required several days of hard labor.","壁の建設には数日間の重労働が必要だった。","labor は労働という活動をまとめて表す語。イギリス式では labour とつづる。"],
    ["committee","The committee will review the proposals tomorrow.","委員会は明日、提案を検討する。","committee は特定の仕事を担う人々の集団。一人の委員は a committee member と表す。"],
    ["physician","The physician listened carefully to the patient's concerns.","医師は患者の不安に注意深く耳を傾けた。","physician は医師を指す改まった語。特に内科系の医師を表すことがあり、physicist『物理学者』と区別する。"],
    ["philosophy","The course introduces the philosophy of ancient Greece.","その講座は古代ギリシャの哲学を紹介する。","philosophy は学問の哲学。a philosophy of life は人生についての基本的な考え方を指す。"],
    ["affection","She spoke about her old teacher with affection.","彼女は昔の先生について愛情を込めて話した。","affection は親しみを伴う温かな気持ち。affection for someone で『人への愛情』を表す。"],
    ["candidate","Each candidate gave a short speech.","各候補者が短い演説をした。","candidate は選挙・仕事などの候補者。a candidate for the position は『その役職の候補者』になる。"],
    ["priority","Safety is our top priority.","安全が私たちの最優先事項だ。","priority は先に扱うべき重要事項。give priority to ... は『～を優先する』という組み合わせ。"],
    ["obstacle","The lack of space is an obstacle to expansion.","場所の不足が拡張の障害になっている。","an obstacle to ... は進行を妨げるもの。to の後に動作を置くなら expanding のような -ing 形にする。"],
    ["appetite","The long walk gave me a good appetite.","長く歩いて食欲がわいた。","appetite は食欲。an appetite for knowledge は知識への強い欲求を表す比喩になる。"],
    ["tension","There was tension between the two groups.","二つの集団の間には緊張があった。","tension は不安や対立で張り詰めた状態。ひもなどが引っ張られる物理的な張力にも使う。"],
    ["tribe","The museum worked with members of the tribe to create the exhibit.","博物館はその部族の人々と協力して展示を作った。","tribe は共通の文化や系譜を持つ集団。実際の人々には、その集団自身が使う呼称も確認するとよい。"],
    ["budget","We need to stay within our travel budget.","旅行の予算内に収める必要がある。","within budget は『予算内で』、over budget は『予算を超えて』。金額を示す枠として覚える。"],
    ["campaign","The students started a campaign to reduce plastic waste.","生徒たちはプラスチックごみを減らす運動を始めた。","campaign は目的に向けた一連の活動。広告だけでなく、選挙や社会運動にも使う。"],
    ["sorrow","She expressed deep sorrow at the news.","彼女はその知らせに深い悲しみを示した。","sorrow は深い悲しみを表すやや改まった語。通常数えず使うが、sorrows では悲しみの原因を指せる。"],
    ["satellite","The satellite sends images of the Earth.","その衛星は地球の画像を送ってくる。","satellite は惑星の周囲を回る衛星。人工衛星だけでなく、月のような自然の衛星も含む。"],
    ["insight","The interview gave us insight into her creative process.","そのインタビューで彼女の創作過程への理解が深まった。","insight into ... は表面だけでない深い理解。give someone insight into ... という形で使える。"],
    ["cough","His cough interrupted the quiet performance.","彼のせきが静かな演奏を遮った。","cough は名詞でも動詞でも使う。語尾 gh は f の音で、つづりから発音を誤らないようにする。"],
    ["fate","The fate of the old station is still uncertain.","古い駅の行く末はまだ不明だ。","fate は将来の運命や結末。人以外に建物や計画の今後についても使える。"],
    ["scheme","The council introduced a scheme to support local shops.","議会は地元の店を支援する計画を導入した。","scheme は特にイギリス英語では施策・計画。文脈によっては悪だくみという否定的な意味にもなる。"],
    ["insult","He took the comment as an insult.","彼はその発言を侮辱と受け取った。","take A as an insult は『Aを侮辱と受け取る』。名詞は前半、動詞 insult は通常後半を強く読む。"],
    ["inhabitant","The island has fewer than a hundred inhabitants.","その島には百人未満の住民しかいない。","inhabitant はある場所に住む人・生物。訪問者ではなく、そこを生活の場にしていることを表す。"],
    ["fossil","They found a fossil in the rock.","彼らは岩の中に化石を見つけた。","fossil は昔の生物の痕跡が残った化石。fossil fuels は石炭や石油などの化石燃料を指す。"],
    ["motive","What was his motive for changing the plan?","計画を変えた彼の動機は何だったのか。","a motive for ... は行動の背後にある理由。for の後には名詞や changing のような -ing 形を置く。"],
    ["instinct","The bird built its nest by instinct.","その鳥は本能で巣を作った。","by instinct は学んだのでなく本能で行うこと。trust your instincts は直感を信じるという表現。"],
    ["legend","A local legend tells of a dragon in the lake.","地元の伝説は湖にいる竜のことを伝えている。","legend は古くから伝わる伝説。地図では記号を説明する『凡例』という意味にもなる。"],
    ["empire","The map shows the empire at its greatest extent.","地図は最大領域に達した時点の帝国を示している。","empire は複数の地域を支配する帝国。a business empire は巨大な企業群を指す比喩。"],
    ["suburb","They moved to a suburb outside the city.","彼らは市の外側の郊外へ引っ越した。","a suburb は都市周辺の住宅地。郊外全体を指すときは in the suburbs と複数形もよく使う。"],
    ["architecture","The city is famous for its modern architecture.","その都市は近代建築で有名だ。","architecture は建築の技術・様式・建物群をまとめて表す。設計する人は architect。"],
    ["passion","She has a passion for restoring old furniture.","彼女は古い家具の修復に情熱を注いでいる。","a passion for ... は『～への強い情熱』。for の後ろには名詞か -ing 形を続ける。"],
    ["cancer","The institute supports research into cancer.","その研究所はがんの研究を支援している。","病気全般としての cancer は通常数えない。種類を分けて述べるときは cancers と複数形にもなる。"],
    ["logic","I understand the logic behind your decision.","あなたの判断の背後にある筋道はわかる。","logic は考えを結びつける論理や筋道。形容詞 logical は『論理的な・筋の通った』。"],
    ["dozen","We bought two dozen eggs for the event.","催しのために卵を二ダース買った。","数詞の後では two dozen と s をつけない。dozens of eggs は正確な数を示さない『何十個もの卵』。"],
    ["harvest","The warm summer led to a good harvest.","暖かい夏のおかげで豊作になった。","harvest は収穫や収穫量。動詞 harvest rice は『米を収穫する』で、育てる段階とは区別する。"],
    ["ingredient","Flour is the main ingredient in this bread.","小麦粉がこのパンの主な材料だ。","ingredient は料理などを作る材料。an ingredient in ... でどの料理に入るかを示せる。"],
    ["hypothesis","The experiment was designed to test the hypothesis.","その実験は仮説を検証するために計画された。","hypothesis は検証前の説明・仮説。複数形は hypotheses で、証明済みの事実とは区別する。"],
    ["voyage","The ship began its voyage across the ocean.","船は大洋を渡る航海を始めた。","voyage は特に海や宇宙を渡る長い旅。日常の短い移動なら trip などを使う。"],
    ["editor","The editor suggested a clearer title.","編集者はもっとわかりやすい題名を提案した。","editor は文章や映像などを編集する人。執筆者 writer と役割が異なる場合がある。"],
    ["option","We have the option of taking an earlier train.","私たちにはもっと早い電車に乗る選択肢がある。","the option of doing は『～する選択肢』。have no option but to do は『～するしかない』になる。"],
    ["hemisphere","The seasons are opposite in the two hemispheres.","二つの半球では季節が反対になる。","hemisphere は球の半分。the Northern Hemisphere は北半球、the Southern Hemisphere は南半球。"],
    ["mechanism","The diagram explains the mechanism inside the lock.","図は錠の内部の仕組みを説明している。","mechanism は装置の機構や物事が働く仕組み。機械そのものを指す machine と区別する。"],
    ["anthropologist","The anthropologist studied how families shared food.","その人類学者は家族が食事をどう分け合うかを研究した。","anthropologist は人間の文化や進化などを研究する人。学問の名前は anthropology。"],
    ["tragedy","The play is a tragedy about a divided family.","その劇は離ればなれになった家族の悲劇だ。","tragedy は不幸な結末の作品や重大な不幸。形容詞 tragic は『悲劇的な』を表す。"],
    ["antibiotic","The textbook explains how antibiotics act on bacteria.","教科書は抗生物質が細菌にどう作用するかを説明している。","antibiotic は細菌に対して使われる薬の種類。bacteria『細菌』と virus『ウイルス』は別のものとして覚える。"],
    ["fare","The bus fare includes one transfer.","バス運賃には一回の乗り換えが含まれる。","fare は乗り物を利用する運賃。入場料などの fee や、商品全般の price と使い分ける。"],
    ["debt","The company paid off its debt over several years.","その会社は数年かけて借金を完済した。","pay off a debt は『借金を返し終える』。debt の b は発音せず、『デット』に近い音になる。"],
    ["curriculum","The school added programming to its curriculum.","学校は教育課程にプログラミングを加えた。","curriculum は学習内容を組み立てた教育課程。複数形には curricula と curriculums がある。"],
    ["component","Each component has a specific function.","各構成部品には特定の役割がある。","component は全体を構成する部品・要素。a component of ... でどの全体の一部かを示す。"],
    ["wheat","The fields were planted with wheat.","その畑には小麦が植えられていた。","wheat は穀物の小麦で、通常数えない。小麦をひいた粉は wheat flour と呼ぶ。"],
    ["usage","The dictionary gives examples of common usage.","その辞書は一般的な語法の例を示している。","usage は言葉などが慣習的にどう使われるか。water usage なら水の使用量という意味にもなる。"],
    ["castle","The castle stands on a hill above the town.","城は町を見下ろす丘の上に建っている。","castle は防御機能などを備えた城。t は通常発音せず、王族の宮殿 palace と区別する。"],
    ["famine","The region suffered a famine after years of drought.","その地域は長年の干ばつの後、飢饉に苦しんだ。","famine は広い地域で食料が深刻に不足すること。個人の空腹 hunger より社会全体の状態を表す。"],
    ["extinction","The museum explains the extinction of several species.","博物館は数種の生物の絶滅について説明している。","extinction は種が存在しなくなること。形容詞 extinct は『絶滅した』で、in danger of extinction は絶滅の危機。"],
    ["purse","She took a coin out of her purse.","彼女は財布から硬貨を取り出した。","purse はイギリス英語では主に小銭などを入れる財布。アメリカ英語ではハンドバッグを指すこともある。"],
    ["folk","The class learned a traditional folk song.","そのクラスは伝統的な民謡を習った。","folk は folk song や folk dance のように民族・民間の伝統を示す。folks はくだけた『人々』。"],
    ["explosion","The explosion shattered the nearby windows.","爆発によって近くの窓が粉々になった。","explosion は急激な爆発。an explosion in demand は需要の急増という比喩的な使い方。"],
    ["portion","Only a small portion of the report is relevant.","報告書のごく一部だけが関係している。","a portion of ... は全体の一部分。料理では一人前などの一盛りを a portion と数える。"],
    ["organism","The microscope revealed tiny organisms in the water.","顕微鏡によって水中の微小な生物が見えた。","organism は生きている個体を指す。臓器を意味する organ とは語尾も意味も異なる。"],
    ["merchant","The merchant sold cloth from distant regions.","その商人は遠い地方の布を売っていた。","merchant は商品を売買する商人。店の従業員一人を指す shop assistant とは立場が異なる。"],
    ["myth","The book retells a myth about the creation of the world.","その本は世界の創造にまつわる神話を語り直している。","myth は古い神話。現代の議論では、広く信じられている誤った考えという意味にもなる。"],
    ["incident","The school recorded the incident in its report.","学校はその出来事を報告書に記録した。","incident は特に問題や異変を伴う出来事。accident は偶然の事故という意味が中心。"],
    ["wildlife","Visitors must avoid disturbing the wildlife.","来訪者は野生生物を邪魔しないようにしなければならない。","wildlife は野生の動植物をまとめて指し、通常数えない。複数の生物でも wildlifes とはしない。"],
    ["congress","Delegates attended an international congress on education.","代表者たちは教育に関する国際会議に出席した。","congress は代表者の大きな会議。アメリカの連邦議会を指す Congress は通常大文字で始める。"],
    ["bay","Small boats were anchored in the bay.","小舟が湾内に停泊していた。","bay は海岸が内側へ入り込んだ湾。at bay という熟語では『寄せつけない状態で』という別の意味になる。"],
    ["penalty","There is a penalty for returning the equipment late.","機器の返却が遅れると罰則がある。","a penalty for ... は『～に対する罰則』。競技の反則による不利益や、契約上の違約金にも使う。"],
    ["heritage","The museum preserves the region's cultural heritage.","博物館は地域の文化遺産を守っている。","heritage は過去から受け継がれた文化や伝統。個人の財産の相続 inheritance と区別する。"],
    ["diversity","The garden demonstrates the diversity of local plants.","その庭は地元の植物の多様性を示している。","diversity は異なる種類や性質が共存すること。形容詞 diverse は『多様な』を表す。"],
    ["thumb","He held the coin between his thumb and forefinger.","彼は親指と人さし指の間に硬貨を挟んだ。","thumb は手の親指。語末の b は発音せず、足の親指は big toe と呼ぶ。"],
    ["geography","In geography, we learned how rivers shape the land.","地理では川が地形をどう作るかを学んだ。","geography は地理学という学問。土地の特徴を指して the geography of a region とも使う。"],
    ["factor","Cost is an important factor in our decision.","費用は私たちの決定の重要な要因だ。","a factor in ... は結果や判断に影響する要素。唯一の原因とは限らない点に注意する。"],
    ["discrimination","The policy aims to prevent discrimination in hiring.","その方針は採用における差別の防止を目指している。","discrimination against ... は『～に対する差別』。区別する能力という別の意味もあり、文脈で判断する。"],
    ["virus","The researchers studied how the virus enters a cell.","研究者たちはウイルスが細胞に入る仕組みを研究した。","virus の複数形は viruses。コンピューターに害を与えるプログラムも a computer virus と呼ぶ。"],
    ["statue","A bronze statue stands in front of the library.","図書館の前に銅像が立っている。","statue は人や動物の姿を立体にした像。status『地位・状態』とつづりを取り違えないようにする。"],
    ["priest","The priest welcomed visitors to the old church.","司祭は古い教会への来訪者を迎えた。","priest は宗教上の儀式を担う聖職者。日本語訳は宗教や宗派により司祭・神父・僧侶などになる。"],
    ["pioneer","She was a pioneer in underwater photography.","彼女は水中写真の先駆者だった。","a pioneer in ... は新しい分野を切り開いた人。動詞 pioneer は新しい技術などを先駆けて開発すること。"],
    ["trait","Curiosity is a trait the two sisters share.","好奇心の強さはその姉妹に共通する特徴だ。","trait は性格や生物の特徴の一つ。a personality trait は性格上の特性を表す。"],
    ["bond","Working together created a strong bond between them.","一緒に働くことで、二人に強い絆が生まれた。","a bond between ... は人同士の結びつき。化学では結合、金融では債券という意味もある。"],
    ["grocery","I stopped at the grocery store on my way home.","私は帰り道に食料品店に寄った。","grocery store は食料品店。購入する食料品などをまとめて指すときは通常 groceries と複数形にする。"],
    ["secretary","The secretary arranged a meeting for next week.","秘書は来週の会議を手配した。","secretary は連絡や事務を担当する人。団体の書記や政府の長官など、組織によって役割が異なる。"],
    ["dialect","My grandfather speaks the local dialect.","祖父は地元の方言を話す。","dialect は地域や集団に特有の言葉遣い。発音だけの特徴を指す accent より広い概念。"],
    ["astronomy","Astronomy helps us understand stars and galaxies.","天文学は恒星や銀河の理解に役立つ。","astronomy は宇宙の天体を研究する学問。占星術 astrology とつづり・意味を区別する。"],
    ["youngster","The coach taught the youngsters how to hold the racket.","コーチは子どもたちにラケットの持ち方を教えた。","youngster は子どもや若者を指すくだけた語。厳密な年齢区分を示す語ではない。"],
    ["substance","The bottle contains a sticky substance.","その瓶には粘り気のある物質が入っている。","substance は材料や物質。the substance of an argument は議論の実質・要点という意味にもなる。"],
    ["finding","The researchers published their findings in a journal.","研究者たちは研究結果を学術誌に発表した。","研究や調査でわかったことは findings と複数形でよく使う。偶然見つけた物そのものとは限らない。"],
    ["strategy","We need a strategy for attracting new members.","新しい会員を集める戦略が必要だ。","a strategy for ... は目標に向けた全体的な方針。個々の手段を指す tactic と区別できる。"],
    ["lung","Air moves into the lungs when we breathe in.","息を吸うと空気が肺に入る。","lung は肺で、左右をまとめて lungs とよく使う。呼吸する動詞 breathe とあわせて覚える。"],
    ["opponent","She shook hands with her opponent after the match.","彼女は試合後に対戦相手と握手した。","opponent は競技・議論などで対する相手。敵意を持つ enemy とは限らない。"],
    ["ritual","The community performs a ritual at the start of spring.","その地域の人々は春の始まりに儀式を行う。","ritual は決まった手順による儀式。a morning ritual は毎朝の決まった習慣という比喩にもなる。"],
    ["outcome","The outcome of the discussion surprised everyone.","話し合いの結末は皆を驚かせた。","the outcome of ... は過程の末に生じた結果。計算で求める数値というより、出来事の帰結に使う。"],
    ["conservation","The group supports the conservation of wetlands.","その団体は湿地の保全を支援している。","conservation は自然や資源を守り維持すること。会話という意味の conversation とつづりが似ているので注意。"],
    ["mammal","A whale is a mammal, not a fish.","クジラは魚ではなく哺乳類だ。","mammal は哺乳類の動物一個体。複数形 mammals で哺乳類全体を指すこともできる。"],
    ["telescope","We observed the moon through a telescope.","私たちは望遠鏡で月を観察した。","telescope は遠くのものを見る望遠鏡。小さなものを拡大する microscope『顕微鏡』と区別する。"],
    ["refugee","The center provides language classes for refugees.","その施設は難民向けの語学授業を提供している。","refugee は迫害や紛争などから逃れてきた人。移住者全般の immigrant と同じ範囲ではない。"],
    ["code","The club has a code of conduct for all members.","そのクラブには全会員向けの行動規範がある。","a code of conduct は行動の規則。code は暗号やコンピューターのコードという別の意味も持つ。"],
    ["flavor","The herbs add flavor to the soup.","香草がスープに風味を加える。","flavor は味や香りが作る風味。a lemon flavor はレモン味で、イギリス式では flavour とつづる。"],
    ["particle","Tiny particles of dust floated in the light.","微小なほこりの粒が光の中を漂っていた。","a particle of ... は非常に小さな粒。物理学の粒子にも、文法の小辞にも使われる。"],
    ["nursing","She is studying nursing at college.","彼女は大学で看護を学んでいる。","nursing は看護という活動・分野。仕事をする人は nurse と呼び、nursing care は看護ケア。"],
    ["suicide","The organization runs a suicide prevention program.","その団体は自殺予防のプログラムを運営している。","suicide は自殺を意味する名詞。suicide prevention のように、別の名詞を修飾する形でも使われる。"],
    ["habitat","The forest is an important habitat for these birds.","その森はこれらの鳥の重要な生息地だ。","habitat は生物が自然に生活する環境。habit『習慣』と似ているが、語尾も意味も異なる。"],
    ["bullying","The school has a clear policy against bullying.","その学校にはいじめに反対する明確な方針がある。","bullying はいじめという行為を表す通常数えない名詞。動詞の原形は bully。"],
    ["dinosaur","The museum displays a dinosaur skeleton.","その博物館は恐竜の骨格を展示している。","dinosaur は恐竜。a dinosaur skeleton では dinosaur が名詞 skeleton を修飾している。"],
    ["council","The local council approved the new playground.","地方議会は新しい遊び場の設置を承認した。","council は地方議会や協議会。counsel『助言』は同じような発音でも別のつづりの語。"],
    ["gender","The survey examined differences in participation by gender.","その調査はジェンダー別の参加状況の違いを調べた。","gender は社会的な性別などを表す。文法では名詞の性を指す場合もあり、分野に応じて意味を読む。"],
    ["surgery","The hospital has a room used for surgery.","その病院には手術用の部屋がある。","手術という処置全般は surgery と数えず表せる。外科医は surgeon で、関連語として覚える。"],
    ["innovation","The award recognizes innovation in public transport.","その賞は公共交通の革新を評価している。","innovation は新しい方法を導入すること。一つの新機軸は an innovation と数えられる。"],
    ["protein","Beans are a source of protein.","豆類はタンパク質の供給源だ。","栄養素としての protein は通常数えない。種類の異なるタンパク質を指す場合は proteins とも使う。"],
    ["nutrition","The course covers nutrition and food preparation.","その講座は栄養と調理を扱う。","nutrition は栄養や栄養摂取の過程。個々の栄養素を指す nutrient と区別する。"],
    ["disaster","The town rebuilt the bridge after the disaster.","その町は災害の後、橋を再建した。","disaster は大きな被害を生む出来事。会話では失敗を強めて The party was a disaster. と言うこともある。"],
    ["emission","The factory reduced its carbon emissions.","工場は炭素の排出量を減らした。","emission は排出すること。排出物や排出量には emissions と複数形をよく使う。"],
    ["ape","The documentary follows a group of apes in the forest.","その記録映画は森の類人猿の群れを追っている。","ape は類人猿。monkey と同じ分類ではなく、ゴリラやチンパンジーなどを指す。"],
    ["molecule","A water molecule contains two hydrogen atoms.","水分子は水素原子を二個含む。","molecule は原子が結びついた分子。atom『原子』と大きさの段階を区別する。"],
    ["sweat","Sweat ran down his face after the race.","競走の後、彼の顔を汗が流れた。","汗という物質は sweat と通常数えない。動詞 sweat は『汗をかく』。"],
    ["transplant","The article describes a successful heart transplant.","その記事は成功した心臓移植について述べている。","a transplant は移植手術や移植されたもの。動詞では植物を植え替える意味にも使う。"],
    ["species","Several species of birds nest here.","数種類の鳥がここに巣を作る。","species は単数も複数も同じ形。one species と two species の両方で s が残る。"],
    ["tip","There is a drop of paint on the tip of the brush.","筆先に絵の具が一滴ついている。","the tip of ... は先端。a useful tip は『役立つ助言』という別の意味になる。"],
    ["cattle","The cattle are grazing in the field.","牛たちは野原で草を食べている。","cattle は牛を集団として表す複数扱いの語。a cattle とはせず、一頭なら a cow などを使う。"],
    ["density","The city has a high population density.","その都市は人口密度が高い。","density は一定の範囲にどれだけ詰まっているか。population density は人口密度という組み合わせ。"],
    ["concept","The teacher explained the concept of gravity.","先生は重力の概念を説明した。","the concept of ... は『～という概念』。具体的な物そのものより、それを捉える考え方を指す。"],
    ["pale","He looked pale after the long journey.","長旅の後、彼は顔色が悪く見えた。","pale は色が薄い・青白いこと。pale blue は薄い青で、肌の状態以外にも使う。"],
    ["precious","These letters are precious to me.","この手紙は私にとってかけがえのないものだ。","precious to someone は人にとって大切なこと。値段だけでなく個人的な価値も表す。"],
    ["loyal","She remained loyal to her team.","彼女はチームに忠実であり続けた。","be loyal to ... は人や集団を裏切らず支えること。royal『王室の』と最初の音が異なる。"],
    ["isolated","The village was isolated by heavy snow.","村は大雪で孤立した。","isolated は周囲とのつながりを断たれた状態。an isolated incident は単発の出来事を指す。"],
    ["generous","He was generous with his time and advice.","彼は時間も助言も惜しまず与えた。","generous with ... は『～を惜しまない』。お金だけでなく、時間や助けにも使える。"],
    ["tropical","The garden contains many tropical plants.","その庭には多くの熱帯植物がある。","tropical は熱帯に関する形容詞。地域としての熱帯は the tropics と表す。"],
    ["reluctant","She was reluctant to speak in front of the class.","彼女はクラスの前で話すのをためらっていた。","be reluctant to do は気が進まない状態。単に能力がないという意味ではない。"],
    ["vague","He gave only a vague explanation.","彼は漠然とした説明しかしなかった。","vague は内容や輪郭がはっきりしないこと。a vague memory は曖昧な記憶。"],
    ["vast","A vast desert stretched beyond the mountains.","山の向こうに広大な砂漠が広がっていた。","vast は面積や量が非常に大きいこと。the vast majority は圧倒的多数を表す。"],
    ["numerous","We received numerous questions after the talk.","講演後、私たちは多数の質問を受けた。","numerous は many に近い改まった形容詞。通常は数えられる名詞の複数形を修飾する。"],
    ["rural","Bus services are limited in rural areas.","農村部ではバスの便が限られている。","rural は田園や農村に関すること。都市の urban と対で覚えられる。"],
    ["widespread","The storm caused widespread damage.","嵐は広い範囲に被害をもたらした。","widespread は地域や人々の間に広く及ぶこと。程度の強さより、広がる範囲を表す。"],
    ["complicated","The instructions were more complicated than expected.","説明は予想より複雑だった。","complicated は多くの要素が絡み、理解しにくいこと。形容する対象を主語にして使える。"],
    ["visible","The mountain is visible from our classroom.","私たちの教室から山が見える。","visible from ... は『～から見える』。反対は invisible『見えない』。"],
    ["raw","The salad contains raw carrots and cabbage.","サラダには生のニンジンとキャベツが入っている。","raw は加熱や加工をしていないこと。raw data は未加工のデータを指す。"],
    ["remote","The researchers stayed in a remote mountain village.","研究者たちは山奥のへんぴな村に滞在した。","remote は人里や中心地から遠いこと。remote control は離れた場所からの操作を表す。"],
    ["urgent","The message says the repairs are urgent.","そのメッセージには修理が急務だとある。","urgent はすぐ対処する必要があること。重要な important でも、必ずしも緊急とは限らない。"],
    ["silly","I made a silly mistake in the calculation.","私は計算でうっかりした間違いをした。","silly は分別がない・ばかげたこと。軽い失敗やふざけた様子にも使う。"],
    ["striking","There is a striking difference between the two designs.","二つの設計には目立った違いがある。","striking は注意を引くほど際立つこと。この例では実際に何かを打つ意味ではない。"],
    ["adequate","The room has adequate space for ten people.","その部屋には十人に十分な広さがある。","adequate は必要な基準を満たす程度。優れている excellent とは区別する。"],
    ["extraordinary","She has an extraordinary memory for faces.","彼女は人の顔を覚える並外れた記憶力を持っている。","extraordinary は普通から大きく外れること。よい意味の優秀さにも、非常に奇妙なことにも使う。"],
    ["odd","I heard an odd noise behind the door.","ドアの向こうで妙な音がした。","odd は普通と違って妙なこと。odd numbers は奇数で、even numbers『偶数』と対になる。"],
    ["abstract","The lesson makes abstract ideas easier to understand.","その授業は抽象的な考えを理解しやすくする。","abstract は具体的な物より概念に関すること。反対方向の語は concrete『具体的な』。"],
    ["mutual","The agreement is based on mutual trust.","その合意は相互の信頼に基づいている。","mutual は双方が共有する、または互いに向けること。a mutual friend は共通の友人。"],
    ["excessive","Excessive noise can make it hard to concentrate.","過度の騒音は集中を難しくすることがある。","excessive は適切な限度を超えること。単に多いのでなく、多すぎるという評価を含む。"],
    ["ashamed","I felt ashamed of my unkind words.","私は自分の不親切な言葉を恥じた。","be ashamed of ... は自分の行動などを恥じること。人前で照れる shy とは異なる。"],
    ["tremendous","The volunteers made a tremendous effort.","ボランティアたちは非常に大きな努力をした。","tremendous は量・程度がとても大きいこと。a tremendous success は大成功を表す。"],
    ["inevitable","Some delays are inevitable during major repairs.","大規模な修理中は多少の遅れが避けられない。","inevitable は防ぎようがなく起こること。単に起こりそうな likely より強い意味。"],
    ["pure","The necklace is made of pure silver.","そのネックレスは純銀製だ。","pure は他の物が混ざっていないこと。pure luck は『まったくの幸運』という強調になる。"],
    ["stable","The table is stable even on the uneven floor.","その机はでこぼこの床でもぐらつかない。","stable は揺れや変化が少なく安定していること。名詞 a stable は馬小屋という別の意味。"],
    ["indifferent","He seemed indifferent to the result.","彼は結果に無関心なようだった。","be indifferent to ... は『～を気にかけない』。different from ... とは意味も前置詞も異なる。"],
    ["aggressive","The dog became aggressive when strangers approached.","知らない人が近づくと犬は攻撃的になった。","aggressive は攻撃するような強い態度。事業などでは積極的に押し進める意味にもなる。"],
    ["ultimate","Our ultimate goal is to make the service accessible to everyone.","私たちの最終目標は誰もがそのサービスを使えるようにすることだ。","ultimate は一連の段階の最後や究極を表す。ultimate goal は最終的に達したい目標。"],
    ["shy","She is shy around people she does not know.","彼女は知らない人の前では内気になる。","shy は人前で緊張して控えめになること。恥じる気持ちの ashamed とは区別する。"],
    ["solar","The roof is covered with solar panels.","屋根は太陽光パネルで覆われている。","solar は太陽に関する形容詞。solar system は太陽系という組み合わせ。"],
    ["profound","The visit had a profound effect on her.","その訪問は彼女に深い影響を与えた。","profound は影響や理解などが非常に深いこと。単に物理的な深さなら deep をよく使う。"],
    ["subtle","There is a subtle difference in flavor.","風味に微妙な違いがある。","subtle は簡単には気づかない繊細な違いなどを表す。b は発音しない。"],
    ["conservative","He takes a conservative approach to estimating costs.","彼は費用の見積もりに慎重な方法を取る。","conservative は急な変化やリスクを避けること。政治上の保守的という意味以外にも使う。"],
    ["brave","It was brave of her to admit the error.","間違いを認めた彼女は勇敢だった。","It is brave of someone to do は人の行動を勇敢だと評価する形。人物の性質には of を使う。"],
    ["intense","The players trained in intense heat.","選手たちは厳しい暑さの中で練習した。","intense は強さや程度が非常に高いこと。intense concentration は強い集中を表す。"],
    ["alcoholic","The menu lists alcoholic and non-alcoholic drinks separately.","メニューではアルコール飲料とノンアルコール飲料が分けて載っている。","形容詞 alcoholic はアルコールを含むこと。alcohol という名詞と語尾を区別する。"],
    ["manual","The machine can be switched to manual control.","その機械は手動操作に切り替えられる。","manual は手で行うこと。名詞 a manual は操作方法などを記した手引書を指す。"],
    ["cruel","It is cruel to laugh at someone's suffering.","人の苦しみを笑うのは残酷だ。","cruel は相手の苦痛に無情なこと。be cruel to ... で『～に残酷な扱いをする』。"],
    ["rational","We need a rational explanation for the change.","その変化には筋の通った説明が必要だ。","rational は理由や論理に基づくこと。反対は irrational『不合理な』。"],
    ["initial","My initial reaction was surprise.","私の最初の反応は驚きだった。","initial は始めの段階を表す形容詞。名詞の initials は氏名の頭文字を指す。"],
    ["immune","The textbook describes the immune system.","教科書は免疫系について説明している。","immune system は体を守る免疫系。be immune to ... は『～の影響を受けない』という比喩にもなる。"],
    ["linguistic","The study compares linguistic patterns in two languages.","その研究は二つの言語の言語的なパターンを比較している。","linguistic は言語に関する形容詞。学問としての言語学は linguistics。"],
    ["crucial","Timing is crucial to the success of the experiment.","時機がその実験の成功に決定的に重要だ。","crucial to ... は結果を左右するほど重要なこと。単に関係があるという意味より強い。"],
    ["verbal","The teacher gave verbal instructions before handing out the sheet.","先生はプリントを配る前に口頭で指示した。","verbal は言葉によること。文脈によっては書面と対比した『口頭の』を表す。"],
    ["optimistic","We are optimistic about the project's future.","私たちはその事業の将来を楽観している。","be optimistic about ... はよい結果を期待すること。反対は pessimistic『悲観的な』。"],
    ["flexible","The course offers flexible study hours.","その講座では学習時間を柔軟に選べる。","flexible は状況に合わせて変えられること。物が曲がりやすいという意味にも使う。"],
    ["grateful","I am grateful to you for your help.","助けてくれたことをあなたに感謝しています。","grateful to 人 for 事柄で感謝の相手と理由を示す。graceful『優雅な』とは別の語。"],
    ["lively","We had a lively discussion after the film.","映画の後、私たちは活発に話し合った。","lively は生き生きして活気のある形容詞。-ly で終わっていても、ここでは副詞ではない。"],
    ["overwhelming","The proposal received overwhelming support.","その提案は圧倒的な支持を得た。","overwhelming は他を圧倒するほど大きいこと。感情については対処しきれない強さも表す。"],
    ["abundant","Fresh water is abundant in this region.","この地域には淡水が豊富にある。","abundant は十分以上にたくさんあること。abundant resources は豊富な資源を表す。"],
    ["selfish","It was selfish to take all the seats for our group.","自分たちのグループだけで席を全部取るのは利己的だった。","selfish は他人を考えず自分の利益を優先すること。self の後の -ish まで含めて覚える。"],
    ["ugly","An ugly stain spoiled the clean wall.","見苦しいしみがきれいな壁を台無しにした。","ugly は見た目が不快なこと。an ugly argument は険悪な口論という意味にもなる。"],
    ["racial","The exhibition examines racial discrimination in history.","その展示は歴史上の人種差別を考察している。","racial は人種に関する形容詞。racial discrimination は人種差別という組み合わせ。"],
    ["prominent","A prominent scientist gave the opening lecture.","著名な科学者が開会講演を行った。","prominent は目立つ・重要な地位にあること。a prominent feature は目立つ特徴になる。"],
    ["controversial","The new road is a controversial issue in the town.","新しい道路はその町で賛否の分かれる問題だ。","controversial は意見が強く分かれて議論を呼ぶこと。単に間違っているという意味ではない。"],
    ["federal","The project received support from the federal government.","その事業は連邦政府から支援を受けた。","federal は複数の州などからなる連邦に関すること。州政府の state government と区別する。"],
    ["ridiculous","The price seemed ridiculous for such a small item.","こんな小さな物にその値段はばかげていると思えた。","ridiculous は理に合わず笑ってしまうほどのこと。相手の案に直接使うと強い否定になる。"],
    ["imaginary","The story takes place on an imaginary island.","その物語の舞台は架空の島だ。","imaginary は実在せず想像上にあること。imaginative『想像力豊かな』とは意味が異なる。"],
    ["harsh","The plants survive in harsh conditions.","その植物は厳しい環境で生き延びる。","harsh は耐えにくいほど厳しい・不快なこと。harsh words は手厳しい言葉を表す。"],
    ["random","The computer chose ten names at random.","コンピューターは十人の名前を無作為に選んだ。","at random は決まった基準なく選ぶこと。形容詞なら a random sample『無作為標本』。"],
    ["adolescent","The program supports adolescent learners.","そのプログラムは思春期の学習者を支援している。","adolescent は子どもから大人へ移る時期の形容詞。名詞 an adolescent はその時期の若者。"],
    ["up-to-date","Make sure your contact details are up-to-date.","連絡先が最新の状態であることを確かめてください。","up-to-date は最新の情報が反映されていること。keep ... up-to-date は最新に保つという表現。"],
    ["liberal","The essay discusses liberal ideas about individual freedom.","その随筆は個人の自由に関する自由主義的な考えを論じている。","liberal は自由を重視すること。政治上の意味は国や文脈で異なり、一つの政党名とは限らない。"],
    ["prior","No prior experience is needed for this course.","この講座に事前の経験は不要だ。","prior は時間的に前のこと。prior to ... は before に近い改まった『～より前に』。"],
    ["moderate","The recipe requires moderate heat.","そのレシピでは中程度の火力を使う。","moderate は強すぎず弱すぎない程度。意見については『穏健な』という意味になる。"],
    ["fluent","She is fluent in both Japanese and English.","彼女は日本語と英語の両方を流暢に話す。","be fluent in + 言語で、その言語を滑らかに使えることを表す。副詞は fluently。"],
    ["elaborate","They built an elaborate model of the town.","彼らは町の精巧な模型を作った。","形容詞 elaborate は細部まで手の込んだこと。動詞 elaborate on ... は詳しく説明する意味。"],
    ["incredible","The view from the summit was incredible.","山頂からの眺めは信じられないほどすばらしかった。","incredible は信じがたいこと。会話では驚くほどよいという強調にもよく使う。"],
    ["radical","The plan requires a radical change in how we work.","その計画には働き方の根本的な変更が必要だ。","radical は根本から大きく変えること。政治では急進的なという意味にもなる。"],
    ["acid","Some plants grow well in acid soil.","酸性の土でよく育つ植物もある。","acid は形容詞で酸性の、名詞で酸。acidic も酸性を表す形容詞として使う。"],
    ["deaf","The theater provides captioned performances for deaf audiences.","その劇場は耳の聞こえない観客向けに字幕付き公演を行っている。","deaf は聞こえない・聞こえにくい状態を表す形容詞。人を示すには deaf people などと名詞を添える。"],
    ["medieval","The town still has a medieval bridge.","その町には今も中世の橋がある。","medieval は中世に関する形容詞。時代名としての中世は the Middle Ages。"],
    ["ecological","The study examines the ecological effects of the dam.","その研究はダムが生態系に及ぼす影響を調べている。","ecological は生物と環境の関係に関すること。学問の生態学は ecology。"],
    ["slight","There is a slight difference in the two colors.","二つの色にはわずかな違いがある。","slight は程度が小さいこと。副詞 slightly なら slightly different『少し違う』となる。"],
    ["ignorant","I was ignorant of the local customs.","私はその土地の習慣を知らなかった。","be ignorant of ... は知識がない状態。人全体を ignorant と呼ぶと侮辱的に響く場合がある。"],
    ["cognitive","The game involves several cognitive skills.","そのゲームにはいくつかの認知能力を使う。","cognitive は記憶・思考・理解などに関すること。cognition は認知という名詞。"],
    ["absolutely","You are absolutely right about the date.","日付についてはあなたがまったく正しい。","absolutely は完全にという強調。Absolutely! だけでも強い同意の返事になる。"],
    ["virtually","The two versions are virtually identical.","二つの版はほとんど同じだ。","virtually は実質的にほぼという意味。必ずしも仮想空間について述べているわけではない。"],
    ["somewhat","The instructions were somewhat confusing.","その説明は多少わかりにくかった。","somewhat はある程度という控えめな表現。形容詞の前に置き、断定の強さを和らげられる。"],
    ["merely","I was merely asking a question.","私はただ質問していただけだ。","merely はそれ以上ではないという限定。only に近く、行為の意図や程度を小さく示す。"],
    ["literally","The sign literally says 'Keep out.'","その看板には文字どおり『立入禁止』と書いてある。","literally は比喩でなく言葉どおりという意味。誇張の強調にも使われるが、説明文では区別を意識する。"],
    ["seemingly","The seemingly simple task took hours.","一見簡単そうな作業に何時間もかかった。","seemingly は見たところそうであること。実際にもそうだと断定せず、外見上の印象を示す。"],
    ["regardless","Everyone can join regardless of experience.","経験に関係なく誰でも参加できる。","regardless of ... は『～にかかわらず』。無視する条件を of の後に置く。"],
    ["thoroughly","Read the instructions thoroughly before starting.","始める前に説明を隅々まで読んでください。","thoroughly は抜けなく徹底的にという副詞。through『～を通って』とつづりを取り違えないようにする。"],
    ["submit","Please submit your application by Monday.","月曜日までに申込書を提出してください。","submit A to B は『BにAを提出する』。過去形 submitted では t を重ねる。"],
    ["tempt","The warm weather tempted us to eat outside.","暖かい天気に誘われ、外で食事をしたくなった。","tempt someone to do は人をその気にさせること。悪い誘惑だけに限らない。"],
    ["resign","She resigned from the committee last month.","彼女は先月、委員を辞任した。","resign from ... は役職や組織を辞すること。be resigned to ... は諦めて受け入れる別の表現。"],
    ["conform","The building must conform to the safety standards.","建物は安全基準に適合しなければならない。","conform to ... は基準・規則などに従うこと。confirm『確認する』と母音が異なる。"],
    ["confine","Please confine your comments to the main topic.","発言は主な話題に絞ってください。","confine A to B は『AをBに限定する』。物理的に閉じ込める場合にも使う。"],
    ["assemble","We assembled the shelves using the instructions.","私たちは説明書を見て棚を組み立てた。","assemble は部品を集めて組み立てること。人を主語にすると集合するという意味にもなる。"],
    ["dedicate","She dedicated the book to her grandmother.","彼女はその本を祖母にささげた。","dedicate A to B は『BにAをささげる』。時間や人生をある目的にあてる場合にも使う。"],
    ["advocate","The group advocates greater access to public libraries.","その団体は公共図書館をもっと利用しやすくすることを主張している。","advocate は支持して公に勧めること。advocate doing と -ing 形も続けられる。"],
    ["thrive","These plants thrive in moist soil.","これらの植物は湿った土でよく育つ。","thrive は条件に恵まれ元気に成長・繁栄すること。thrive in ... で環境を示す。"],
    ["provoke","The decision provoked a long debate.","その決定は長い議論を引き起こした。","provoke は強い反応を起こさせること。怒りや議論などが目的語になりやすい。"],
    ["dictate","The weather will dictate when we can leave.","出発できる時刻は天候次第になる。","dictate は条件などが決定すること。言葉を書き取らせる『口述する』という意味もある。"],
    ["exploit","The design exploits the natural light from the windows.","その設計は窓からの自然光を活用している。","exploit は資源などを利用すること。人が目的語なら不当に利用する『搾取する』という意味になり得る。"],
    ["surrender","The army surrendered after a long siege.","軍は長い包囲の後に降伏した。","surrender は抵抗をやめて降伏すること。surrender something は権利や所持品を明け渡すこと。"],
    ["reproduce","The machine can reproduce the drawing at any size.","その機械は図面を任意の大きさで複製できる。","reproduce は再び作る・複製すること。生物が主語なら繁殖するという意味にもなる。"],
    ["acknowledge","He acknowledged that the instructions were unclear.","彼は説明が不明瞭だったと認めた。","acknowledge that ... は事実を認めること。賛成する agree と同じ意味とは限らない。"],
    ["swell","The river swelled after the heavy rain.","大雨の後、川は増水した。","swell は膨らむ・大きくなること。過去形 swelled、過去分詞 swollen または swelled。"],
    ["shed","Some trees shed their leaves in autumn.","秋に葉を落とす木もある。","shed は葉・毛などを落とすこと。原形・過去形・過去分詞がすべて shed。"],
    ["wind","The path winds through the forest.","道は森の中を曲がりくねっている。","この動詞 wind は『ワインド』に近い発音。活用は wind–wound–wound で、風の wind と発音が違う。"],
    ["cite","Please cite the source of each quotation.","各引用の出典を示してください。","cite は根拠や出典を挙げること。cite A as B は『AをBとして引き合いに出す』。"],
    ["digest","I need time to digest all this information.","この情報をすべて理解するには時間が必要だ。","digest は食物の消化から、情報を理解して取り込む意味にもなる。動詞は後半を強く読む。"],
    ["skip","Do not skip the final step.","最後の手順を飛ばさないでください。","skip は行わずに飛ばすこと。skipped と skipping では p を重ねる。"],
    ["bind","She bound the papers together with string.","彼女はひもで書類をまとめて縛った。","bind は結びつける・束縛すること。活用は bind–bound–bound。"],
    ["dissolve","Dissolve the sugar in warm water.","砂糖をぬるま湯に溶かしてください。","dissolve A in B は液体中にAを溶かすこと。熱で固体自体が液体になる melt と区別する。"],
    ["implement","The school will implement the new timetable next term.","学校は次の学期に新しい時間割を実施する。","implement は決めた計画などを実行に移すこと。考案する段階ではなく運用の開始に焦点がある。"],
    ["steer","He steered the boat toward the shore.","彼は船を岸へ向けて操縦した。","steer は進む方向を操作すること。steer a discussion は議論をある方向へ導く比喩。"],
    ["congratulate","We congratulated her on winning the prize.","私たちは受賞した彼女を祝福した。","congratulate 人 on 事柄で祝う相手と理由を示す。on の後は winning のような -ing 形も使う。"],
    ["designate","This area is designated as a quiet zone.","この区域は静かにする場所に指定されている。","designate A as B は『AをBに指定する』。役割や用途を正式に定める語。"],
    ["violate","Sharing the password would violate the rules.","パスワードを共有すると規則に違反する。","violate は規則や権利を侵すこと。目的語を直接続け、violate against とはしない。"],
    ["presume","I presume you have already read the message.","あなたはもうメッセージを読んだと思います。","presume は根拠や常識からそうだと思うこと。確かめた事実ではない点を含む。"],
    ["recruit","The club is recruiting new members.","そのクラブは新しい会員を募集している。","recruit は新しい人を集めて加えること。名詞 a recruit は新入りを指す。"],
    ["coincide","The festival coincides with the school holidays.","その祭りは学校の休みと時期が重なる。","coincide with ... は同時に起きる、または一致すること。with を含めて覚える。"],
    ["enforce","The staff must enforce the safety rules.","職員は安全規則を確実に守らせなければならない。","enforce は規則を実際に守らせること。規則を制定すること自体とは区別する。"],
    ["displace","The flood displaced hundreds of residents.","洪水で数百人の住民が住む場所を追われた。","displace は元の場所から移す・追いやること。技術が旧製品に取って代わる場合にも使う。"],
    ["shrink","The sweater shrank in the wash.","セーターは洗濯で縮んだ。","shrink は小さくなる・縮めること。活用は shrink–shrank–shrunk。"],
    ["betray","He betrayed my trust by sharing the secret.","彼は秘密を漏らして私の信頼を裏切った。","betray someone's trust は信頼を裏切ること。表情が感情を漏らすという意味にも使う。"],
    ["comprise","The course comprises six short lessons.","その講座は六つの短い授業からなる。","全体 comprise 部分の形で『全体が部分からなる』。この形では of を入れない。"],
    ["indulge","On weekends, I indulge in a long breakfast.","週末にはゆっくり朝食を楽しむ。","indulge in ... は好きなことを思うままに楽しむこと。少し贅沢を許す感覚がある。"],
    ["penetrate","Sunlight barely penetrates the thick forest.","日光はうっそうとした森にほとんど入り込まない。","penetrate は表面を越えて中へ入ること。対象を直接続けられ、penetrate the wall などと使う。"],
    ["devastate","The storm devastated several coastal villages.","嵐は海岸沿いの数か所の村を壊滅させた。","devastate は非常に大きな被害を与えること。人の気持ちなら深く打ちのめす意味にもなる。"],
    ["plunge","The temperature plunged overnight.","気温は一晩で急落した。","plunge は急に落ちる・飛び込むこと。plunge into water なら水に勢いよく飛び込む動作。"],
    ["bounce","The ball bounced off the wall.","ボールは壁に当たって跳ね返った。","bounce off ... は『～から跳ね返る』。bounce a ball はボールをつくという他動詞の用法。"],
    ["contradict","The new evidence contradicts his account.","新しい証拠は彼の説明と矛盾する。","contradict は相手の内容と食い違うこと。目的語を直接取り、contradict with とは通常しない。"],
    ["prescribe","The doctor prescribed medicine for the infection.","医師はその感染症に対して薬を処方した。","prescribe は薬や処置を専門家が指示すること。名詞 prescription は処方・処方箋。"],
    ["oppress","The novel describes people oppressed by a harsh ruler.","その小説は厳しい支配者に抑圧された人々を描いている。","oppress は権力を使って自由などを奪い苦しめること。単に意見が対立する oppose とは異なる。"],
    ["cherish","I cherish the memories of our summer trips.","私は夏の旅行の思い出を大切にしている。","cherish は愛情をもって大切にすること。思い出・希望・人などが目的語になる。"],
    ["illuminate","A small lamp illuminated the desk.","小さなランプが机を照らしていた。","illuminate は光で照らすこと。例や説明が問題を明らかにするという比喩にも使う。"],
    ["trigger","The announcement triggered a wave of questions.","その発表をきっかけに次々と質問が出た。","trigger は反応や出来事の引き金になること。すべての原因でなく直接のきっかけを示す。"],
    ["commute","She commutes to work by train.","彼女は電車で通勤している。","commute to ... は日常的に通うこと。住む場所と仕事・学校の間の定期的な移動を指す。"],
    ["induce","The discount induced more people to try the service.","割引により、そのサービスを試す人が増えた。","induce someone to do は人を～するように促すこと。状態を引き起こす意味でも使う。"],
    ["utilize","The design utilizes space under the stairs.","その設計は階段下の空間を活用している。","utilize は目的に役立てて利用する改まった語。日常の文章では use で十分な場合も多い。"],
    ["snap","The dry branch snapped in the wind.","乾いた枝が風でぽきっと折れた。","snap は短い鋭い音を立てて折れること。snapped と snapping では p を重ねる。"],
    ["donate","They donated books to the school library.","彼らは学校図書館に本を寄贈した。","donate A to B は『BにAを寄付・寄贈する』。お金以外の物も対象になる。"],
    ["hatch","The eggs hatched early in the morning.","卵は朝早くにかえった。","hatch は卵がかえる・ひなをかえすこと。hatch a plan は計画をひそかに練る比喩。"],
    ["enclose","A low wall encloses the garden.","低い壁が庭を囲んでいる。","enclose は周囲を囲むこと。enclose a document with a letter は書類を同封する意味。"],
    ["prevail","A calm atmosphere prevailed in the room.","部屋には落ち着いた雰囲気が広がっていた。","prevail は広く存在する・優勢になること。prevail over ... は相手に勝るという意味。"],
    ["sigh","She sighed with relief when the keys were found.","鍵が見つかり、彼女はほっとため息をついた。","sigh with relief は安心のため息をつくこと。疲れや失望だけでなく安堵にも使う。"],
    ["leak","Water is leaking from the pipe.","パイプから水が漏れている。","leak from ... は外へ漏れ出すこと。秘密の情報を漏らす意味にも使う。"],
    ["compel","The damage compelled us to close the bridge.","被害のため、私たちは橋を閉鎖せざるを得なかった。","compel someone to do は人に行動を強いること。過去形 compelled では l を重ねる。"],
    ["crush","Crush the biscuits into small pieces.","ビスケットを細かく砕いてください。","crush は強く押して潰す・砕くこと。ぶつかる crash とは母音と意味が異なる。"],
    ["comprehend","I could not comprehend the complicated instructions.","私は複雑な説明を理解できなかった。","comprehend は内容を十分に理解する改まった語。特に難しい事柄の理解について使われる。"],
    ["negotiate","The two groups negotiated a new agreement.","二つの集団は新たな合意に向けて交渉した。","negotiate with 人 about 事柄とも使える。交渉して条件を調整することを表す。"],
    ["persist","The noise persisted throughout the night.","騒音は一晩中続いた。","persist は状態が消えず続くこと。persist in doing は困難があっても行動を続けること。"],
    ["multiply","Multiply six by four to get twenty-four.","六に四を掛けると二十四になる。","multiply A by B は『AにBを掛ける』。数が増える・増やす意味もある。"],
    ["conceive","I cannot conceive of a city without parks.","公園のない都市は私には想像できない。","conceive of ... は考えとして思い描くこと。conceive a plan は計画を考案する意味。"],
    ["compensate","The company compensated residents for the damage.","会社は住民に被害を補償した。","compensate 人 for 損失で補償の相手と理由を示す。compensate for ... は埋め合わせること。"],
    ["suspend","The match was suspended because of the storm.","試合は嵐のため一時中断された。","suspend は一時的に止めること。suspend a lamp from the ceiling はつるすという別の用法。"],
    ["stir","The speech stirred hope among the listeners.","演説は聞き手の心に希望をかき立てた。","stir は感情を動かすこと。stir the soup はかき混ぜる動作で、過去形 stirred は r を重ねる。"],
    ["soak","Soak the cloth in warm water.","布をぬるま湯に浸してください。","soak A in B は『AをBに浸す』。be soaked は水分でびしょぬれになった状態。"],
    ["refine","We refined the design after testing the first model.","最初の模型を試した後、設計を改良した。","refine は細部を改善して質を高めること。物質から不純物を除く精製の意味もある。"],
    ["arouse","The unusual painting aroused my curiosity.","その珍しい絵が私の好奇心をかき立てた。","arouse は感情や関心を呼び起こすこと。自ら生じる arise とは動詞の形も使い方も違う。"],
    ["precede","A short introduction preceded the main talk.","本題の話の前に短い紹介があった。","precede は時間や順序で前に来ること。進むという proceed とつづりを区別する。"],
    ["render","The damage rendered the bridge unsafe.","その損傷で橋は安全でない状態になった。","render A + 形容詞で『Aを～の状態にする』。例文では unsafe が結果の状態。"],
    ["mount","They mounted the screen on the wall.","彼らはスクリーンを壁に取り付けた。","mount A on B は『AをBに据え付ける』。mount a horse は馬に乗る意味になる。"],
    ["retreat","The hikers retreated to the shelter when the storm began.","嵐が始まると登山者たちは避難小屋へ引き返した。","retreat は危険などから後退すること。retreat to ... で退く先を示す。"],
    ["startle","The sudden bell startled everyone.","突然のベルに皆がびくっとした。","startle は突然の刺激で驚かせること。驚いた側は startled と表す。"],
    ["dare","I did not dare to open the mysterious box.","私はその謎の箱を開ける勇気がなかった。","dare to do は思い切って～すること。否定や疑問では dare do の形も使われる。"],
    ["sphere","The issue lies outside my sphere of responsibility.","その問題は私の責任範囲の外にある。","sphere は球体から転じて活動の範囲・領域。a sphere of influence は勢力範囲。"],
    ["sequence","Put the pictures in the correct sequence.","絵を正しい順序に並べてください。","sequence は順番のある連なり。in sequence は順番どおりにという意味。"],
    ["deposit","We paid a deposit to reserve the room.","部屋を予約するために予約金を払った。","deposit は前払い金や預け金。川などの deposits は堆積物という別の意味になる。"],
    ["poll","A recent poll asked residents about the new park.","最近の世論調査では住民に新しい公園について尋ねた。","a poll は意見を尋ねる調査。the polls は選挙の投票や投票所を指す場合がある。"],
    ["caution","Please use caution on the wet stairs.","濡れた階段では注意してください。","caution は危険を避ける慎重さ。with caution は用心してという組み合わせ。"],
    ["rage","He was filled with rage when he saw the damage.","被害を見て、彼は激しい怒りに満たされた。","rage は非常に強い怒り。in a rage は激怒している状態を表す。"],
    ["formula","The teacher wrote the formula on the board.","先生は公式を黒板に書いた。","formula は計算などの公式。a formula for success は成功の方法・秘訣という比喩。"],
    ["plot","The novel has a complicated plot.","その小説は筋が複雑だ。","plot は物語の筋。a plot to do はひそかに企てた計画・陰謀を表す。"],
    ["scope","The question falls outside the scope of this lesson.","その質問はこの授業の範囲を外れている。","the scope of ... は扱う範囲。scope for improvement は改善の余地という意味になる。"],
    ["norm","Working from home has become the norm in this team.","このチームでは在宅勤務が普通になっている。","the norm は通常の基準や標準的な状態。norms は社会的な規範を指す。"],
    ["disgust","She turned away in disgust at the smell.","その臭いに嫌悪を感じ、彼女は顔を背けた。","disgust は強い不快感・嫌悪。in disgust は嫌気がさしてという表現。"],
    ["compromise","We reached a compromise on the schedule.","私たちは予定について妥協点に達した。","reach a compromise は双方が譲り合って合意すること。on で話題を示せる。"],
    ["supervisor","Ask your supervisor to check the completed form.","記入済みの用紙を監督者に確認してもらってください。","supervisor は仕事を監督する立場の人。動詞 supervise は監督・指導すること。"],
    ["paradox","It is a paradox that having more choices can make decisions harder.","選択肢が増えると決めにくくなるのは逆説的だ。","paradox は一見矛盾しているが考える価値のある事柄。単なる誤りとは区別する。"],
    ["tissue","The microscope shows the structure of plant tissue.","顕微鏡で植物組織の構造が見える。","tissue は細胞が集まった組織。a tissue は鼻などを拭くティッシュ一枚の意味にもなる。"],
    ["breakdown","A breakdown in communication caused the delay.","意思疎通がうまくいかず遅れが生じた。","breakdown は機能の停止・崩壊。a breakdown of costs は費用の内訳という別の意味。"],
    ["initiative","She took the initiative and organized the meeting.","彼女は率先して会議を準備した。","take the initiative は主導して行動すること。an initiative は新たな取り組みや施策。"],
    ["fabric","The bag is made from recycled fabric.","そのかばんは再生生地でできている。","fabric は織物や布地。種類を区別すれば fabrics と複数形でも使える。"],
    ["publicity","The exhibition received a lot of publicity.","その展示は多くの宣伝・報道を受けた。","publicity は世間の注目を集める活動や報道。通常数えず、個々の広告 advertisement と区別する。"],
    ["summit","We reached the summit just before noon.","私たちは正午直前に頂上に着いた。","summit は山頂。政治では a summit meeting が首脳会議を表す。"],
    ["flock","A flock of sheep crossed the road.","羊の群れが道路を横切った。","a flock of ... は羊や鳥などの群れ。牛の群れには a herd をよく使う。"],
    ["plague","The history book describes a plague that spread through the city.","その歴史書は都市に広がった疫病を記している。","plague は疫病、特にペストを指すこともある。動詞では問題が絶えず苦しめる意味になる。"],
    ["haste","In my haste, I forgot to lock the door.","急いでいたので、私は鍵をかけ忘れた。","in haste は急いでという意味。通常数えない名詞で、急ぐあまりの不注意を述べる文にも合う。"],
    ["nap","I took a short nap after lunch.","私は昼食後に少し昼寝をした。","take a nap は短時間眠ること。夜のまとまった睡眠ではなく、仮眠やうたた寝を指す。"],
    ["ally","The two countries became allies during the conflict.","二つの国は紛争中に同盟国になった。","ally は共通の目的で協力する国や人。複数形 allies では y を ies に変える。"],
    ["draft","I finished the first draft of my report.","報告書の最初の下書きを書き終えた。","a first draft は初稿。完成版の前に修正する段階を指し、動詞 draft は下書きすること。"],
    ["spectacle","The fireworks were an impressive spectacle.","花火は印象的な光景だった。","spectacle は人の目を引く光景。複数形 spectacles は眼鏡という別の意味になる。"],
    ["premise","The argument rests on a false premise.","その議論は誤った前提に基づいている。","premise は推論の土台となる前提。premises は建物や敷地を表す別の用法もある。"],
    ["asset","Her language skills are a valuable asset to the team.","彼女の語学力はチームにとって貴重な財産だ。","asset は価値をもたらすもの。資産だけでなく、人の能力などにも使える。"],
    ["lag","There is a short lag between the sound and the image.","音と映像の間にわずかなずれがある。","lag は時間的な遅れ。動詞 lag behind ... は後れを取ることを表す。"],
    ["therapy","The center offers several forms of therapy.","その施設は数種類の療法を提供している。","therapy は心身の問題への治療・療法。具体的な種類なら a therapy と数えられる。"],
    ["reception","The visitors received a warm reception.","訪問者たちは温かい歓迎を受けた。","a warm reception は温かなもてなし。建物の受付や放送の受信という意味もある。"],
    ["compound","Water is a compound of hydrogen and oxygen.","水は水素と酸素の化合物だ。","compound は異なる元素が化学的に結びついた物質。単なる混合物 mixture と区別する。"],
    ["blessing","The unexpected rain was a blessing for the farmers.","予期しない雨は農家にとって恵みだった。","a blessing はありがたいもの・幸運。宗教的な祝福を指す場合もある。"],
    ["sensation","I felt a strange sensation in my fingertips.","指先に奇妙な感覚があった。","sensation は身体で感じる感覚。a sensation は大評判を呼ぶものという意味にもなる。"],
    ["recession","Many shops struggled during the recession.","不況の間、多くの店が苦戦した。","recession は経済活動が落ち込む不況。経済の文脈で使うことが多い名詞。"],
    ["pole","They attached the flag to a long pole.","彼らは長い棒に旗を取り付けた。","pole は長い棒。the North Pole は北極で、地球の極を表す意味もある。"],
    ["outlook","The report gives a cautious outlook for next year.","その報告書は来年の慎重な見通しを示している。","outlook は将来の見通し。an outlook on life は人生に対する考え方を表す。"],
    ["endeavor","Restoring the old theater was a community endeavor.","古い劇場の修復は地域全体の取り組みだった。","endeavor は努力を要する試み。動詞 endeavor to do は～しようと努力する改まった形。"],
    ["mercy","The king showed mercy to the prisoners.","王は捕虜たちに慈悲を示した。","show mercy to ... は寛大に扱うこと。at the mercy of ... は相手に左右される状態を表す。"],
    ["counterpart","The Japanese manager met her French counterpart.","日本の管理職はフランス側の同じ役職の人に会った。","counterpart は別の組織などで対応する役割の人・物。単に相手という意味より限定される。"],
    ["session","The afternoon session focused on writing skills.","午後の授業時間は作文の技能に重点を置いた。","session は特定の活動のために区切った時間。会議・授業・練習などに使える。"],
    ["spectrum","The course covers a broad spectrum of topics.","その講座は幅広い分野の話題を扱う。","a spectrum of ... は連続する広い範囲。光の色の帯であるスペクトルにも使う。"],
    ["junk","We cleared the junk out of the garage.","私たちは車庫のがらくたを片づけた。","junk は不要な物をまとめて指す通常数えない名詞。a piece of junk と一つを数えられる。"],
    ["worship","The temple is still used as a place of worship.","その寺院は今も礼拝の場所として使われている。","worship は神などへの崇拝・礼拝。動詞なら目的語を直接続けて worship a god と使う。"],
    ["apt","This road is apt to flood after heavy rain.","この道は大雨の後に冠水しやすい。","be apt to do は～する傾向があること。an apt remark は適切な発言という別の意味。"],
    ["humble","Despite her success, she remained humble.","成功しても、彼女は謙虚なままだった。","humble は自分の重要さを誇示しないこと。a humble home は質素な家を表す。"],
    ["entitled","Members are entitled to use the reading room.","会員には閲覧室を利用する権利がある。","be entitled to do は～する権利があること。a book entitled ... は～という題の本になる。"],
    ["valid","This ticket is valid for one week.","この切符は一週間有効だ。","valid は期限・条件内で有効なこと。a valid argument は筋の通った妥当な議論。"],
    ["faint","We heard a faint sound from the next room.","隣の部屋からかすかな音が聞こえた。","faint は知覚しにくいほど弱いこと。動詞 faint は気を失うという別の意味。"],
    ["stiff","My shoulders felt stiff after the long drive.","長時間の運転で肩がこわばった。","stiff は硬く動きにくい状態。stiff competition は激しい競争という比喩になる。"],
    ["obscure","The reference was too obscure for most readers.","その言及は大半の読者にはわかりにくすぎた。","obscure はあまり知られず理解しにくいこと。動詞では見えなくする・不明瞭にする意味。"],
    ["fierce","The two teams faced fierce competition.","両チームは激しい競争に直面した。","fierce は勢いが強く激しいこと。動物のどう猛さや天候の激しさにも使う。"],
    ["acute","The town faces an acute shortage of water.","その町は深刻な水不足に直面している。","acute は問題が非常に深刻なこと。acute pain は鋭い痛みで、感覚の鋭さにも使う。"],
    ["idle","The machines stood idle during the repairs.","修理中、機械は動かずに置かれていた。","idle は使われず活動していないこと。人については怠けているという評価にもなる。"],
    ["crude","We made a crude map on a scrap of paper.","私たちは紙切れに大まかな地図を描いた。","crude は精密でなく粗いこと。crude oil は未精製の原油という組み合わせ。"],
    ["jealous","He was jealous of his sister's success.","彼は姉の成功をねたんでいた。","be jealous of ... は～をうらやみ嫉妬すること。of の後に人やその成功を置ける。"],
    ["pregnant","The story follows a pregnant woman on a long journey.","その物語は長旅をする妊娠中の女性を描いている。","pregnant は妊娠している状態の形容詞。妊娠という名詞は pregnancy。"],
    ["liable","The old pipes are liable to freeze in winter.","古いパイプは冬に凍結しやすい。","be liable to do は特によくないことが起きやすいこと。liable for ... は責任があるという別の形。"],
    ["stubborn","The stain was too stubborn to remove easily.","そのしみは頑固で簡単には落ちなかった。","stubborn は変えにくい・取り除きにくいこと。人に使えば意見を変えない頑固さを表す。"],
    ["decent","We found a decent place to stay near the station.","駅の近くにまずまずよい宿が見つかった。","decent は十分に満足できる程度によいこと。人については誠実で良識がある意味にもなる。"],
    ["marvelous","We had a marvelous view of the valley.","私たちは谷のすばらしい眺めを楽しんだ。","marvelous は非常にすばらしいという評価。イギリス式では marvellous と l を二つ書く。"],
    ["misleading","The headline was misleading about the survey results.","その見出しは調査結果について誤解を招くものだった。","misleading は誤った理解へ導くこと。必ずしも文章の全内容が虚偽という意味ではない。"],
    ["synthetic","The jacket is made of synthetic fibers.","その上着は合成繊維でできている。","synthetic は化学的に合成されたこと。natural『天然の』と対比して使える。"],
    ["classical","She enjoys listening to classical music.","彼女はクラシック音楽を聴くのが好きだ。","classical music はクラシック音楽。classic『代表的な傑作の』とは必ずしも同じ意味でない。"],
    ["Muslim","The exhibition introduces Muslim traditions from several regions.","その展示は数地域のイスラム教徒の伝統を紹介している。","Muslim はイスラム教徒、またはその人々に関する形容詞。英語では通常大文字で始める。"],
    ["anticipate","We anticipate a large number of visitors.","私たちは多くの来訪者を見込んでいる。","anticipate は先に予想すること。anticipate doing は使えるが、通常 anticipate to do とはしない。"],
    ["rub","She rubbed her hands together to warm them.","彼女は手を温めようとこすり合わせた。","rub は表面を押しながらこすること。rubbed と rubbing では b を重ねる。"],
    ["dispose","Please dispose of the waste in the correct container.","ごみは適切な容器に捨ててください。","dispose of ... は処分するという熟語。dispose the waste と of を落とさないようにする。"],
    ["refrain","Please refrain from taking photos during the performance.","公演中の写真撮影はお控えください。","refrain from doing は～するのを控えること。from の後は taking のような -ing 形。"],
    ["accumulate","Dust accumulated on the unused shelves.","使われていない棚にほこりがたまった。","accumulate は時間をかけて蓄積すること。accumulate knowledge なら知識を蓄える意味。"],
    ["boost","The good review boosted sales of the book.","好意的な書評で、その本の売上が伸びた。","boost は量や勢いを高めること。boost confidence は自信を高めるという組み合わせ。"],
    ["drag","He dragged the heavy bag across the floor.","彼は重いかばんを床の上で引きずった。","drag は接地したまま引くこと。dragged と dragging では g を重ねる。"],
    ["revise","I revised the introduction to make it clearer.","私はわかりやすくするために導入部分を修正した。","revise は見直して書き換えること。イギリス英語では試験勉強の復習にも使う。"],
    ["scratch","Be careful not to scratch the glass.","ガラスをひっかいて傷つけないようにしてください。","scratch は鋭いものでこする・傷をつけること。scratch your head は頭をかく動作。"],
    ["roar","The lion roared across the valley.","ライオンのほえる声が谷に響いた。","roar は低く大きな声でほえること。群衆やエンジンなどの大きな音にも使う。"],
    ["quote","The article quotes a local teacher.","その記事は地元の先生の言葉を引用している。","quote は発言をそのまま引くこと。quote from a book は本から引用するという形。"],
    ["bloom","The roses bloom in early summer.","バラは初夏に咲く。","bloom は花が咲くこと。in bloom は開花中という名詞の用法になる。"],
    ["insert","Insert the card into the slot.","カードを差込口に入れてください。","insert A into B は『AをBに差し込む』。文章の途中へ情報を挿入する場合にも使う。"],
    ["awaiting","We are awaiting a reply from the organizer.","私たちは主催者からの返事を待っている。","awaiting は await の -ing 形。await a reply と直接続け、wait for と違って for を入れない。"],
    ["dread","I dread having to speak before such a large audience.","こんな大勢の前で話さなければならないのが恐ろしい。","dread は先の出来事を強く不安に思うこと。動作なら having のような -ing 形を続けられる。"],
    ["conceal","The curtains concealed the damaged wall.","カーテンが傷んだ壁を隠していた。","conceal は見えない・知られないよう隠すこと。conceal A from B は『BからAを隠す』。"],
    ["enrich","Travel can enrich our understanding of other cultures.","旅行は異文化への理解を豊かにすることがある。","enrich は内容や価値を豊かにすること。金銭的に豊かにする場合にも使う。"],
    ["cling","The child clung to her father's hand.","その子は父親の手にしがみついた。","cling to ... は離さずつかまること。考えに固執する意味もあり、活用は cling–clung–clung。"],
    ["surpass","The result surpassed all our expectations.","結果は私たちの予想をすべて上回った。","surpass は水準や成果で上回ること。比較する対象を直接目的語に取る。"],
    ["suppress","She tried to suppress a laugh during the speech.","彼女は演説中に笑いをこらえようとした。","suppress は感情や反応を外に出さず抑えること。情報の公表を抑える意味にもなる。"],
    ["portray","The film portrays life in a small fishing village.","その映画は小さな漁村の暮らしを描いている。","portray は作品などで表現すること。portray A as B は『AをBとして描く』。"],
    ["soaring","Soaring prices made the materials harder to afford.","急騰する価格のため、材料を買うのが難しくなった。","soaring は soar の -ing 形で価格の急上昇を表す。鳥が高く舞い上がる意味もある。"],
    ["drain","Drain the water from the pot.","鍋から水を切ってください。","drain A from B は液体AをBから排出すること。drain one's energy は気力を消耗させる比喩。"],
    ["glow","The lamp glowed softly in the corner.","ランプは部屋の隅で柔らかく光っていた。","glow は強く点滅せず持続して光ること。a warm glow は温かな光という名詞の用法。"],
    ["migrate","These birds migrate south in winter.","これらの鳥は冬に南へ渡る。","migrate は動物や人が別の地域へ移動すること。季節的な渡りにも使い、名詞は migration。"],
    ["exclaim","She exclaimed that the view was beautiful.","彼女は景色が美しいと声を上げた。","exclaim は驚きや感動で急に大きな声を出すこと。内容は that 節でも示せる。"],
    ["exert","The rope exerted pressure on the branch.","ロープが枝に圧力をかけていた。","exert A on B は『BにAを及ぼす』。力・圧力・影響などがAになる。"],
    ["disguise","He disguised his disappointment with a smile.","彼は笑顔で落胆を隠した。","disguise は本当の姿や気持ちをわからなくすること。disguise oneself as ... は～に変装すること。"],
    ["accelerate","The train accelerated as it left the station.","列車は駅を離れるにつれて加速した。","accelerate は速度や進行を速めること。accelerate a process は過程を加速する意味。"],
    ["dwell","The story describes people who dwell in mountain caves.","その物語は山の洞窟に住む人々を描いている。","dwell は住むという文章的な語。dwell on a problem は問題を長く考え続ける意味になる。"],
    ["integrate","The teacher integrated music into the language lesson.","先生は語学の授業に音楽を取り入れた。","integrate A into B は『AをBに組み込んで一体化する』。単に置くだけでなく関連づける感覚。"],
    ["weep","She wept with relief when the search ended.","捜索が終わると、彼女は安堵の涙を流した。","weep は涙を流して泣くこと。活用は weep–wept–wept で、cry より文章的な響き。"],
    ["reassure","The teacher reassured us that there was enough time.","先生は十分時間があると言って私たちを安心させた。","reassure someone that ... は不安を和らげる形。相手がすでに心配している場面に合う。"],
    ["crawl","The baby crawled across the rug.","赤ちゃんは敷物の上をはって進んだ。","crawl は手足を使って低く進むこと。車がのろのろ進む場合にも比喩的に使う。"],
    ["restrain","She restrained herself from interrupting.","彼女は口を挟むのをこらえた。","restrain A from doing は『Aが～するのを抑える』。oneself を使えば自分を抑える意味。"],
    ["resent","I resent being blamed for someone else's mistake.","私は他人の間違いで責められるのに腹が立つ。","resent は不公平などに憤りを感じること。動作を続けるなら being のような -ing 形。"],
    ["yell","He yelled for help from the other side of the river.","彼は川の向こうから助けを求めて叫んだ。","yell for help は救助を求めて大声を出すこと。yell at someone は人に怒鳴る意味になる。"],
    ["assess","The team assessed the damage to the bridge.","そのチームは橋の損傷を評価した。","assess は調べて程度や価値を判断すること。被害・危険・能力などが目的語になる。"],
    ["carve","She carved a bird from a piece of wood.","彼女は木片から鳥を彫った。","carve A from B は素材Bを削ってAを作ること。carve a name into wood は名前を刻むこと。"],
    ["halt","The driver brought the bus to a halt.","運転手はバスを停止させた。","bring A to a halt は『Aを止める』。halt は動詞としても停止する・させる意味で使える。"],
    ["inspect","The engineer inspected the bridge after the storm.","技師は嵐の後に橋を点検した。","inspect は状態や問題を確かめるため詳しく見ること。名詞 inspection は点検・検査。"],
    ["tackle","We need to tackle the hardest problem first.","最も難しい問題に先に取り組む必要がある。","tackle は困難に正面から取り組むこと。対象を直接続け、通常 tackle with とはしない。"],
    ["omit","You may omit the final paragraph.","最後の段落は省いて構いません。","omit は省略する・抜かすこと。omitted と omitting では t を重ねる。"],
    ["chew","The child chewed the bread slowly.","その子はパンをゆっくりかんだ。","chew は食べ物を歯で繰り返しかむこと。bite はかみつく一回の動作にも使う。"],
    ["resume","We resumed the meeting after a short break.","短い休憩の後、会議を再開した。","resume は中断したことを再び始めること。resume working のように -ing 形も続けられる。"],
    ["mold","The artist molded the clay into a bowl.","芸術家は粘土を鉢の形に成形した。","mold A into B は『AをBの形にする』。イギリス式では mould とつづる。"],
    ["accommodate","The hall can accommodate two hundred people.","そのホールは二百人を収容できる。","accommodate は場所や必要を満たして受け入れること。c と m をそれぞれ二つ書く。"],
    ["erase","Please erase the old date from the board.","黒板の古い日付を消してください。","erase A from B は『BからAを消す』。文字や記録、データなどに使う。"],
    ["inferred","We inferred from the footprints that someone had been there.","足跡から、誰かがそこにいたと推測した。","inferred は infer の過去形・過去分詞。infer A from B は『BからAを推測する』。"],
    ["revive","The rain revived the wilted plants.","雨でしおれた植物が元気を取り戻した。","revive は元気や活動を取り戻す・取り戻させること。古い習慣の復活にも使う。"],
    ["contemplate","She contemplated moving to a smaller town.","彼女はもっと小さな町への引っ越しをじっくり考えた。","contemplate は時間をかけて考えること。動作には moving のような -ing 形を続ける。"],
    ["rotate","Rotate the handle clockwise.","取っ手を時計回りに回してください。","rotate は軸を中心に回転する・させること。clockwise は時計回り、counterclockwise は反時計回り。"],
    ["disrupt","The power cut disrupted the presentation.","停電で発表が中断された。","disrupt は正常な進行を乱すこと。完全に終わらせるとは限らず、支障を生む場合にも使う。"],
    ["navigate","We used a map to navigate the narrow streets.","私たちは地図を使って狭い通りを進んだ。","navigate は進路を判断して進むこと。船だけでなく道路やウェブサイトの移動にも使う。"],
    ["ache","My legs ached after the hike.","ハイキングの後、脚が痛んだ。","ache は持続する鈍い痛みを表す。a headache のように体の部位と一語になる名詞もある。"],
    ["discard","Discard any damaged pieces before assembly.","組み立てる前に傷んだ部品を取り除いてください。","discard は不要・不適切なものを捨てること。discard an idea なら案を採用せず捨てる意味。"],
    ["incorporate","The new plan incorporates suggestions from residents.","新しい計画には住民の提案が取り入れられている。","incorporate A into B は『AをBの一部に組み込む』。全体との統合を表す。"],
    ["overtake","The cyclist overtook me on the hill.","自転車に乗った人が坂で私を追い越した。","overtake は後ろから追いつき先に出ること。活用は overtake–overtook–overtaken。"],
    ["supplement","The teacher supplemented the textbook with photographs.","先生は写真で教科書の内容を補った。","supplement A with B は『Bを追加してAを補う』。元のものを取り替えるのではない。"],
    ["manipulate","The technician manipulated the controls carefully.","技術者は慎重に操作装置を扱った。","manipulate は巧みに操作すること。人や情報を意図的に操る否定的な意味もある。"],
    ["nourish","The roots absorb water to nourish the plant.","根は植物を養うために水を吸収する。","nourish は成長に必要なものを与えること。想像力などを育む比喩にも使う。"],
    ["squeeze","Squeeze the lemon over the salad.","サラダの上でレモンを搾ってください。","squeeze は強く押して絞ること。squeeze into a space は狭い場所に押し入ること。"],
    ["depict","The painting depicts a busy harbor.","その絵はにぎやかな港を描いている。","depict は絵や言葉で表すこと。depict A as B は『AをBとして描く』。"],
    ["distract","The noise distracted me from my reading.","騒音で読書への集中が途切れた。","distract A from B は『Aの注意をBからそらす』。対象と注意を向けていたものを区別する。"],
    ["disclose","The company disclosed the results of the investigation.","会社は調査結果を公表した。","disclose は知られていなかった情報を明らかにすること。必ずしも不正の暴露とは限らない。"],
    ["enroll","She enrolled in an evening language course.","彼女は夜間の語学講座に申し込んだ。","enroll in ... は講座などに登録すること。イギリス式では原形を enrol ともつづる。"],
    ["nurture","The program nurtures young artists.","そのプログラムは若い芸術家を育成する。","nurture は必要な支援を与えて成長を助けること。才能や関係を育てる場合にも使う。"],
    ["speculate","We can only speculate about why the city was abandoned.","その都市が放棄された理由は推測するしかない。","speculate about ... は確かな証拠なしに考えを巡らせること。事実として断定する語ではない。"],
    ["prolong","The repairs prolonged our stay by two days.","修理のため、私たちの滞在は二日延びた。","prolong は時間的に長くすること。延びた長さには by を使える。"],
    ["execute","The history describes prisoners who were executed after the revolt.","その歴史書は反乱後に処刑された囚人たちを記している。","execute は文脈により処刑する・実行する。execute a plan では計画を実行する意味になる。"],
    ["uncover","The investigation uncovered several errors.","調査でいくつかの誤りが明らかになった。","uncover は覆いを取ることから、隠れていた事実を発見する意味にもなる。"],
    ["tremble","Her hands trembled with excitement.","彼女の手は興奮で震えた。","tremble with ... は原因となる感情などで震えること。寒さや恐怖にも使える。"],
    ["seize","She seized the opportunity to ask a question.","彼女は機会を捉えて質問した。","seize は急につかむこと。seize an opportunity は好機を逃さず利用する比喩。"],
    ["abolish","The council voted to abolish the outdated rule.","議会は時代遅れの規則の廃止を可決した。","abolish は制度や規則を正式になくすこと。一時的に止める suspend とは異なる。"],
    ["scold","He scolded the children for leaving the gate open.","彼は門を開けたままにした子どもたちを叱った。","scold 人 for 行為で叱る理由を示す。行為は leaving のような -ing 形を使う。"],
    ["attain","She attained her goal after years of practice.","彼女は何年もの練習を経て目標を達成した。","attain は努力して目標や水準に達すること。attain a level と直接目的語を取る。"],
    ["utter","He did not utter a word during the meeting.","彼は会議中、一言も発しなかった。","動詞 utter は声や言葉を発すること。形容詞 utter は完全なという強調になる。"],
    ["flee","The birds fled when the dog approached.","犬が近づくと鳥たちは逃げた。","flee は危険から逃げること。活用は flee–fled–fled で、flee from ... と場所を示せる。"],
    ["offending","She apologized for offending her colleague.","彼女は同僚を不快にさせたことを謝った。","offending は offend の -ing 形。offend someone は人の感情を害することを表す。"],
    ["confess","He confessed to breaking the window.","彼は窓を割ったことを認めた。","confess to doing はしたことを告白する形。to は前置詞なので breaking を続ける。"],
    ["postpone","We postponed the picnic until Sunday.","私たちはピクニックを日曜日まで延期した。","postpone A until B は『AをBまで延期する』。中止する cancel と区別する。"],
    ["drift","Clouds drifted slowly across the sky.","雲が空をゆっくり流れていった。","drift は風や流れに任せて漂うこと。意図的に進む動きとは限らない。"],
    ["weave","She wove a basket from thin branches.","彼女は細い枝でかごを編んだ。","weave は材料を交差させて織る・編むこと。活用は weave–wove–woven。"],
    ["install","They installed a new light above the entrance.","彼らは入り口の上に新しい照明を設置した。","install は使える状態に取り付けること。ソフトウェアの導入にも同じ動詞を使う。"],
    ["twist","Twist the lid gently to open the jar.","ふたをそっとひねって瓶を開けてください。","twist はねじる動作。twist someone's words は人の言葉の意味をねじ曲げる比喩。"],
    ["extract","The researchers extracted data from old records.","研究者たちは古い記録からデータを取り出した。","extract A from B は『BからAを抽出する』。物質・情報・引用文などに使う。"],
    ["bump","I bumped into the table in the dark.","暗闇で机にぶつかった。","bump into ... は偶然ぶつかること。人が相手ならばったり会うという意味にもなる。"],
    ["despise","She despises people who cheat others.","彼女は他人をだます人を軽蔑している。","despise は価値が低いとして強く見下すこと。単に好きでない dislike より強い語。"],
    ["tolerate","These plants tolerate dry conditions well.","これらの植物は乾燥によく耐える。","tolerate は不快・困難なものに耐えること。容認する意味でも使い、賛成とは限らない。"],
    ["boast","He boasted about his perfect score.","彼は満点を取ったことを自慢した。","boast about ... は自慢話をすること。自信を述べるだけでなく、誇示する響きがある。"],
    ["flourishing","The town has a flourishing market for local crafts.","その町では地元の工芸品市場が活況を呈している。","flourishing は flourish の -ing 形で、順調に栄えている状態を修飾する。"],
    ["disregard","He disregarded the warning and continued walking.","彼は警告を無視して歩き続けた。","disregard は注意を向けず取り合わないこと。目的語を直接続ける。"],
    ["tease","Please do not tease him about his mistake.","彼の失敗をからかわないでください。","tease 人 about 事柄でからかう内容を示す。冗談のつもりでも相手を傷つける文脈に使う。"],
    ["reinforce","The builders reinforced the wall with steel.","建設作業員は鋼材で壁を補強した。","reinforce A with B は『BでAを強める』。考えや学習内容を強化する場合にも使う。"],
    ["strive","We strive to make every lesson clear.","私たちはすべての授業をわかりやすくしようと努めている。","strive to do は懸命に努力すること。strive for a goal は目標を目指して努力する形。"],
    ["coordinate","She coordinated the work of three teams.","彼女は三チームの作業を調整した。","coordinate は複数の活動がうまく合うようにすること。cooperate『協力する』と役割が違う。"],
    ["yawn","I yawned several times during the late train ride.","遅い時間の電車で何度かあくびをした。","yawn はあくびをすること。名詞なら let out a yawn と表せる。"],
    ["hug","She hugged her brother when he arrived.","弟が到着すると、彼女は弟を抱きしめた。","hug は腕で抱きしめること。hugged と hugging では g を重ねる。"],
    ["combat","The program aims to combat food waste.","そのプログラムは食品廃棄を減らすことに取り組んでいる。","combat は問題などと戦うこと。combat a problem と直接続け、通常 against は不要。"],
    ["knit","My aunt knitted a scarf for me.","おばは私にマフラーを編んでくれた。","knit は糸の輪をつなげて編むこと。語頭の k は発音せず、過去形は knitted または knit。"],
    ["fatigue","After hours of driving, he felt fatigue.","何時間も運転した後、彼は疲労を感じた。","fatigue は疲労というやや改まった名詞。通常数えず、形容詞 fatigued は疲れた状態。"],
    ["fame","The writer gained fame after her first novel.","その作家は最初の小説で名声を得た。","fame は広く知られる名声。形容詞 famous は有名なという意味。"],
    ["mess","The kitchen was a mess after we baked the cake.","ケーキを焼いた後、台所は散らかっていた。","a mess は乱雑な状態。make a mess は散らかすことで、通常 a をつける。"],
    ["dignity","The staff treated every visitor with dignity.","職員はすべての来訪者の尊厳を大切に扱った。","dignity は人としての尊厳や落ち着いた品位。with dignity は尊厳を保ってという表現にもなる。"],
    ["canal","Boats carry goods along the canal.","船が運河に沿って荷物を運ぶ。","canal は人が造った水路。自然の river と区別する。"],
    ["drought","The long drought damaged the crops.","長い干ばつが作物に被害を与えた。","drought は雨が長く降らない状態。発音は『ドラウト』に近く、最後は t の音。"],
    ["despair","She refused to give in to despair.","彼女は絶望に屈することを拒んだ。","despair は希望を失うこと。in despair は絶望してという形で使う。"],
    ["interval","The bells ring at regular intervals.","鐘は一定の間隔で鳴る。","at regular intervals は定期的な間隔でという熟語。時間にも距離にも使える。"],
    ["luggage","We left our luggage at the hotel.","私たちは荷物をホテルに預けた。","luggage は旅行の荷物をまとめて指し、通常数えない。一個なら a piece of luggage。"],
    ["behalf","I thanked the volunteers on behalf of the school.","私は学校を代表してボランティアにお礼を述べた。","on behalf of ... は『～を代表して・～のために』。behalf 単独より熟語の形で覚える。"],
    ["impulse","I bought the notebook on impulse.","私は衝動的にそのノートを買った。","on impulse は前もって考えず衝動でという意味。an impulse to do は急に～したい気持ち。"],
    ["debris","Workers cleared debris from the road.","作業員は道路からがれきを取り除いた。","debris は破片や残骸をまとめて指す通常数えない名詞。語末の s は発音しない。"],
    ["beast","The tale describes a strange beast in the forest.","その物語は森の奇妙な野獣を描いている。","beast は動物を荒々しく、または物語的に表す語。日常の動物全般には animal が中立的。"],
    ["superstition","The book explores superstitions about numbers.","その本は数字にまつわる迷信を考察している。","superstition は根拠なく運などに結びつける信念。個々の迷信は数えられる。"],
    ["illusion","The mirrors create an illusion of greater space.","鏡によって部屋が広く見える錯覚が生まれる。","an illusion of ... は実際と違う印象・錯覚。手品だけでなく思い込みにも使う。"],
    ["thread","She passed the thread through the needle.","彼女は針に糸を通した。","thread は糸。議論の流れやオンラインの一連の投稿という意味にもなる。"],
    ["intake","The diary records her daily food intake.","その日誌は彼女の毎日の食物摂取量を記録している。","intake は体や装置に取り込む量。daily intake は一日あたりの摂取量。"],
    ["feast","The villagers prepared a feast for the celebration.","村人たちは祝いのためにごちそうを用意した。","feast は盛大な食事・宴。a feast for the eyes は目を楽しませるものという比喩。"],
    ["transition","The transition from school to work can be challenging.","学校から仕事への移行は難しいことがある。","the transition from A to B はAからBへの移り変わり。両端を from と to で示す。"],
    ["misery","The cold and rain added to their misery.","寒さと雨が彼らの苦しみを増した。","misery は強い苦痛・悲惨な状態。形容詞 miserable はみじめなという意味。"],
    ["radiation","The instrument measures radiation from the sun.","その装置は太陽からの放射を測定する。","radiation はエネルギーの放射。放射線だけでなく熱や光などにも使われる語。"],
    ["log","They used a log as a seat.","彼らは丸太を椅子代わりにした。","log は丸太。活動の記録も a log と呼び、動詞では記録するという意味になる。"],
    ["consensus","The group reached a consensus on the final design.","集団は最終設計について合意に達した。","reach a consensus は広い合意を得ること。完全な全員一致だけを意味するとは限らない。"],
    ["deed","The story praises courage shown through deeds.","その物語は行動で示された勇気をたたえている。","deed は実際にした行為。words and deeds は言葉と行動という対比になる。"],
    ["proverb","The teacher asked us to explain a proverb in our own words.","先生はことわざを自分の言葉で説明するよう求めた。","proverb は経験や教訓を短く表すことわざ。quote は特定の人などの引用で、必ずしもことわざではない。"],
    ["compliment","She gave me a compliment on my presentation.","彼女は私の発表をほめてくれた。","a compliment on ... は～についてのほめ言葉。complement『補うもの』とはつづりが違う。"],
    ["flame","A small flame flickered inside the lantern.","ランタンの中で小さな炎が揺れた。","flame は燃えて見える炎。in flames は炎に包まれている状態を表す。"],
    ["anniversary","The school celebrated its fiftieth anniversary.","学校は創立五十周年を祝った。","anniversary は出来事から一年ごとの記念日。何周年かは fiftieth のような序数を使う。"],
    ["conscience","My conscience told me to return the money.","良心に従い、そのお金を返すべきだと思った。","conscience は善悪を判断する良心。conscious『意識している』と形を取り違えないようにする。"],
    ["expedition","The expedition collected samples from the glacier.","探検隊は氷河から試料を集めた。","expedition は目的をもつ探検旅行やその一行。気軽な旅行 trip より組織的な響き。"],
    ["offspring","The birds feed their offspring with insects.","その鳥たちは子に昆虫を与える。","offspring は子や子孫。単数・複数が同じ形で、offsprings とは通常しない。"],
    ["allowance","She saves part of her weekly allowance.","彼女は毎週の小遣いの一部を貯金している。","allowance は定期的に与えられる金額。手当や小遣いを指し、用途で訳を選ぶ。"],
    ["headline","The headline drew my attention to the article.","見出しでその記事に目が留まった。","headline は記事の大見出し。make headlines はニュースで大きく取り上げられること。"],
    ["treaty","The two countries signed a peace treaty.","二つの国は平和条約に署名した。","treaty は国などの正式な条約。sign a treaty は条約に署名するという組み合わせ。"],
    ["monument","The monument honors the people who built the town.","その記念碑は町を築いた人々をたたえている。","a monument to ... は～を記念する建造物。歴史的に重要な建物にも使う。"],
    ["worm","The bird pulled a worm from the soil.","鳥は土からミミズを引き出した。","worm は細長く柔らかい体の虫。insect『昆虫』全般と同じ意味ではない。"],
    ["remedy","The committee proposed a remedy for the shortage.","委員会は不足への解決策を提案した。","a remedy for ... は問題への対策。病気に対する治療法・薬という意味もある。"],
    ["encyclopedia","I looked up the island in an encyclopedia.","私は百科事典でその島を調べた。","encyclopedia は幅広い事柄を説明する事典。単語の意味が中心の dictionary と区別する。"],
    ["glimpse","We caught a glimpse of the sea between the buildings.","建物の間から海がちらりと見えた。","catch a glimpse of ... は一瞬見ること。ゆっくり観察する意味ではない。"],
    ["personnel","Only authorized personnel may enter this room.","許可された職員だけがこの部屋に入れる。","personnel は職員全体を表す集合的な語。personal『個人の』とつづりやアクセントが異なる。"],
    ["triumph","Finishing the project was a personal triumph.","その計画をやり遂げたことは個人的な大きな勝利だった。","triumph は大きな成功・勝利。競争相手に勝つ場面以外にも使える。"],
    ["arithmetic","The children practice arithmetic with small blocks.","子どもたちは小さな積み木で算数を練習する。","arithmetic は基本的な数の計算を扱う算数。mathematics はより広い数学全体を指す。"],
    ["self-esteem","Encouragement can help build a child's self-esteem.","励ましは子どもの自尊心を育てる助けになる。","self-esteem は自分に価値があると感じること。自信 confidence と重なるが同じ範囲とは限らない。"],
    ["microbe","The students observed microbes under a microscope.","生徒たちは顕微鏡で微生物を観察した。","microbe は肉眼では見えにくい微生物。すべてが病気の原因になるという意味ではない。"],
    ["odds","What are the odds of finding a seat at this hour?","この時間に席が見つかる可能性はどのくらいだろう。","the odds of doing は～する見込み。odds は通常複数形扱いで are と組み合わせる。"],
    ["chaos","The sudden closure threw the station into chaos.","突然の閉鎖で駅は大混乱に陥った。","chaos は秩序のない混乱。通常数えない名詞で、英語の発音は『ケイオス』に近い。"],
    ["destiny","The hero believes it is his destiny to protect the village.","主人公は村を守るのが自分の運命だと信じている。","destiny は将来たどる運命。物語や強い信念を述べる場面によく合う。"],
    ["diameter","The circle has a diameter of ten centimeters.","その円の直径は十センチメートルだ。","diameter は中心を通って円の両端を結ぶ直径。radius『半径』の二倍にあたる。"],
    ["lottery","The tickets were allocated by lottery.","チケットは抽選で割り当てられた。","lottery は宝くじや無作為の抽選。by lottery は抽選によってという表現。"],
    ["souvenir","I bought a small bowl as a souvenir of the trip.","私は旅の記念に小さな器を買った。","a souvenir of ... は出来事や場所を思い出す記念品。食べ物以外のお土産にも使う。"],
    ["trail","We followed a narrow trail through the woods.","私たちは森の中の細い小道をたどった。","trail は歩いてできた道や山道。a trail of footprints は一続きの足跡になる。"],
    ["ratio","The ratio of water to juice is three to one.","水とジュースの比率は三対一だ。","the ratio of A to B はA対Bの比。例文では水が三、ジュースが一になる。"],
    ["sword","The museum displays a decorated sword.","その博物館は装飾された剣を展示している。","sword は剣。つづりに w があるが、通常その音は発音しない。"],
    ["whistle","The referee blew the whistle.","審判が笛を吹いた。","blow a whistle は笛を吹くこと。動詞 whistle は口笛を吹く意味にもなる。"],
    ["sentiment","The speech reflected public sentiment.","その演説は世間の感情を反映していた。","sentiment はある事柄についての感情や意見。public sentiment は世論の感情面を表す。"],
    ["chore","Washing the dishes is my evening chore.","皿洗いは私の夜の家事だ。","chore は定期的に行う家事や雑用。household chores で家事全般をまとめられる。"],
    ["courtesy","He treated the visitors with courtesy.","彼は来訪者に礼儀正しく接した。","courtesy は礼儀正しさ。out of courtesy は礼儀としてという動機を表す。"],
    ["mayor","The mayor opened the new public library.","市長が新しい公共図書館の開館を宣言した。","mayor は市や町の首長。major『主要な』とつづり・発音を混同しないようにする。"],
    ["surveillance","The building is under video surveillance.","その建物は映像で監視されている。","under surveillance は監視下にある状態。通常数えない名詞で、注意して見守る活動を指す。"],
    ["trash","Please put the trash in the bin.","ごみをごみ箱に入れてください。","trash は主にアメリカ英語で、ごみをまとめて指す。通常数えず、a bag of trash と量を表す。"],
    ["prestige","The award brought prestige to the small theater.","その賞は小さな劇場に名声をもたらした。","prestige は高い評価からくる名声・威信。単に知られている fame より尊敬の要素が強い。"],
    ["headquarters","The company moved its headquarters to a new building.","会社は本社を新しい建物へ移した。","headquarters は一つの本部でも語尾に s がある。headquarter と単数形にしない。"],
    ["wilderness","They spent a week exploring the wilderness.","彼らは一週間、未開の自然地帯を探検した。","wilderness は人の手があまり入らない広い自然。単に木のない土地だけを意味しない。"],
    ["orbit","The satellite remains in orbit around the Earth.","衛星は地球周回軌道にとどまっている。","in orbit は軌道上にあること。動詞 orbit the Earth は地球を周回する意味。"],
    ["bias","The report shows a bias toward large companies.","その報告書には大企業寄りの偏りが見られる。","bias toward ... は～に有利な偏り。bias against ... は～に不利な偏見を表す。"],
    ["republic","The country became a republic after the revolution.","その国は革命後に共和国となった。","republic は君主を元首としない国家形態。民主的かどうかとは別の観点の語。"],
    ["bargain","This used desk was a real bargain.","この中古の机は本当にお買い得だった。","a bargain は値段に比べて価値が高い買い物。動詞なら値段などを交渉すること。"],
    ["domain","The issue falls within the domain of public health.","その問題は公衆衛生の領域に属する。","domain は活動や知識の領域。インターネットでは住所の一部であるドメイン名にも使う。"],
    ["fragment","Only a fragment of the original letter remains.","元の手紙は一部分だけが残っている。","a fragment of ... は壊れた全体などの一片。完全な形でない部分を示す。"],
    ["galaxy","Our solar system is part of the Milky Way galaxy.","太陽系は天の川銀河の一部だ。","galaxy は多くの恒星などが集まる銀河。星雲を表す nebula とは区別する。"],
    ["lap","The cat slept on her lap.","猫は彼女の膝の上で眠っていた。","lap は座ったときの太ももの上の部分。膝の関節そのものは knee と呼ぶ。"],
    ["deadline","The deadline for applications is Friday.","応募の締め切りは金曜日だ。","a deadline for ... は提出などの期限。meet a deadline は締め切りに間に合わせること。"],
    ["bullet","The museum displays a bullet found near the battlefield.","博物館は戦場近くで見つかった弾丸を展示している。","bullet は銃から発射される弾丸。文章の bullet point は箇条書きの項目を指す。"],
    ["pedestrian","The bridge is open only to pedestrians.","その橋は歩行者専用だ。","pedestrian は歩いて移動する人。pedestrian crossing は横断歩道という組み合わせ。"],
    ["wit","Her speech was full of wit.","彼女の演説は機知に富んでいた。","wit は機転の利いたおもしろさ。a witty remark は気の利いた発言。"],
    ["nuisance","The constant noise became a nuisance.","絶え間ない騒音が迷惑になった。","a nuisance は不便や不快を引き起こすもの。人にも状況にも使う。"],
    ["criteria","The judges used three criteria to evaluate the designs.","審査員は三つの基準で設計を評価した。","criteria は criterion の複数形。一つの基準なら a criterion とする。"],
    ["hardship","The family endured great hardship during the winter.","その家族は冬の間、大きな苦難に耐えた。","hardship は生活上の厳しい困難。複数形 hardships なら個々の苦難を表す。"],
    ["glory","The team shared the glory of its first victory.","チームは初勝利の栄光を分かち合った。","glory は輝かしい功績への栄誉。in all its glory は最も見事な姿でという表現。"],
    ["pavement","Please keep your bicycle off the pavement.","自転車を歩道に乗り入れないでください。","pavement はイギリス英語では歩道。アメリカ英語では舗装面を指し、歩道は sidewalk が一般的。"],
    ["navy","He joined the navy after finishing school.","彼は学校を卒業して海軍に入った。","navy は海の軍隊。army は陸軍、air force は空軍で、navy blue は濃紺。"],
    ["script","The actors read the script together.","俳優たちは一緒に台本を読んだ。","script は演劇や映像の台本。文字体系や短いプログラムという意味もある。"],
    ["pension","She receives a pension every month.","彼女は毎月年金を受け取っている。","pension は退職後などに定期的に受け取る年金。日本語の宿泊施設のペンションとは区別する。"],
    ["province","The festival attracts visitors from across the province.","祭りには州内各地から来訪者が集まる。","province は国の行政区分で、州・県などと訳す。国によって区分の仕組みは異なる。"],
    ["surplus","The farm sells its surplus vegetables at the market.","農場は余った野菜を市場で売る。","surplus は必要量を超えた余り。a surplus of food は食料の余剰を表す。"],
    ["moisture","The lid helps keep moisture in the soil.","ふたは土の水分を保つのに役立つ。","moisture は物や空気に含まれる水分。通常数えない名詞で、形容詞 moist は湿った。"],
    ["patch","She sewed a patch over the hole in her jeans.","彼女はジーンズの穴に当て布を縫いつけた。","patch は補修の小片。a patch of grass は小さな草地で、限定された一部分にも使う。"],
    ["altitude","The aircraft flew at a high altitude.","航空機は高い高度を飛んだ。","altitude は海面などを基準にした高さ。at an altitude of ... で具体的な高度を示す。"],
    ["thermometer","The thermometer showed twenty degrees.","温度計は二十度を示していた。","thermometer は温度を測る道具。体温計にも気温計にも使える。"],
    ["tuition","The scholarship covers her tuition fees.","奨学金は彼女の授業料を賄っている。","tuition fees は授業料。アメリカ英語では tuition 単独でも学費を表す。"],
    ["troop","A troop of soldiers crossed the bridge.","兵士の一団が橋を渡った。","a troop は一団・部隊。troops は兵士たちや軍隊をまとめて指すことが多い。"],
    ["primate","The study compares the behavior of several primates.","その研究は数種の霊長類の行動を比較している。","primate は霊長類の動物。類人猿だけでなくサルや人間も含む分類。"],
    ["flaw","The test revealed a flaw in the design.","試験で設計の欠陥が明らかになった。","a flaw in ... は内部にある欠点。計画や議論の弱点にも使う。"],
    ["nephew","My nephew starts school this spring.","私の甥はこの春、学校に入る。","nephew は兄弟姉妹などの息子。娘にあたる姪は niece と呼ぶ。"],
    ["garment","Each garment is checked before shipping.","各衣服は出荷前に検査される。","garment は衣服一点を数える改まった語。clothes は衣類をまとめて指す複数形。"],
    ["diagnosis","The report explains how the diagnosis was made.","その報告書は診断がどう行われたかを説明している。","diagnosis は原因や病名を判断する診断。複数形は diagnoses、動詞は diagnose。"],
    ["commerce","The port became a center of commerce.","港は商業の中心地になった。","commerce は商品やサービスの売買活動全体。通常数えない名詞で、commercial は商業の。"],
    ["antiquity","The museum displays tools from antiquity.","博物館は古代の道具を展示している。","antiquity は古代。複数形 antiquities は古代の遺物を表す。"],
    ["fraction","Only a fraction of the seats were occupied.","席はほんの一部しか埋まっていなかった。","a fraction of ... はごく一部。数学では三分の一などの分数も fraction。"],
    ["irony","The irony is that the time-saving device wasted our time.","皮肉なことに、時間節約用の装置が時間を浪費させた。","irony は予想や意図と現実が食い違うおかしさ。相手への嫌味だけを指す語ではない。"],
    ["nightmare","I had a nightmare about missing the train.","私は電車に乗り遅れる悪夢を見た。","have a nightmare は悪夢を見ること。非常に困難な状況を比喩的に a nightmare とも呼ぶ。"],
    ["defect","The inspection found a defect in the cable.","検査でケーブルの欠陥が見つかった。","a defect in ... は機能などの不具合。名詞は前半、動詞 defect は後半を強く読む。"],
    ["certificate","She received a certificate after completing the course.","彼女は講座修了後に証明書を受け取った。","certificate は事実や資格を示す文書。a birth certificate は出生証明書。"],
    ["decay","The old wood showed signs of decay.","古い木材には腐朽の兆候があった。","decay は徐々に腐る・衰えること。名詞でも動詞でも使える。"],
    ["erosion","Tree roots help prevent soil erosion.","木の根は土壌の浸食を防ぐ助けになる。","erosion は水や風などによって削られること。動詞は erode。"],
    ["recipe","Clear goals and regular practice are a recipe for progress.","明確な目標と定期的な練習は上達の秘訣だ。","a recipe for ... はある結果につながる方法という比喩。元の意味は料理の作り方。"],
    ["skeleton","The model shows the human skeleton.","その模型は人間の骨格を示している。","skeleton は体を支える骨組み。建物や計画の基本構造にも比喩的に使う。"],
    ["grace","The dancer moved with grace.","踊り手は優雅に動いた。","with grace は優雅に・品よくという表現。通常数えない性質として使う。"],
    ["landmark","The clock tower is the town's best-known landmark.","時計塔は町で最もよく知られた目印だ。","landmark は場所を識別する目立つ建造物。a landmark decision は画期的な決定になる。"],
    ["dementia","The center supports people living with dementia.","その施設は認知症のある人々を支援している。","dementia は認知症を表す通常数えない名詞。診断名などの用語として使われる。"],
    ["flesh","The fruit has soft, orange flesh.","その果物には柔らかなオレンジ色の果肉がある。","flesh は体の肉や果肉。食用の肉を一般に指す meat と区別する。"],
    ["collision","The driver stopped to avoid a collision.","運転手は衝突を避けるために止まった。","a collision between A and B はAとBの衝突。意見などの対立にも使う。"],
    ["hazard","Loose cables are a hazard in a busy hallway.","人通りの多い廊下では、たるんだケーブルは危険のもとだ。","hazard は害を生じうるもの。危険の可能性を表す risk と焦点が異なる。"],
    ["tomb","The archaeologists examined the ancient tomb.","考古学者たちは古代の墓を調べた。","tomb は遺体を納める墓や墓室。語末の b は発音しない。"],
    ["injection","The nurse prepared the equipment for the injection.","看護師は注射の器具を用意した。","injection は液体を注入すること、特に注射。動詞は inject。"],
    ["breakthrough","The discovery was a breakthrough in battery research.","その発見は電池研究の画期的な進歩だった。","a breakthrough in ... は行き詰まりを超える大きな進展。通常の小さな改善より強い語。"],
    ["leather","The bag is made of soft leather.","そのかばんは柔らかな革でできている。","leather は加工した動物の皮。素材としては通常数えない名詞。"],
    ["jewelry","The shop sells handmade jewelry.","その店は手作りの宝飾品を売っている。","jewelry は装身具をまとめた通常数えない語。一つなら a piece of jewelry と表す。"],
    ["cue","The light was our cue to enter the stage.","その照明が舞台へ出る合図だった。","a cue to do は行動を始める合図。発音は queue『列』と同じ。"],
    ["ambulance","An ambulance arrived outside the station.","駅の外に救急車が到着した。","ambulance は救急搬送の車両。母音の音で始まるため an ambulance とする。"],
    ["estate","They inherited a small estate in the countryside.","彼らは田園地帯の小さな土地・屋敷を相続した。","estate は土地や建物を含む財産。real estate は不動産を表す。"],
    ["commodity","Coffee is an important export commodity.","コーヒーは重要な輸出商品だ。","commodity は市場で取引する商品、特に原料など。個別の製品全般 product と焦点が異なる。"],
    ["departure","Our departure was delayed by an hour.","私たちの出発は一時間遅れた。","departure は出発。departure from a plan は計画からの逸脱という意味にもなる。"],
    ["phase","The project is entering its final phase.","その事業は最終段階に入ろうとしている。","phase は過程の一段階。phase out は段階的に廃止するという動詞表現。"],
    ["thief","The thief escaped before the police arrived.","泥棒は警察が来る前に逃げた。","thief は盗みをする人。複数形は thieves で、f が v に変わる。"],
    ["saint","The church is named after a local saint.","その教会は地元の聖人にちなんで名づけられている。","saint は宗教上の聖人。名前の前では Saint、略して St. と書くことがある。"],
    ["sculpture","A stone sculpture stands beside the entrance.","入り口の横に石の彫刻がある。","a sculpture は一つの彫刻作品。芸術分野としては sculpture と数えず使える。"],
    ["grief","Friends supported her through her grief.","友人たちは悲しみの中にある彼女を支えた。","grief は喪失などによる深い悲しみ。通常数えない名詞で使う。"],
    ["lane","Keep your bicycle in the marked lane.","自転車は標示された車線内を走らせてください。","lane は道路の車線や細い道。a bike lane は自転車用の通行帯。"],
    ["predator","The fox is a predator of small animals.","キツネは小動物を捕食する動物だ。","predator は獲物を捕らえて食べる側。食べられる獲物は prey と呼ぶ。"],
    ["fluid","The diagram shows how fluid moves through the pipe.","図は流体が管を通る様子を示している。","fluid は流れる性質を持つもの。日常では液体を指しやすいが、物理では気体も含む。"],
    ["incentive","The prize gave the students an incentive to practice.","その賞は生徒が練習する励みになった。","an incentive to do は行動を促す動機や報酬。to の後に行動を示す。"],
    ["bride","The bride thanked the guests for coming.","花嫁は来てくれた客に感謝した。","bride は結婚する女性、特に式の前後の呼び方。花婿は groom または bridegroom。"],
    ["intervention","Early intervention helped resolve the disagreement.","早期の介入が対立の解消に役立った。","intervention は状況を変えるため間に入ること。動詞は intervene。"],
    ["margin","Our team won by a narrow margin.","私たちのチームは僅差で勝った。","by a narrow margin は小さな差でという表現。紙の余白も margin と呼ぶ。"],
    ["biography","I read a biography of a famous explorer.","私は有名な探検家の伝記を読んだ。","a biography of ... は～の伝記。本人が書いた自伝は autobiography。"],
    ["consent","The photograph was published with her consent.","写真は彼女の同意を得て掲載された。","with someone's consent は人の同意を得てという意味。通常数えない名詞。"],
    ["volcano","The volcano has been quiet for many years.","その火山は長年、静かな状態だ。","volcano は火山。複数形には volcanoes と volcanos の二つがある。"],
    ["rebel","The rebels demanded a change in government.","反乱者たちは政府の交代を要求した。","名詞 rebel は反逆者で前半にアクセント。動詞 rebel against ... は～に反抗すること。"],
    ["metaphor","The poet uses a river as a metaphor for time.","詩人は川を時間の比喩として使っている。","a metaphor for ... は～を表す隠喩。like を用いた明示的な直喩は simile と呼ぶ。"],
    ["legislation","The committee discussed new environmental legislation.","委員会は新しい環境法制を議論した。","legislation は法律をまとめたものや立法。通常数えず、個別には a law などを使う。"],
    ["lightning","A flash of lightning lit up the sky.","稲光が空を照らした。","lightning は稲妻の光。雷の音は thunder で、一閃は a flash of lightning。"],
    ["pesticide","The study measured pesticide levels in the soil.","その研究は土中の農薬濃度を測った。","pesticide は害虫など有害な生物を防除する薬剤。昆虫用に限定する insecticide より広い語。"],
    ["column","She writes a weekly column about local history.","彼女は地域の歴史について毎週コラムを書いている。","column は新聞などの定期的な欄。表の縦列や建築の柱という意味もある。"],
    ["rumor","A rumor spread that the shop was closing.","店が閉まるといううわさが広まった。","rumor は確認されていない話。イギリス式のつづりは rumour。"],
    ["dust","A thin layer of dust covered the desk.","机は薄いほこりに覆われていた。","dust は細かい粒をまとめて指す通常数えない名詞。動詞 dust はほこりを払うこと。"],
    ["dialogue","The film contains very little dialogue.","その映画には会話がほとんどない。","dialogue は対話や作品中の会話。little とともに会話量を数えず表せる。"],
    ["kindergarten","The children sang together at kindergarten.","子どもたちは幼稚園で一緒に歌った。","kindergarten は幼児教育の施設・学年。対象年齢や制度は国によって異なる。"],
    ["diabetes","The lecture introduced basic research on diabetes.","講義では糖尿病の基礎研究が紹介された。","diabetes は糖尿病という病名。語尾に s があっても通常単数扱い。"],
    ["obesity","The report discusses factors associated with obesity.","報告書は肥満に関連する要因を論じている。","obesity は肥満という状態を表す名詞。形容詞は obese。"],
    ["patent","The inventor applied for a patent on the device.","発明者はその装置の特許を申請した。","apply for a patent は特許を申請すること。特許を得たことまで意味するわけではない。"],
    ["chapter","The final chapter answers the main question.","最終章は中心となる疑問に答えている。","chapter は本の大きな区分である章。paragraph『段落』とは分量の区分が異なる。"],
    ["palace","The palace gardens are open to visitors.","宮殿の庭園は来訪者に開放されている。","palace は王族などの壮大な住居。防御用の城 castle と意味が重なるとは限らない。"],
    ["laundry","I do the laundry on Saturday mornings.","私は土曜日の朝に洗濯をする。","do the laundry は洗濯すること。laundry は洗濯物も指す通常数えない名詞。"],
    ["ward","She works in the children's ward.","彼女は小児病棟で働いている。","ward は病院の病棟・病室区分。市の行政区という意味もある。"],
    ["outbreak","The report describes an outbreak of disease in the town.","報告書は町での病気の発生を記している。","an outbreak of ... は病気や争いが突然発生すること。of の後に起きたものを置く。"],
    ["equation","We solved the equation using the method from class.","授業で習った方法で方程式を解いた。","equation は等号で二つの式を結ぶ方程式・等式。solve an equation は解を求めること。"],
    ["archaeologist","The archaeologist studied tools found near the river.","考古学者は川の近くで見つかった道具を調べた。","archaeologist は遺物などから過去を調べる研究者。学問の名前は archaeology。"],
    ["corruption","The investigation uncovered corruption in the organization.","調査で組織内の汚職が明らかになった。","corruption は権力の不正利用や汚職。データの破損という別の意味にも使う。"],
    ["germ","The experiment examined germs on different surfaces.","その実験はさまざまな表面の病原菌を調べた。","germ は病気を起こす微生物を指す日常語。細菌という分類名 bacteria と完全に同じ範囲ではない。"],
    ["revenue","Ticket sales are the museum's main source of revenue.","入場券の売上が博物館の主な収入源だ。","revenue は事業や政府の収入。費用を差し引いた利益 profit と区別する。"],
    ["spouse","Employees may bring their spouse to the event.","従業員は催しに配偶者を連れてきてもよい。","spouse は夫または妻を性別を指定せずに表す改まった語。複数形は spouses。"],
    ["epidemic","The report describes an epidemic in the region.","報告書はその地域の感染症の流行を記している。","epidemic はある地域で病気が広がる流行。形容詞としても使われる。"],
    ["mortality","The researchers compared mortality rates across regions.","研究者たちは地域間の死亡率を比較した。","mortality rate は死亡率。mortality 単独では死ぬことや人間の有限性も表す。"],
    ["syndrome","The lecture explained the symptoms associated with the syndrome.","講義はその症候群に関連する症状を説明した。","syndrome は一緒に現れる特徴的な症状の集まり。個別の症状 symptom と区別する。"],
    ["retail","She has worked in retail for several years.","彼女は小売業で数年働いている。","retail は消費者へ直接売る小売り。卸売りは wholesale と呼ぶ。"],
    ["dose","The label states the amount in each dose.","ラベルには一回分の用量が書かれている。","dose は一度に投与・摂取する量。薬そのもの全体ではなく、一回の量に焦点がある。"],
    ["beverage","Hot beverages are available in the lounge.","ラウンジで温かい飲み物を利用できる。","beverage は drink より改まった飲み物の呼び方。メニューや案内文に使われる。"],
    ["metabolism","The class studied how metabolism releases energy from food.","授業では代謝が食べ物からエネルギーを取り出す仕組みを学んだ。","metabolism は体内の化学反応全体である代謝。単に食物の消化だけを指す語ではない。"],
    ["hybrid","This plant is a hybrid of two different varieties.","この植物は二つの異なる品種の交配種だ。","hybrid は異なる種類を組み合わせたもの。車や働き方などの組み合わせにも使う。"],
    ["scent","The scent of flowers filled the room.","花の香りが部屋に満ちた。","scent は香りや生物の残すにおい。動物が追うにおいの跡にも使う。"],
    ["inflammation","The textbook explains the process of inflammation.","教科書は炎症の過程を説明している。","inflammation は炎症という状態。動詞 inflame には炎症を起こさせる意味がある。"],
    ["pill","The pharmacist showed her how the pills were packaged.","薬剤師は錠剤がどう包装されているか彼女に示した。","pill は飲み込む小さな固形の薬。薬全般を指す medicine より形が限定される。"],
    ["grave","The report raised grave concerns about the building.","報告書は建物について重大な懸念を示した。","形容詞 grave は深刻な・重大な。名詞 a grave は墓という別の意味。"],
    ["fertile","The river valley has fertile soil.","川沿いの谷には肥沃な土がある。","fertile は作物がよく育つこと。a fertile imagination は豊かな想像力という比喩。"],
    ["hostile","The audience was initially hostile to the proposal.","聴衆は初め、その提案に反感を抱いていた。","hostile to ... は敵対的・反対の態度。hostile conditions は生存に厳しい環境になる。"],
    ["indispensable","A good map is indispensable for this journey.","よい地図はこの旅に不可欠だ。","indispensable for/to ... はなくてはならないこと。単に便利という意味より強い。"],
    ["oriented","The course is oriented toward practical skills.","その講座は実用的な技能を重視している。","be oriented toward ... は～を中心に方向づけられていること。goal-oriented は目標志向の。"],
    ["splendid","We enjoyed a splendid view of the mountains.","私たちは山々の見事な眺めを楽しんだ。","splendid は非常にすばらしいという評価。景色や出来事の見事さを表せる。"],
    ["competent","She is a competent and reliable guide.","彼女は有能で頼れるガイドだ。","competent は仕事を適切にできる能力があること。be competent at doing と技能を示せる。"],
    ["supreme","The court has supreme authority in these matters.","その裁判所はこれらの事柄について最高の権限を持つ。","supreme は順位や権限が最高のこと。the Supreme Court は最高裁判所を指す。"],
    ["straightforward","The instructions are clear and straightforward.","説明は明確でわかりやすい。","straightforward は複雑な点や隠し事がなく明快なこと。人の率直な態度にも使う。"],
    ["sacred","The mountain is sacred to the local community.","その山は地域の人々にとって神聖だ。","sacred to ... は～にとって神聖なこと。大切で侵してはならないものにも使う。"],
    ["bold","It was a bold decision to change the whole design.","設計全体を変えるのは大胆な決断だった。","bold は恐れず思い切ったこと。文字の bold type は太字を表す。"],
    ["uneasy","I felt uneasy about leaving the door unlocked.","鍵をかけずに出ることに不安を感じた。","be uneasy about ... は落ち着かない不安。easy の単純な否定として難しいという意味ではない。"],
    ["neat","Her notes are always neat and easy to read.","彼女のノートはいつも整って読みやすい。","neat はきちんと整理されたこと。a neat solution は巧みで簡潔な解決策。"],
    ["shallow","The water is shallow near the shore.","岸の近くは水が浅い。","shallow は深さが小さいこと。shallow thinking は考えが浅いという比喩になる。"],
    ["fake","The detective discovered that the painting was fake.","探偵はその絵が偽物だと突き止めた。","fake は本物に見せかけたこと。名詞 a fake は偽物を一つ数える形。"],
    ["superficial","The damage was only superficial.","損傷は表面だけだった。","superficial は表面に限られること。superficial knowledge は深い理解のない表面的な知識。"],
    ["absurd","It would be absurd to build a bridge with no road to it.","つながる道のない橋を造るのはばかげている。","absurd は理屈に合わずおかしいこと。相手の考えへの強い否定にもなる語。"],
    ["fragile","Please handle the fragile cups carefully.","壊れやすいカップを丁寧に扱ってください。","fragile は簡単に壊れたり損なわれたりすること。関係や平和のもろさにも使う。"],
    ["respectable","They earned a respectable score in their first competition.","彼らは初めての大会で立派な得点を取った。","respectable は十分に評価できる・ちゃんとした。respectful『敬意を示す』とは意味が違う。"],
    ["magnificent","The old hall has a magnificent ceiling.","その古いホールには壮麗な天井がある。","magnificent は大きさや美しさが見事で感動的なこと。建築や景観によく合う。"],
    ["infinite","The story imagines an infinite universe.","その物語は無限の宇宙を想像している。","infinite は限界や終わりがないこと。名詞 infinity は無限を表す。"],
    ["comprehensive","The guide provides a comprehensive overview of the city.","その案内書は都市を幅広く網羅して紹介している。","comprehensive は必要な範囲を広く含むこと。理解できるという comprehensible と区別する。"],
    ["steep","The path becomes steep near the summit.","道は頂上近くで急になる。","steep は傾斜が大きいこと。a steep rise in prices は価格の急上昇にも使う。"],
    ["gross","The report lists gross income before expenses.","報告書には経費を引く前の総収入が載っている。","gross は控除前の総額。差し引いた後の正味の額は net と表す。"],
    ["subsequent","Subsequent tests confirmed the first result.","その後の検査で最初の結果が確認された。","subsequent はある出来事より後に続くこと。必ず直後の一つだけを指すわけではない。"],
    ["sincere","Please accept my sincere thanks.","心からのお礼をお受け取りください。","sincere は偽りのない本心からのこと。sincerely は手紙の結びにも使う副詞。"],
    ["toxic","The label warns that the substance is toxic.","ラベルはその物質が有毒だと警告している。","toxic は生物に害を与える毒性があること。名詞 toxin は毒素。"],
    ["neutral","The chair remained neutral during the debate.","議長は討論中、中立を保った。","neutral はどちらにも肩入れしないこと。色では派手でない中間色を表す場合もある。"],
    ["diligent","She is diligent in checking every detail.","彼女は細部まで勤勉に確認する。","diligent は注意と努力を惜しまず続けること。副詞は diligently。"],
    ["sore","My feet were sore after the long walk.","長く歩いた後、足が痛かった。","sore は体の部分が痛む形容詞。a sore throat はのどの痛みという組み合わせ。"],
    ["contaminated","The samples were contaminated during transport.","試料は輸送中に汚染された。","contaminated は contaminate の過去分詞。be contaminated with ... で混入したものを示せる。"],
    ["ambiguous","The sentence is ambiguous without more context.","その文は文脈がないと曖昧だ。","ambiguous は複数の解釈が可能なこと。単に詳しくない vague とは焦点が違う。"],
    ["oral","The exam includes an oral presentation.","試験には口頭発表が含まれる。","oral は口頭の、または口に関すること。oral history は語り伝えられた歴史。"],
    ["restless","The children grew restless during the long wait.","長く待つうちに子どもたちは落ち着かなくなった。","restless はじっとしていられないこと。restful『安らげる』の単なる比較形ではない。"],
    ["rotten","We removed the rotten boards from the floor.","私たちは床の腐った板を取り除いた。","rotten は腐敗した・腐朽した状態。rot は腐るという動詞。"],
    ["vigorous","The plan led to vigorous debate.","その計画は活発な議論を招いた。","vigorous は勢いと活力があること。活動や成長の強さを示す。"],
    ["immense","The project required immense patience.","その事業には非常に大きな忍耐が必要だった。","immense は量や程度が非常に大きいこと。物の大きさにも抽象的な性質にも使う。"],
    ["metropolitan","The railway serves the whole metropolitan area.","その鉄道は大都市圏全域を結んでいる。","metropolitan area は中心都市とその周辺を含む都市圏。中心部だけに限定しない。"],
    ["punctual","Please be punctual for the interview.","面接には時間どおりに来てください。","punctual は決められた時間を守ること。早い fast や迅速な prompt とは区別する。"],
    ["solitary","A solitary tree stood in the field.","野原に一本だけ木が立っていた。","solitary は一つ・一人であること。必ずしも寂しい lonely という感情を含まない。"],
    ["collective","The project was a collective effort.","その事業は皆の共同の努力によるものだった。","collective は集団全体で行う・共有すること。individual『個人の』と対比できる。"],
    ["diplomatic","The countries restored diplomatic relations.","両国は外交関係を回復した。","diplomatic は国家間の外交に関すること。人の対応が巧みで穏便な場合にも使う。"],
    ["nasty","There was a nasty smell in the cupboard.","戸棚の中に不快な臭いがあった。","nasty は不快・嫌なという幅広い語。a nasty remark は意地悪な発言。"],
    ["helpless","I felt helpless when I could not reach anyone.","誰にも連絡できず、私は無力に感じた。","helpless は自力で対処できないこと。助けを提供する helpful とは意味が異なる。"],
    ["explicit","The instructions give explicit details about each step.","説明には各手順が明確に詳述されている。","explicit は曖昧にせずはっきり示すこと。implicit は暗に示されたという対になる語。"],
    ["bankrupt","The company went bankrupt after years of losses.","会社は長年の赤字の末に破産した。","go bankrupt は破産すること。bankruptcy は破産という名詞。"],
    ["eternal","The poem describes a wish for eternal peace.","その詩は永遠の平和への願いを描いている。","eternal は終わりなく続くこと。長期的な permanent より永遠性を強く表す。"],
    ["sole","She was the sole survivor of the fictional expedition.","架空の探検隊で彼女は唯一の生存者だった。","sole はただ一つのという形容詞。名詞では足や靴の裏を表す。"],
    ["sour","The lemon juice tasted sour.","レモン汁は酸っぱかった。","sour は酸味があること。味の苦い bitter と区別する。"],
    ["notable","There was a notable improvement in her writing.","彼女の作文には目立った向上があった。","notable は注意を向ける価値があるほど顕著なこと。副詞 notably は特に・著しく。"],
    ["affluent","The survey compared affluent and low-income neighborhoods.","調査は裕福な地域と低所得の地域を比較した。","affluent はお金や物に恵まれたこと。流暢な fluent と似たつづりだが意味が違う。"],
    ["naked","These stars are visible to the naked eye.","これらの星は肉眼で見える。","the naked eye は望遠鏡などを使わない肉眼。naked の基本は覆いのない・裸の。"],
    ["vocal","The singer did some vocal exercises before the concert.","歌手は公演前に発声練習をした。","vocal は声に関する形容詞。a vocal critic は意見を声高に表す批判者を指す。"],
    ["feminine","The dictionary marks the noun as feminine.","辞書はその名詞を女性名詞と記している。","feminine は文法上の女性などを表す。人や様式に使うと、女性的とされる特徴を指す。"],
    ["vacant","The seat beside me was vacant.","私の隣の席は空いていた。","vacant は人に占められていないこと。a vacant position は人員を募集している空きの役職。"],
    ["exotic","The greenhouse contains exotic plants from distant regions.","温室には遠い地域の珍しい外来植物がある。","exotic はある場所の人にとって珍しく異国風なこと。何が珍しいかは見る側によって変わる。"],
    ["rigid","The container has rigid sides.","その容器の側面は硬く曲がらない。","rigid は物理的に曲がらないこと。rigid rules は融通の利かない規則を表す。"],
    ["humid","The air became hot and humid before the storm.","嵐の前に空気が暑く湿っぽくなった。","humid は空気中の湿気が多いこと。温度の高さ自体は必ずしも含まない。"],
    ["outstanding","She made an outstanding contribution to the project.","彼女はその事業に傑出した貢献をした。","outstanding は非常に優れたこと。an outstanding payment は未払いの支払いという別の意味。"],
    ["addicted","The story follows a man addicted to gambling.","その物語はギャンブルに依存する男性を描いている。","be addicted to ... は～に依存していること。to は前置詞なので名詞や -ing 形を続ける。"],
    ["vulnerable","Young plants are vulnerable to frost.","若い植物は霜の害を受けやすい。","vulnerable to ... は～で傷ついたり被害を受けたりしやすいこと。弱い部分を持つ状態を表す。"],
    ["spontaneous","The audience broke into spontaneous applause.","観客から自然に拍手が起こった。","spontaneous は前もって計画せず自然に起きること。自発的な反応や行動に使う。"],
    ["greedy","The greedy character wanted all the treasure.","その欲深い登場人物は財宝を独り占めしたがった。","greedy は必要以上に欲しがること。単なる意欲より否定的な評価を含む。"],
    ["trivial","Do not let a trivial detail delay the whole project.","ささいな点で事業全体を遅らせないでください。","trivial は重要でない小さなこと。話し手が重要性を低く評価する語。"],
    ["per capita","The report compares water use per capita.","報告書は一人当たりの水使用量を比較している。","per capita は一人当たりという二語の表現。人口規模が違う集団を比較するときに使う。"],
    ["inherent","There are risks inherent in any experiment.","どの実験にも本来伴う危険がある。","inherent in ... は性質上もともと含まれること。外から一時的に加わるものと区別する。"],
    ["promising","The first test produced promising results.","最初の試験では期待できる結果が出た。","promising は今後の成功が期待されること。成功が確定したという意味ではない。"],
    ["physiological","The study measured physiological responses to exercise.","その研究は運動に対する生理的反応を測定した。","physiological は体の機能に関すること。心理的な psychological と区別する。"],
    ["clinical","The team published the results of a clinical study.","チームは臨床研究の結果を発表した。","clinical は実際の患者の診療や人を対象とする研究に関わること。基礎実験だけを指す語ではない。"],
    ["chronic","The village faces a chronic shortage of teachers.","その村は慢性的な教員不足に直面している。","chronic は長く続く・繰り返すこと。病気以外の解消しない問題にも使う。"],
    ["geological","The rocks reveal the region's geological history.","岩石は地域の地質学的な歴史を示している。","geological は地球の構造や岩石の変化に関すること。地理の geographical と区別する。"],
    ["countless","Countless stars were visible in the clear sky.","澄んだ空に無数の星が見えた。","countless は数え切れないほど多いこと。通常、数えられる名詞の複数形を修飾する。"],
    ["innate","The researcher studied innate responses in young animals.","研究者は幼い動物の生得的な反応を調べた。","innate は学習によらず生まれつき備わること。acquired は後から得たという対比になる。"],
    ["alert","Stay alert to changes in the weather.","天候の変化に注意を払ってください。","be/stay alert to ... は～を見逃さず注意すること。名詞 an alert は警報。"],
    ["autonomous","The team tested an autonomous vehicle on a closed course.","チームは閉鎖コースで自律走行車を試験した。","autonomous は外部の直接操作なしに自律的に動くこと。自動運転車以外の組織や機械にも使う。"],
    ["simultaneously","The two screens showed the results simultaneously.","二つの画面は同時に結果を表示した。","simultaneously は同時にという副詞。形容詞は simultaneous。"],
    ["utterly","I was utterly confused by the map.","私はその地図を見て完全に混乱した。","utterly は完全にという強い副詞。confused や impossible などを強調する。"],
    ["drastically","The new route drastically reduced travel time.","新しい経路で移動時間が大幅に短縮された。","drastically は変化の程度が非常に大きいこと。見た目が派手という意味に限定されない。"],
    ["necessarily","A longer answer is not necessarily a better answer.","長い答えが必ずしもよい答えとは限らない。","not necessarily は必ずしも～でないという部分否定。常に悪いと断定しているわけではない。"],
    ["thereby","We grouped the tasks, thereby saving time.","私たちは作業をまとめ、そうすることで時間を節約した。","thereby はその方法・行為によってという意味。前の行動とその結果を結びつける。"],
    ["frankly","Frankly, I think the plan needs more work.","率直に言うと、その計画はさらに検討が必要だと思う。","frankly は遠慮なく本心を述べるときの副詞。文頭に置いて発言全体を修飾できる。"],
    ["namely","We need one thing, namely, a clear schedule.","私たちに必要なのは一つ、すなわち明確な予定表だ。","namely は前の内容を具体的に言い直す語。単なる例の追加ではなく内容を特定する。"],
    ["hence","The road is closed, hence the need for another route.","道路が閉鎖されているため、別の経路が必要だ。","hence はそれゆえという改まった語。理由を受けて結果や必要性を示す。"],
    ["via","We traveled to the island via the coastal town.","私たちは海沿いの町を経由して島へ行った。","via は経由地や通信手段を示す前置詞。via email はメールでという意味。"],
    ["owing","The match was canceled owing to heavy rain.","試合は大雨のため中止になった。","原因を示す熟語は owing to ... の形。owing だけで名詞を続けず、to も含めて覚える。"],
    ["clarify","Could you clarify what you mean by 'soon'?","『すぐに』とはいつなのか明確にしてもらえますか。","clarify は不明な点をわかりやすくすること。clarify a point は要点を明確にする意味。"],
    ["smash","The falling branch smashed the window.","落ちた枝が窓を粉々に割った。","smash は強い力で激しく壊すこと。smash into ... は勢いよく衝突する形。"],
    ["mourn","The village mourned the loss of its oldest resident.","村は最年長の住民を失ったことを悲しんだ。","mourn は死や喪失を深く悲しむこと。mourn a loss と直接目的語を取れる。"],
    ["summon","The manager summoned the team to a meeting.","管理者はチームを会議に呼び集めた。","summon は権限をもって呼び出すこと。summon courage は勇気を奮い起こす比喩。"],
    ["shatter","The glass shattered when it hit the floor.","ガラスは床に当たると粉々になった。","shatter は細かく砕ける・砕くこと。shatter hopes は希望を打ち砕く比喩になる。"],
    ["linger","The smell of coffee lingered in the room.","コーヒーの香りが部屋に残っていた。","linger はすぐ消えず残る、または立ち去らずとどまること。予想より長く続く感じがある。"],
    ["lament","The residents lamented the loss of the old theater.","住民は古い劇場がなくなったことを嘆いた。","lament は失ったものなどを悲しむ改まった語。声や文章で嘆きを表す場面に使う。"],
    ["endowed","The region is endowed with rich natural resources.","その地域は豊かな天然資源に恵まれている。","be endowed with ... は資質や資源を与えられていること。endowed は endow の過去分詞。"],
    ["rejoice","We rejoiced at the news of her safe return.","私たちは彼女が無事に戻った知らせを喜んだ。","rejoice at/in ... は大いに喜ぶこと。joy を含む形と意味を結びつけられる。"],
    ["allocate","The school allocated funds to the library.","学校は図書館に資金を配分した。","allocate A to B は『BにAを割り当てる』。資金・時間・資源などに使う。"],
    ["slap","He slapped his hand on the table in frustration.","彼は苛立ってテーブルを手のひらでたたいた。","slap は平たい面でぴしゃりと打つこと。slapped と slapping では p を重ねる。"],
    ["contend","The author contends that the policy needs revision.","著者はその方針に修正が必要だと主張している。","contend that ... は主張を述べる形。contend with difficulties は困難に対処する別の用法。"],
    ["swear","She swore that she had told the truth.","彼女は真実を話したと誓った。","活用は swear–swore–sworn。swear は誓う意味のほか、ののしる言葉を使う意味もある。"],
    ["discern","I could barely discern the sign through the fog.","霧越しに看板をかろうじて見分けられた。","discern はわかりにくいものを識別すること。discern a difference は違いを見て取る意味。"],
    ["degrade","Pollution can degrade the quality of the soil.","汚染は土の質を低下させることがある。","degrade は質や価値を下げること。人をおとしめる意味にもなる。"],
    ["erect","The workers erected a fence around the site.","作業員は現場の周囲に柵を設置した。","erect は建造物などを立てる動詞。形容詞としては直立した状態も表す。"],
    ["testify","The witness testified that the road was dark.","証人は道路が暗かったと証言した。","testify that ... は証言内容を文で示す形。testify to ... は事実の証拠となる意味にもなる。"],
    ["spur","The success spurred us to continue the project.","成功を受け、私たちは事業を続ける意欲を強めた。","spur 人 to do は行動へ駆り立てること。spurred では r を重ねる。"],
    ["roam","We roamed the old streets without a plan.","私たちはあてもなく古い街路を歩き回った。","roam は自由に広く動き回ること。決まった目的地へ直進する意味とは異なる。"],
    ["frown","She frowned at the confusing instructions.","彼女はわかりにくい説明を見て眉をひそめた。","frown at ... は不快や困惑で眉を寄せること。frown on ... は好ましくないと見る熟語。"],
    ["lure","The bright display lured visitors into the shop.","明るい展示に引かれ、来訪者は店に入った。","lure A into B は『AをBへ誘い込む』。魅力を使って引き寄せる感覚がある。"],
    ["defy","The result defied all our expectations.","結果は私たちの予想をことごとく裏切った。","defy は権威に逆らう、または予想に従わないこと。過去形は defied。"],
    ["stroll","We strolled along the river after dinner.","夕食後、私たちは川沿いをのんびり歩いた。","stroll は急がず散歩すること。名詞では go for a stroll と使える。"],
    ["rattle","The windows rattled in the wind.","窓は風でがたがた鳴った。","rattle は硬い物が揺れて連続した音を立てること。人を動揺させる意味もある。"],
    ["reconcile","It is hard to reconcile the two accounts of the event.","その出来事の二つの説明を矛盾なく合わせるのは難しい。","reconcile A with B は食い違うものを調和させること。仲違いした人を和解させる意味もある。"],
    ["blur","The rain blurred the view through the window.","雨で窓越しの景色がぼやけた。","blur は輪郭を不鮮明にすること。blurred と blurring では r を重ねる。"],
    ["soothe","The quiet music soothed the restless child.","静かな音楽が落ち着かない子をなだめた。","soothe は痛みや不安を和らげること。穏やかな刺激で落ち着かせる感覚がある。"],
    ["impair","Poor lighting can impair our ability to read small print.","照明が悪いと細かい文字を読む力が損なわれることがある。","impair は機能や能力を弱めること。完全に失わせる意味とは限らない。"],
    ["comply","All visitors must comply with the rules.","すべての来訪者は規則に従わなければならない。","comply with ... は要求・規則に従うこと。with を省いて目的語を直接続けない。"],
    ["pierce","The needle pierced the thick fabric.","針が厚い布を貫いた。","pierce は尖ったもので穴を開ける・貫くこと。piercing sound は耳をつんざく音。"],
    ["stumble","I stumbled over a root on the path.","道の木の根につまずいた。","stumble over ... は～につまずくこと。stumble upon ... は偶然見つける熟語。"],
    ["hinder","The snow hindered our progress.","雪が私たちの前進を妨げた。","hinder は進行を遅らせる・難しくすること。完全に止める prevent より弱い場合もある。"],
    ["mock","The other character mocked his grand plans.","別の登場人物は彼の壮大な計画をあざけった。","mock は人や物をばかにすること。a mock exam は模擬試験という別の用法。"],
    ["embody","The building embodies the architect's love of nature.","その建物は建築家の自然への愛を具体的に表している。","embody は抽象的な理念を形にすること。考えが人や作品に現れている場面で使う。"],
    ["stalk","The cat stalked the bird through the grass.","猫は草の中から鳥に忍び寄った。","stalk は見つからないよう後を追うこと。人を執拗につけ回す行為にも使う。"],
    ["proclaim","The notice proclaimed the opening of the new library.","掲示は新図書館の開館を告げていた。","proclaim は広く公に宣言すること。proclaim that ... と文を続けることもできる。"],
    ["applaud","The audience applauded the performers.","観客は出演者に拍手を送った。","applaud は拍手する・称賛すること。相手を直接目的語に取れる。"],
    ["inflict","The storm inflicted damage on the harbor.","嵐は港に被害を与えた。","inflict A on B は『BにAを与える』。Aは損害や苦痛など好ましくないもの。"],
    ["merge","The two paths merge near the river.","二本の道は川の近くで合流する。","merge は別々のものが一つになること。企業の合併にも同じ動詞を使う。"],
    ["evacuated","The residents were evacuated before the river flooded.","住民は川が氾濫する前に避難させられた。","evacuated は evacuate の過去形・過去分詞。人を安全な所へ移す意味で受け身にも使う。"],
    ["undone","My shoelace came undone during the walk.","歩いている間に靴ひもがほどけた。","undone は undo の過去分詞。come undone は結び目などがほどけることで、未完了の意味もある。"],
    ["poke","She poked the soft ground with a stick.","彼女は棒で柔らかい地面を突いた。","poke A with B は『BでAを突く』。鋭く一度押すような動作を表す。"],
    ["haunted","He was haunted by the memory of his mistake.","彼は失敗の記憶に悩まされ続けた。","be haunted by ... は記憶や不安が頭から離れないこと。a haunted house は幽霊屋敷。"],
    ["adhere","We must adhere to the agreed schedule.","私たちは合意した予定を守らなければならない。","adhere to ... は規則などを固く守ること。物が表面にくっつく意味にも使う。"],
    ["compile","She compiled a list of useful resources.","彼女は役立つ資料の一覧をまとめた。","compile は散らばる情報を集めて整理すること。プログラムのコンパイルにも使う。"],
    ["wither","The flowers withered in the dry heat.","花は乾いた暑さでしおれた。","wither は植物が水分や活力を失うこと。勢力などが衰える比喩にもなる。"],
    ["stun","The unexpected result stunned everyone.","予期しない結果に皆が驚いた。","stun は一時言葉を失うほど驚かせること。stunned では n を重ねる。"],
    ["choke","He began to choke on a piece of food.","彼は食べ物を喉に詰まらせ始めた。","choke on ... は～が詰まって呼吸しにくくなること。単に咳をする cough と区別する。"],
    ["deteriorate","The road deteriorated after years without repairs.","道路は何年も修理されず悪化した。","deteriorate は状態が徐々に悪くなる自動詞。通常は対象を直接目的語に取らない。"],
    ["dump","Someone had dumped rubbish beside the road.","誰かが道端にごみを捨てていた。","dump は不用意に大量に捨てる・下ろすこと。適切に処分するという意味とは限らない。"],
    ["murmur","She murmured a few words of thanks.","彼女は小声でお礼を述べた。","murmur は低く静かに言うこと。水や群衆の低いざわめきにも使える。"],
    ["delete","Delete the duplicate paragraph from the document.","文書から重複した段落を削除してください。","delete A from B は『BからAを削除する』。文字・データなどに使う。"],
    ["inhibit","The cold can inhibit plant growth.","寒さは植物の成長を妨げることがある。","inhibit は活動や発達を抑えること。緊張が行動を抑制する場合にも使う。"],
    ["divert","The police diverted traffic away from the bridge.","警察は橋を避けるよう交通を迂回させた。","divert A from B は進路や注意をBからそらすこと。to で新しい行き先も示せる。"],
    ["tame","The story tells how the traveler tamed a wild horse.","その話は旅人が野生の馬を飼いならす様子を伝える。","動詞 tame は野生動物を人に慣らすこと。形容詞ならおとなしく飼いならされた状態。"],
    ["reap","The town began to reap the benefits of the new railway.","町は新鉄道の恩恵を受け始めた。","reap the benefits は努力などの成果を得る熟語。元の意味は作物を刈り取ること。"],
    ["affirm","She affirmed that the information was correct.","彼女は情報が正しいと断言した。","affirm は確かだと明言すること。affirm one's commitment は責任を果たす意志を表明する意味。"],
    ["immersed","He was immersed in a book when I arrived.","私が着くと、彼は本に没頭していた。","be immersed in ... は深く入り込んでいること。液体に浸される物理的な意味もある。"],
    ["expire","My library card expires next month.","私の図書館カードは来月期限が切れる。","expire は有効期間が終わる自動詞。期限の名詞は expiration や expiry。"],
    ["embark","We embarked on a new research project.","私たちは新しい研究計画に着手した。","embark on ... は大きな取り組みを始めること。船などに乗り込む意味から広がった用法。"],
    ["vow","They vowed to rebuild the damaged school.","彼らは損傷した学校を再建すると誓った。","vow to do は強く決意して約束すること。名詞 a vow は誓い。"],
    ["foresee","No one foresaw how popular the game would become.","そのゲームがどれほど人気になるか誰も予見しなかった。","foresee は前もって予想すること。活用は foresee–foresaw–foreseen。"],
    ["adore","My sister adores the little cat.","妹はその小さな猫が大好きだ。","adore は非常に好きで大切に思うこと。必ずしも宗教上の崇拝だけを意味しない。"],
    ["yearn","She yearned to see her hometown again.","彼女は故郷をもう一度見たいと切望した。","yearn to do は強く～したいと思うこと。yearn for ... は名詞を続ける形。"],
    ["undermine","Repeated errors undermined confidence in the system.","度重なる誤りがその仕組みへの信頼を損なった。","undermine は土台から徐々に弱めること。信頼・権威・努力などに使う。"],
    ["suck","The machine sucks dust into a container.","その機械はほこりを容器に吸い込む。","suck A into B は『AをBへ吸い込む』。口で吸う動作にも使う。"],
    ["pledge","The group pledged to protect the forest.","その団体は森を守ると誓った。","pledge to do は公的・正式に約束すること。名詞 a pledge は誓約。"],
    ["intrude","I did not want to intrude on their conversation.","私は二人の会話に立ち入りたくなかった。","intrude on ... は許可や歓迎なしに入り込むこと。相手の私的な領域を侵す響きがある。"],
    ["sue","The company was sued for breaking the agreement.","その会社は契約違反で訴えられた。","sue A for B は『Bを理由にAを訴える』。裁判での提訴を指す。"],
    ["distort","The curved glass distorted the image.","曲面のガラスが像を歪めた。","distort は本来の形や内容を変えてしまうこと。事実を歪曲する場合にも使う。"],
    ["extinguish","The firefighters extinguished the fire.","消防隊員は火を消した。","extinguish は燃えている火や光を消すこと。日常的な電灯の操作には turn off も使う。"],
    ["preach","The minister preached about kindness.","聖職者は思いやりについて説教した。","preach は宗教的な教えなどを説くこと。道徳をしつこく説くという否定的な使い方もある。"],
    ["curb","The new rules aim to curb unnecessary spending.","新しい規則は不要な支出を抑えることを目指す。","curb は行きすぎを抑制すること。名詞では道路の縁石という別の意味もある。"],
    ["withstand","The bridge was built to withstand strong winds.","橋は強風に耐えられるよう造られた。","withstand は力や困難に耐えること。活用は withstand–withstood–withstood。"],
    ["dip","She dipped the brush in water.","彼女は筆を水に浸した。","dip A in B は短時間つける動作。名詞 a dip は一時的な低下にも使う。"],
    ["recite","The students recited a short poem.","生徒たちは短い詩を暗唱した。","recite は覚えた文章などを声に出すこと。静かに読む read とは違う行為。"],
    ["thrust","He thrust the papers into his bag.","彼は書類をかばんに押し込んだ。","thrust は勢いよく押し出す・押し込むこと。原形・過去形・過去分詞が同じ。"],
    ["plead","She pleaded with him to reconsider.","彼女は考え直してほしいと彼に懇願した。","plead with 人 to do は人に強く頼む形。裁判では有罪・無罪を答弁する意味もある。"],
    ["humiliate","His public criticism humiliated the young actor.","公然の批判で若い俳優は恥をかかされた。","humiliate は相手の尊厳を傷つけ恥ずかしい思いをさせること。単なる照れより強い語。"],
    ["discharge","The pipe discharges water into the river.","その管は川に水を放出する。","discharge は外へ出すこと。人を退院させる・任務から解放する意味もある。"],
    ["condemn","The statement condemned the destruction of the library.","声明は図書館の破壊を非難した。","condemn は強く不当だと批判すること。condemn A to B は刑などを宣告する別の形。"],
    ["retrieve","The program retrieves records from the database.","プログラムはデータベースから記録を取り出す。","retrieve は保存先などから取り戻すこと。検索して取得する意味で、単に探す search と焦点が違う。"],
    ["shrug","He shrugged when I asked why the shop was closed.","店が閉まっている理由を尋ねると、彼は肩をすくめた。","shrug はわからない・気にしないなどを肩で示すこと。shrugged では g を重ねる。"],
    ["evoke","The photograph evoked memories of my childhood.","写真は子どものころの記憶を呼び起こした。","evoke は感情や記憶を引き出すこと。直接思い出せと命じるのではなく連想を起こす感覚。"],
    ["fetch","Could you fetch the map from the car?","車から地図を取ってきてもらえますか。","fetch は行って取って戻ること。持ってくる bring より往復の動作が明確。"],
    ["flatter","He tried to flatter the judge with compliments.","彼はほめ言葉で審査員にお世辞を言おうとした。","flatter は相手を喜ばせるためにほめること。誠実な称賛だけでなく下心を含む場合がある。"],
    ["prose","The author writes both poetry and prose.","その作家は詩と散文の両方を書く。","prose は詩の韻律形式によらない文章。通常数えない名詞として使う。"],
    ["textile","The town was once a center of textile production.","その町はかつて織物生産の中心だった。","textile は織物や布地。textile industry は繊維産業を表す。"],
    ["timber","The bridge was built from local timber.","橋は地元の材木で造られた。","timber は建築などに使う材木。素材全般では通常数えない名詞。"],
    ["masterpiece","Many critics regard the film as a masterpiece.","多くの批評家はその映画を傑作とみなしている。","a masterpiece は特に完成度の高い作品。絵画以外の映画や小説にも使う。"],
    ["riot","The novel describes a riot outside the palace.","小説は宮殿の外の暴動を描いている。","riot は群衆による暴力的な騒動。平和的な抗議 protest と区別する。"],
    ["carriage","We found seats in the last carriage.","私たちは最後尾の車両に席を見つけた。","carriage はイギリス英語で列車の車両。馬が引く客車という意味もある。"],
    ["apparatus","The experiment requires special measuring apparatus.","その実験には特別な測定装置が必要だ。","apparatus は特定目的の装置や器具一式。複数の部品をまとめて数えず表す場合もある。"],
    ["fuss","Please do not make a fuss about the small delay.","少しの遅れで大騒ぎしないでください。","make a fuss about ... は～で騒ぎ立てること。必要以上の心配や騒ぎという響きがある。"],
    ["deficiency","The report identifies a deficiency in the training program.","報告書は研修計画の不足点を指摘している。","a deficiency in ... は必要なものの不足。栄養素の欠乏にも使う。"],
    ["heir","She was the sole heir to the estate.","彼女はその財産の唯一の相続人だった。","heir to ... は～の相続人。h を発音しないため an heir とする。"],
    ["equator","The island lies close to the equator.","その島は赤道の近くにある。","equator は地球を南北の半球に分ける赤道。通常 the equator と定冠詞をつける。"],
    ["petroleum","The region exports petroleum and natural gas.","その地域は石油と天然ガスを輸出している。","petroleum は地下から得る石油を指す通常数えない名詞。ガソリン petrol と範囲が異なる。"],
    ["witch","The story features a witch who lives in a tower.","その物語には塔に住む魔女が登場する。","witch は魔女。疑問詞 which と同じ発音でもつづりと意味が異なる。"],
    ["vapor","Water vapor condensed on the cold glass.","水蒸気が冷たいガラスの表面で凝結した。","vapor は気体になった物質。イギリス式では vapour とつづる。"],
    ["probe","The space probe sent back images of the planet.","宇宙探査機は惑星の画像を送り返した。","probe は探査機や調べるための器具。動詞では詳しく探るという意味になる。"],
    ["expertise","The project needs expertise in water management.","その事業には水管理の専門知識が必要だ。","expertise in ... は～の専門的な知識・技能。通常数えないので an expertise とはしない。"],
    ["scorn","She rejected the unfair proposal with scorn.","彼女は不公平な提案を軽蔑して退けた。","scorn は価値がないとして見下す感情。動詞 scorn も目的語を直接取れる。"],
    ["prophet","The story follows a prophet who warns of a great flood.","その物語は大洪水を警告する預言者を描いている。","prophet は神の言葉を伝えるとされる人。profit『利益』とはつづりと意味が違う。"],
    ["breeze","A cool breeze came through the window.","涼しいそよ風が窓から入ってきた。","breeze は穏やかな風。会話の a breeze は非常に簡単なことという比喩にもなる。"],
    ["sin","The sermon discussed the meaning of sin.","説教は罪の意味について論じた。","sin は特に宗教や道徳上の罪。法律に違反する crime とは範囲が異なる。"],
    ["surge","The shop saw a surge in orders after the review.","書評の後、その店への注文が急増した。","a surge in ... は数量などの急な増加。波や人の流れの強い動きにも使う。"],
    ["complement","The soup is a good complement to the bread.","そのスープはパンによく合い、食事を引き立てる。","a complement to ... は組み合わせて補うもの。compliment『ほめ言葉』と区別する。"],
    ["queue","We joined the queue outside the museum.","私たちは博物館の外の列に並んだ。","queue は主にイギリス英語で順番待ちの列。発音は一音節で cue と同じ。"],
    ["stake","The safety of the visitors is at stake.","来訪者の安全がかかっている。","at stake は失うおそれがある・成否がかかっていること。stake 単独には賭け金の意味もある。"],
    ["ambassador","The ambassador attended the opening ceremony.","大使は開会式に出席した。","ambassador は国を代表する外交官。a goodwill ambassador は親善大使という表現。"],
    ["jury","The jury listened to the evidence.","陪審員団は証拠に耳を傾けた。","jury は陪審員の集団。一人なら a juror または a member of the jury。"],
    ["cluster","A cluster of houses stood near the river.","川の近くに家々が集まって建っていた。","a cluster of ... は近くにまとまった集まり。星や果実などにも使える。"],
    ["lump","There was a small lump under the carpet.","じゅうたんの下に小さな盛り上がりがあった。","lump は不規則な塊やこぶ。a lump of clay は粘土の塊を表す。"],
    ["meadow","Wildflowers covered the meadow in spring.","春には野の花が牧草地を覆った。","meadow は草の生える開けた土地。野草地や牧草を刈る草地を指す。"],
    ["feat","Crossing the mountains alone was a remarkable feat.","山々を一人で越えたことは驚くべき偉業だった。","feat は技能や勇気を要するすぐれた行為。feet『足』とは同じ発音でも別の語。"],
    ["temperament","The two brothers have very different temperaments.","その兄弟は気質が大きく異なる。","temperament は生来の感情や行動の傾向。一時的な気分 mood と区別する。"],
    ["chill","There was a chill in the evening air.","夕方の空気には冷たさがあった。","a chill は体に感じる寒さ。動詞 chill は冷やす・冷えるという意味。"],
    ["appliance","The store repairs household appliances.","その店は家庭用電化製品を修理する。","appliance は特定の家事などに使う機器。household appliances は家電製品全般。"],
    ["predecessor","The new manager continued the work of her predecessor.","新しい管理者は前任者の仕事を引き継いだ。","predecessor は前の役職にいた人。後任者は successor と呼ぶ。"],
    ["entity","The two departments operate as a single entity.","二つの部門は一つの組織体として運営されている。","entity は独立した一つの存在・組織。形のある物だけに限定しない。"],
    ["hospitality","We thanked the family for their hospitality.","私たちは家族のもてなしに感謝した。","hospitality は客を温かく迎えること。hospital『病院』と関連する形でも現在の意味は違う。"],
    ["narrative","The film presents a clear narrative of the journey.","映画は旅の経過をわかりやすい物語として示している。","narrative は出来事をつなげた語りや説明。物語の内容だけでなく組み立て方にも関わる。"],
    ["segment","The final segment of the program covers local news.","番組の最後の部分は地域ニュースを扱う。","a segment of ... は全体を分けた一部分。市場などを区分した集団にも使う。"],
    ["catastrophe","The flood was a catastrophe for the small town.","洪水はその小さな町にとって大災害だった。","catastrophe は極めて大きな被害を生む出来事。通常の小さな失敗よりはるかに強い語。"],
    ["monarch","The portrait shows the monarch wearing a crown.","肖像画には冠をかぶった君主が描かれている。","monarch は国王・女王などの君主。男性の王だけを指す語ではない。"],
    ["constraint","Time constraints limited the scope of the study.","時間の制約で研究の範囲が限られた。","constraint はできることを制限する条件。constraints on ... で制約される対象を示せる。"],
    ["amendment","The committee proposed an amendment to the rule.","委員会は規則の修正案を提案した。","an amendment to ... は文書や規則への修正。全体を新しく作り直すとは限らない。"],
    ["cosmos","The exhibit explores humanity's place in the cosmos.","展示は宇宙における人類の位置を考察している。","the cosmos は秩序ある全体としての宇宙。通常 the をつけて使う。"],
    ["aisle","Please keep the aisle clear.","通路をふさがないでください。","aisle は座席や棚の間の通路。s は発音せず、isle『小島』と同じ音。"],
    ["hierarchy","The chart shows the hierarchy within the organization.","図は組織内の階層を示している。","hierarchy は上下の順位による仕組み。職位や分類の段階にも使う。"],
    ["toll","Drivers pay a toll to cross the bridge.","運転者は橋を渡るために通行料を払う。","toll は道路・橋などの使用料。take a toll on ... は～に損害や負担を与える熟語。"],
    ["transaction","Each transaction is recorded in the system.","各取引はシステムに記録される。","transaction は売買や支払いなど一件の取引。transact は取引を行うという動詞。"],
    ["burglar","The burglar entered through an unlocked window.","侵入盗は鍵のかかっていない窓から入った。","burglar は建物に侵入して盗む人。暴力や脅迫で奪う robber と区別する。"],
    ["tyranny","The novel describes life under tyranny.","その小説は圧政下の生活を描いている。","tyranny は権力を横暴に使う支配。支配者を指す名詞は tyrant。"],
    ["parasite","The parasite depends on a host to survive.","その寄生生物は生きるために宿主に依存する。","parasite は他の生物から栄養などを得る寄生生物。寄生される側は host。"],
    ["intuition","Her intuition told her that something was wrong.","彼女は何かおかしいと直感した。","intuition は論理的な説明を経ずに感じ取ること。明確な証拠に基づく結論とは異なる。"],
    ["communist","The course compares communist and capitalist economic ideas.","その講座は共産主義と資本主義の経済思想を比較する。","communist は共産主義のという形容詞、またはその支持者。大文字かどうかは党名などの文脈による。"],
    ["legacy","The library is part of her lasting legacy.","図書館は彼女が後世に残したものの一部だ。","legacy は後に残した影響や遺産。財産だけでなく業績にも使う。"],
    ["vein","The diagram shows the veins in the arm.","図は腕の静脈を示している。","vein は血液を心臓へ戻す静脈。心臓から送り出す動脈は artery。"],
    ["discourse","The book examines public discourse about education.","その本は教育をめぐる公的な議論を分析している。","discourse はある主題についての言説・議論。日常の一回の会話より広い範囲にも使う。"],
    ["dairy","The farm produces milk and other dairy products.","その農場は牛乳やその他の乳製品を生産している。","dairy products は乳製品。日記という diary と文字の順番が異なる。"],
    ["artifact","The museum displays artifacts from the ancient settlement.","博物館は古代集落の人工物を展示している。","artifact は人が作った遺物など。必ずしも美術的な工芸品だけに限らない。"],
    ["outlet","Painting gives her an outlet for her emotions.","絵を描くことは彼女に感情のはけ口を与えている。","an outlet for ... は～を外へ表す手段。店舗・排出口・コンセントという意味もある。"],
    ["apprehension","I felt some apprehension before the interview.","私は面接前にいくらか不安を感じた。","apprehension は先の出来事への心配。通常数えない気持ちとして使える。"],
    ["melancholy","The music filled the room with melancholy.","その音楽は部屋をもの悲しい雰囲気で満たした。","melancholy は静かな悲しみ・憂鬱。名詞でも形容詞でも使う。"],
    ["novelty","The novelty of the new toy soon wore off.","新しいおもちゃの目新しさはすぐ薄れた。","novelty は新しいために感じる興味。a novelty は珍しい物そのものを指す。"],
    ["specimen","Each specimen was labeled before examination.","各標本は検査前にラベルを付けられた。","specimen は研究用に選んだ標本・試料。a specimen of ... で種類を示せる。"],
    ["hygiene","The course teaches basic food hygiene.","その講座は基本的な食品衛生を教える。","hygiene は清潔を保つ習慣や条件。通常数えない名詞として使う。"],
    ["tactics","The coach changed tactics in the second half.","コーチは後半に戦術を変えた。","tactics は具体的な行動手段。長期的な全体方針 strategy と区別できる。"],
    ["monopoly","The company once had a monopoly on local transport.","その会社はかつて地域交通を独占していた。","a monopoly on ... は～の独占。競争相手がいない支配的な状態を表す。"],
    ["token","Please accept this gift as a token of our thanks.","感謝のしるしとして、この贈り物をお受け取りください。","a token of ... は気持ちなどを示すしるし。代用貨幣や認証用データという意味もある。"],
    ["aristocracy","The book describes the lives of the aristocracy.","その本は貴族階級の暮らしを描いている。","the aristocracy は貴族という集団。一人の貴族は an aristocrat と呼ぶ。"],
    ["revenge","The character seeks revenge for the betrayal.","その登場人物は裏切りへの復讐を求めている。","revenge for ... は～に対する復讐。take revenge on 人で復讐の相手を示す。"],
    ["activist","Local activists organized a river cleanup.","地域の活動家たちは川の清掃を企画した。","activist は社会的・政治的な目的に向け積極的に活動する人。単に活発な人という意味ではない。"],
    ["rhetoric","The speech contained more rhetoric than practical proposals.","その演説は具体策より美辞麗句が多かった。","rhetoric は説得の言葉遣いや修辞。文脈によっては実質を伴わない言葉という否定的な意味。"],
    ["entrepreneur","The entrepreneur opened a business repairing old bicycles.","その起業家は古い自転車を修理する事業を始めた。","entrepreneur はリスクを取って事業を立ち上げる人。従業員 employee と役割が違う。"],
    ["census","The census recorded the population of each district.","国勢調査は各地区の人口を記録した。","census は集団全体を対象にした調査、特に国勢調査。標本調査だけを指す語ではない。"],
    ["verge","The old theater was on the verge of closing.","その古い劇場は閉鎖寸前だった。","on the verge of doing は今にも～しそうな状態。of の後に -ing 形を置く。"],
    ["advent","The advent of printing changed how knowledge spread.","印刷の登場は知識の広まり方を変えた。","the advent of ... は重要なものの出現・到来。日常の人の到着より大きな変化に使う。"],
    ["analogy","The teacher used an analogy between a cell and a factory.","先生は細胞と工場の類似を使って説明した。","an analogy between A and B は共通点をもとにした比較。完全に同じだとする意味ではない。"],
    ["irrigation","The farmers built channels for irrigation.","農家は灌漑用の水路を造った。","irrigation は田畑へ人工的に水を送ること。動詞は irrigate。"],
    ["coverage","The event received extensive news coverage.","その催しはニュースで広く報じられた。","news coverage は報道。保険の補償範囲や通信の到達範囲という意味もある。"],
    ["cuisine","The restaurant specializes in regional cuisine.","その店は郷土料理を専門にしている。","cuisine は地域や伝統に特徴的な料理・調理法。個々の一皿は a dish と呼ぶ。"],
    ["menace","The loose wire was a menace to passing cyclists.","外れた針金は通行する自転車にとって脅威だった。","a menace to ... は～に害を及ぼすおそれがあるもの。危険のもとを指す。"],
    ["peril","The travelers were in peril during the storm.","旅行者たちは嵐の間、危険にさらされていた。","in peril は深刻な危険にあるという改まった表現。形容詞は perilous。"],
    ["limb","The model shows the movement of each limb.","その模型は手足の各部の動きを示している。","limb は腕や脚の一本全体。手先 hand・足先 foot だけではない。"],
    ["assault","The report describes an assault on a passenger.","報告書は乗客への暴行を記している。","an assault on ... は～への攻撃・暴行。物理的な攻撃を表す強い語。"],
    ["hatred","The story shows how fear can turn into hatred.","その物語は恐怖が憎悪に変わる様子を描いている。","hatred は強い憎しみ。hatred of/for ... で対象を示せる。"],
    ["autonomy","The team has autonomy over its daily schedule.","そのチームは日々の予定を自分たちで決められる。","autonomy は自ら判断して運営する権限・自主性。形容詞は autonomous。"],
    ["cram","I tried to cram too much information into one slide.","私は一枚のスライドに情報を詰め込みすぎた。","cram は詰め込むという動詞。塾は cram school の二語で、cram 単独は塾を意味しない。"],
    ["subsidy","The farm received a subsidy for conserving water.","その農場は節水のための補助金を受けた。","subsidy は活動を支援するための金銭。複数形は subsidies。"],
    ["empathy","The teacher showed empathy for the new student.","先生は新入生の気持ちに寄り添った。","empathy は相手の感情を理解し感じ取ること。気の毒に思う sympathy と焦点が異なる。"],
    ["slang","This dictionary explains slang used in online chats.","その辞書はオンライン会話の俗語を説明している。","slang は集団内などのくだけた言葉。通常数えず、一語なら a slang expression と言える。"],
    ["posture","The drawing shows the dancer's upright posture.","絵は踊り手のまっすぐな姿勢を示している。","posture は立つ・座るときの体の構え。議論での姿勢や立場を指す場合もある。"],
    ["ideology","The course compares political ideologies.","その講座は政治思想を比較する。","ideology は社会や政治についての体系的な考え方。個別の案 idea より広い枠組み。"],
    ["curse","The character believes the old house is under a curse.","その登場人物は古い家が呪われていると信じている。","curse は呪い。a curse can mean a source of trouble のように災いのもとという比喩にもなる。"],
    ["tumor","The researchers studied the tumor cells in the laboratory.","研究者たちは実験室で腫瘍細胞を調べた。","tumor は腫瘍。すべてが悪性を意味するわけではなく、イギリス式では tumour。"],
    ["intersection","Turn left at the next intersection.","次の交差点を左へ曲がってください。","intersection は道などが交わる所。数学では集合の共通部分も表す。"],
    ["duration","Please remain seated for the duration of the performance.","公演の間は着席したままでいてください。","for the duration of ... は～が続く間ずっとという意味。時間の長さに焦点がある。"],
    ["deforestation","The study examines the effects of deforestation.","その研究は森林減少の影響を調べている。","deforestation は森林を伐採などで失うこと。植林・再森林化は reforestation。"],
    ["precaution","We carried an extra map as a precaution.","用心のため、私たちは予備の地図を持った。","as a precaution は万一に備えた措置としてという意味。take precautions は予防策を取ること。"],
    ["bunch","She placed a bunch of flowers on the table.","彼女はテーブルに一束の花を置いた。","a bunch of ... は束やまとまり。花やバナナなど、まとめられたものに使う。"],
    ["shortcoming","The review points out several shortcomings in the design.","その批評は設計のいくつかの欠点を指摘している。","shortcoming は期待する水準に届かない点。short『短い』から不足する部分と捉えられる。"],
    ["aspiration","Her aspiration is to become an architect.","彼女の大望は建築家になることだ。","aspiration は強く望む目標。aspirations と複数形で将来への志をまとめることも多い。"],
    ["psychiatrist","The article includes an interview with a psychiatrist.","記事には精神科医へのインタビューが含まれている。","psychiatrist は精神科の医師。psychologist『心理学者・心理職』とは資格や役割が異なる。"],
    ["shipping","The price includes shipping to your address.","価格には指定住所への送料が含まれている。","shipping は商品の発送や輸送。船便だけに限らず、送料という意味にも使う。"],
    ["senator","The senator spoke about education funding.","上院議員は教育予算について演説した。","senator は上院の議員。すべての議員一般を指す語ではない。"],
    ["statesman","The biography describes him as an experienced statesman.","その伝記は彼を経験豊かな政治家として描いている。","statesman は国政で力量を持つ政治家という評価を含む。中立的な職業名 politician と響きが違う。"],
    ["subordinate","The supervisor listened to suggestions from her subordinates.","監督者は部下たちの提案に耳を傾けた。","名詞 subordinate は下位の立場にある人。形容詞では subordinate to ...『～に従属する』。"],
    ["vacuum","His sudden departure left a leadership vacuum.","彼の突然の退任で指導者不在の状態になった。","vacuum は真空や何もない空白。a leadership vacuum は指導する人の不在を表す比喩。"],
    ["quest","The story follows a quest for a lost city.","その物語は失われた都市を探す旅を描いている。","a quest for ... は長く熱心に探し求めること。知識や真実の探究にも使える。"],
    ["meditation","She sets aside ten minutes for meditation.","彼女は瞑想のために十分間を確保している。","meditation は静かに心を集中させる瞑想。動詞 meditate と対応する。"],
    ["subscriber","Subscribers receive the newsletter every month.","登録者は毎月ニュースレターを受け取る。","subscriber は定期購読・配信などの登録者。有料会員だけに限定されない。"],
    ["riddle","Can you solve the riddle on this card?","このカードのなぞなぞを解けますか。","riddle はひねりのある問いや謎。solve a riddle は謎を解くという組み合わせ。"],
    ["rag","He wiped the tools with an old rag.","彼は古いぼろ布で道具を拭いた。","rag は古い布切れ。in rags はぼろぼろの服を着た状態を表す。"],
    ["rust","There was rust on the old gate.","古い門にさびがあった。","rust は鉄などに生じるさび。動詞でも使え、The gate rusted. は門がさびたという意味。"],
    ["sanitation","The project improved water supply and sanitation.","その事業は給水と衛生設備を改善した。","sanitation は上下水道や廃棄物処理などの衛生環境。個人の清潔習慣 hygiene と焦点が違う。"],
    ["midst","We arrived in the midst of a lively discussion.","私たちは活発な議論の最中に到着した。","in the midst of ... は～の真っ最中にという熟語。midst 単独よりこの形で覚える。"],
    ["mischief","The puppy was always getting into mischief.","その子犬はいつもいたずらをしていた。","mischief はいたずらや小さな悪さ。通常数えず、get into mischief という形で使う。"],
    ["proficiency","The test measures proficiency in English.","その試験は英語の熟達度を測る。","proficiency は技能に熟達していること。検定試験は a proficiency test で、語単独は検定そのものではない。"],
    ["recollection","I have no recollection of meeting him before.","以前彼に会った記憶はない。","recollection は思い出すことや記憶。a recollection of ... で内容を示せる。"],
    ["latitude","The map shows the latitude of each city.","地図は各都市の緯度を示している。","latitude は赤道から南北の位置を示す緯度。東西の位置は longitude『経度』。"],
    ["friction","Friction between the surfaces slows the movement.","表面同士の摩擦が動きを遅くする。","friction は触れ合う面の摩擦。人間関係の不和という比喩にも使う。"],
    ["botanist","The botanist identified the plants along the trail.","植物学者は道沿いの植物を識別した。","botanist は植物を研究する人。学問としての植物学は botany。"],
    ["heredity","The lesson explains how heredity affects certain traits.","授業は遺伝が特定の特徴にどう影響するかを説明している。","heredity は親から子へ特徴が伝わる遺伝。財産の相続 inheritance とは区別する。"],
    ["contempt","He spoke with contempt about the dishonest deal.","彼はその不正な取引について軽蔑を込めて話した。","contempt は価値が低いとして見下す気持ち。contempt for ... で対象を示す。"],
    ["anatomy","The diagram explains the anatomy of the human hand.","図は人間の手の構造を説明している。","anatomy は体の構造やそれを学ぶ解剖学。動きや機能を扱う physiology と区別する。"],
    ["integrity","Her integrity earned the trust of her colleagues.","彼女の誠実さは同僚の信頼を得た。","integrity は原則を曲げない誠実さ。構造が損なわれていない完全性という意味もある。"],
    ["cargo","The ship carried a cargo of grain.","船は穀物の貨物を運んでいた。","cargo は船や飛行機などで運ぶ貨物。a cargo of ... で積荷の内容を示す。"],
    ["bribe","The official refused to accept a bribe.","その役人は賄賂の受け取りを拒んだ。","bribe は不正な便宜を得るために渡す金品。動詞でも賄賂を贈る意味で使う。"],
    ["eruption","The eruption covered the nearby fields with ash.","噴火は近くの畑を灰で覆った。","eruption は噴火や急な噴出。動詞 erupt と関連づけて覚える。"],
    ["funeral","Many friends attended the funeral.","多くの友人が葬儀に参列した。","funeral は亡くなった人を送る儀式。attend a funeral は葬儀に参列すること。"],
    ["deficit","The budget showed a large deficit.","予算には大きな赤字があった。","deficit は収入などに対する不足額。余剰を表す surplus と対になる。"],
    ["bulk","The bulk of the work was finished by Friday.","作業の大部分は金曜日までに終わった。","the bulk of ... は～の大部分。in bulk は大量にまとめてという別の表現。"],
    ["millionaire","The novel follows a millionaire who loses his fortune.","その小説は財産を失う百万長者を描いている。","millionaire は百万通貨単位以上の資産を持つ人。どの通貨かは文脈による。"],
    ["ash","Only ash remained after the fire.","火の後には灰だけが残った。","ash は燃えた後の灰。ashes と複数形で燃え残りをまとめて指すこともある。"],
    ["realm","The question belongs to the realm of philosophy.","その問いは哲学の領域に属する。","the realm of ... は学問や活動の領域。王国という意味もある文章的な語。"],
    ["plantation","The documentary examines the history of a sugar plantation.","その記録映画は砂糖農園の歴史を調べている。","plantation は商品作物などを大規模に栽培する農園。歴史的な文脈にもよく現れる。"],
    ["plow","The farmer used a plow to turn the soil.","農家はすきで土を耕した。","plow は農具のすき、または耕す動詞。イギリス式のつづりは plough。"],
    ["vending","A vending machine stands near the station entrance.","駅の入り口近くに自動販売機がある。","vending は vend『販売する』の -ing 形。vending machine の組み合わせで覚える。"],
    ["orphan","The story follows an orphan raised by relatives.","その物語は親戚に育てられた孤児を描いている。","orphan は親を亡くした子。動詞の be orphaned は親を失うことを表す。"],
    ["neuron","The diagram shows how signals pass between neurons.","図は神経細胞間で信号が伝わる様子を示す。","neuron は情報を伝える神経細胞。nerve は神経線維が集まった神経を指す。"],
    ["vegetation","Dense vegetation covered the hillside.","密生した植物が丘の斜面を覆っていた。","vegetation はある地域の植物全体である植生。通常数えない名詞。"],
    ["warrior","The legend tells of a warrior who protected the village.","伝説は村を守った戦士について語る。","warrior は戦う人を表す、歴史や物語に合う語。現代の職業的な兵士は soldier。"],
    ["mutation","The researchers identified a mutation in the gene.","研究者たちは遺伝子の変異を特定した。","mutation は遺伝情報の変化。必ず有害とも有益とも限らない。"],
    ["sewage","The plant treats sewage before releasing the water.","その施設は水を放出する前に下水を処理する。","sewage は汚水・下水。流す管や水路そのものは sewer と呼ぶ。"],
    ["paradigm","The discovery challenged the existing scientific paradigm.","その発見は従来の科学的枠組みに疑問を投げかけた。","paradigm は考えや研究を組み立てる基本的な枠組み。語末の g は発音しない。"],
    ["protocol","The countries signed a protocol on environmental cooperation.","各国は環境協力に関する議定書に署名した。","protocol は議定書や正式な手順。通信の決まりも protocol と呼ぶ。"],
    ["skyscraper","The skyscraper towers above the older buildings.","超高層ビルが古い建物の上にそびえている。","skyscraper は非常に高いビル。sky と scrape から空に届く高さを連想できる。"],
    ["accord","The result is in accord with our prediction.","結果は私たちの予測と一致している。","in accord with ... は～と一致してという表現。an accord は正式な合意にも使う。"],
    ["bureaucrat","The proposal was reviewed by a senior bureaucrat.","その提案は上級官僚によって検討された。","bureaucrat は行政の官僚。文脈によって形式主義的な職員という批判も含む。"],
    ["array","The market offers a wide array of spices.","市場には多彩な香辛料がある。","an array of ... は多くのものが並ぶ集まり。a wide array は幅広い種類を示す。"],
    ["clash","A clash of opinions delayed the decision.","意見の衝突で決定が遅れた。","clash は強い対立や衝突。日程が重なる場合にも使える。"],
    ["torture","The report condemns the use of torture.","報告書は拷問の使用を非難している。","torture は激しい苦痛を意図的に与える拷問。通常数えない名詞でも動詞でも使う。"],
    ["reign","The palace was built during her reign.","宮殿は彼女の治世に造られた。","reign は君主の統治やその期間。rain『雨』と同じ発音でも別のつづり。"],
    ["thesis","Her thesis examines changes in urban transport.","彼女の学位論文は都市交通の変化を研究している。","thesis は学位論文や中心となる主張。複数形は theses。"],
    ["digit","The code contains six digits.","そのコードは六桁の数字からなる。","digit は数を表す一つの数字。a six-digit code は六桁のコードという形。"],
    ["agenda","The first item on the agenda is the budget.","議題の最初の項目は予算だ。","agenda は会議で扱う項目一覧。on the agenda で議題に載っていることを示す。"],
    ["onset","The records describe the onset of the symptoms.","記録は症状が現れ始めた時点を記している。","the onset of ... は始まり・発生。病気や好ましくない状態によく使う。"],
    ["peasant","The painting shows peasants working in the fields.","その絵は畑で働く農民たちを描いている。","peasant は特に過去の社会の小規模な農民。必ず小作農だけを指すわけではない。"],
    ["ultraviolet","The instrument detects ultraviolet light.","その装置は紫外線を検出する。","ultraviolet light は紫外線。略称 UV もこの語から来ている。"],
    ["renowned","The town is renowned for its pottery.","その町は陶器で有名だ。","be renowned for ... は～で高く評価され知られていること。名声の理由には for を使う。"],
    ["transparent","The box has a transparent lid.","その箱には透明なふたがある。","transparent は向こうが見える透明さ。決定過程が明確で隠し事がない意味にも使う。"],
    ["dim","The room was lit by a dim lamp.","部屋は薄暗いランプで照らされていた。","dim は光が弱いこと。a dim memory ははっきりしない記憶になる。"],
    ["legitimate","The residents raised legitimate concerns about the noise.","住民は騒音についてもっともな懸念を示した。","legitimate は正当な根拠があること。法律に適ったという意味もある。"],
    ["adverse","The crops survived despite adverse weather conditions.","作物は悪天候にもかかわらず生き残った。","adverse は不利な・有害なこと。adverse effects は悪影響を表す。"],
    ["swift","The rescue team made a swift response.","救助隊は迅速に対応した。","swift は動作や対応が速いこと。副詞 swiftly は素早くという意味。"],
    ["naive","It was naive to expect the task to be effortless.","その作業が苦労なくできると思ったのは甘かった。","naive は経験不足から単純に信じること。素直さだけでなく判断の甘さを含み得る。"],
    ["dumb","That was a dumb mistake to make.","それはばかな間違いだった。","dumb はくだけた強い否定語。話せない人を指す古い用法は侮辱的に受け取られ得る。"],
    ["gloomy","The sky looked gloomy before the storm.","嵐の前、空はどんよりしていた。","gloomy は暗く沈んだこと。a gloomy outlook は悲観的な見通しを表す。"],
    ["furious","She was furious about the broken promise.","彼女は約束が破られたことに激怒していた。","be furious about ... は～に非常に怒っていること。人には furious with someone とも言う。"],
    ["earnest","He made an earnest attempt to understand her concerns.","彼は彼女の心配を理解しようと真剣に努めた。","earnest は本気で熱心なこと。in earnest は本格的に・真剣にという表現。"],
    ["terrific","You did a terrific job on the display.","展示をとても見事に仕上げましたね。","terrific は日常では非常によいという称賛。terrible『ひどい』と取り違えないようにする。"],
    ["vertical","Draw a vertical line through the center.","中心を通る垂直な線を引いてください。","vertical は上下方向の垂直なこと。horizontal は水平方向を表す。"],
    ["wicked","The tale features a wicked ruler.","その物語には邪悪な支配者が登場する。","wicked は道徳的に悪いこと。物語の悪役を述べる場面によく使う。"],
    ["subjective","Judging beauty is often subjective.","美しさの判断はしばしば主観的だ。","subjective は個人の感じ方によること。客観的な objective と対になる。"],
    ["enlightened","The essay argues for a more enlightened approach to education.","その随筆はより開かれた教育への取り組みを主張している。","enlightened は知識と理解に基づく進歩的なこと。話し手の肯定的な評価を含む。"],
    ["authentic","The museum confirmed that the letter was authentic.","博物館はその手紙が本物だと確認した。","authentic は出所などが確かで本物のこと。偽物 fake と対比できる。"],
    ["brutal","The novel describes the effects of a brutal war.","その小説は残忍な戦争の影響を描いている。","brutal は暴力的で容赦のないこと。単に厳しいという語より強い。"],
    ["dizzy","I felt dizzy after spinning around.","くるくる回った後、めまいがした。","dizzy はめまいがする状態の形容詞。feel dizzy と組み合わせ、名詞は dizziness。"],
    ["sheer","The team succeeded through sheer determination.","そのチームはひたすら強い意志で成功した。","sheer はまったくの・純粋なという強調。sheer size は大きさそのものの圧倒的さ。"],
    ["naughty","The naughty puppy stole a sock.","いたずら好きの子犬が靴下を持っていった。","naughty は主に子どもやペットの行儀の悪さ。深刻な邪悪さより軽い叱責に使う。"],
    ["damp","The towel was still damp in the morning.","タオルは朝もまだ湿っていた。","damp は少し湿った状態。ずぶぬれの soaked より水分が少ない。"],
    ["static","The chart shows that the population remained static.","グラフは人口が変わらなかったことを示している。","static は動きや変化がないこと。dynamic は動的で変化するという対比。"],
    ["doomed","Without enough water, the plants were doomed to die.","水が足りず、その植物は枯れる運命にあった。","be doomed to do は悪い結果を避けられないこと。中立的な未来全般には使わない。"],
    ["respiratory","The diagram shows the respiratory system.","図は呼吸器系を示している。","respiratory は呼吸に関する形容詞。respiration は呼吸という名詞。"],
    ["innumerable","The collection contains innumerable handwritten notes.","その資料集には数え切れない手書きのメモがある。","innumerable は数え切れないほど多いこと。通常は複数名詞を修飾する。"],
    ["clumsy","I was clumsy with the unfamiliar tools.","慣れない道具をうまく扱えなかった。","clumsy は動作がぎこちない・不器用なこと。a clumsy explanation は拙い説明になる。"],
    ["aesthetic","The design balances practical and aesthetic considerations.","その設計は実用面と美的な面を両立している。","aesthetic は美しさや芸術的な感覚に関すること。機能だけでなく見た目を評価する語。"],
    ["obsessed","The character is obsessed with finding the lost map.","その登場人物は失われた地図の発見に取りつかれている。","be obsessed with ... は頭から離れないほど執着すること。単なる興味より強い。"],
    ["detached","The label had become detached from the box.","ラベルが箱から外れていた。","be detached from ... は～から切り離された状態。感情を交えず距離を置く意味もある。"],
    ["wrecked","The ship was wrecked on the rocks.","船は岩場で難破した。","wrecked は wreck の過去形・過去分詞。船以外の物がひどく壊れた場合にも使う。"],
    ["reckless","It was reckless to drive so fast in the rain.","雨の中でそんなに速く運転するのは無謀だった。","reckless は結果や危険を十分考えないこと。勇敢な brave と同じ評価ではない。"],
    ["arrogant","His arrogant reply upset the group.","彼の傲慢な返事に皆が不快になった。","arrogant は自分が他人より優れていると見せる態度。自信がある confident と区別する。"],
    ["preoccupied","She was preoccupied with preparations for the event.","彼女は催しの準備で頭がいっぱいだった。","be preoccupied with ... は～に気を取られていること。ほかのことへ注意が向かない状態を表す。"],
    ["gigantic","A gigantic screen stood at the back of the stage.","舞台の後ろに巨大なスクリーンがあった。","gigantic は非常に大きいこと。giant『巨人・巨大なもの』と関連づけて覚えられる。"],
    ["conspicuous","The red umbrella was conspicuous in the crowd.","赤い傘は群衆の中で目立っていた。","conspicuous は簡単に目につくこと。反対は inconspicuous『目立たない』。"],
    ["slender","The plant has a long, slender stem.","その植物には長く細い茎がある。","slender は細くすらりとしたこと。a slender chance はごくわずかな可能性という比喩。"],
    ["manifest","Her enthusiasm was manifest in every detail.","彼女の熱意は細部のすべてに明らかだった。","形容詞 manifest ははっきりわかること。動詞では感情や性質を表に示す意味になる。"],
    ["tidy","Keep your workspace tidy.","作業場所をきちんと整えておいてください。","tidy は整頓された形容詞。動詞 tidy up は片づけることを表す。"],
    ["skeptical","I am skeptical of claims without evidence.","私は証拠のない主張に懐疑的だ。","be skeptical of/about ... は～をすぐには信じないこと。理由を確かめようとする態度にも使う。"],
    ["notorious","The road is notorious for heavy traffic.","その道路は交通渋滞で悪名高い。","notorious for ... は悪いことで知られていること。中立的な famous と区別する。"],
    ["anonymous","The library received an anonymous donation.","図書館は匿名の寄付を受けた。","anonymous は名前が明かされていないこと。単に有名でない unknown とは異なる。"],
    ["monotonous","The task became monotonous after several hours.","数時間たつと、その作業は単調に感じられた。","monotonous は変化がなく退屈なこと。音・景色・仕事の繰り返しにも使う。"],
    ["ample","There is ample room for everyone.","全員に十分なスペースがある。","ample は必要量以上の余裕がある形容詞。ample time はたっぷりの時間を表す。"],
    ["trim","The small garden looked neat and trim.","その小さな庭はこぎれいに整っていた。","形容詞 trim は整ったこと。動詞 trim は余分な部分を切りそろえる意味。"],
    ["savage","The island was hit by a savage storm.","島は猛烈な嵐に見舞われた。","savage は激しい・残酷なこと。人々の文化を見下す呼称として使うのは侮辱的になる。"],
    ["coherent","Her report presents a coherent argument.","彼女の報告書は筋の通った議論を示している。","coherent は各部分がつながり全体として理解できること。単に文法が正しいという意味より広い。"],
    ["eloquent","She gave an eloquent speech about the value of libraries.","彼女は図書館の価値について雄弁に語った。","eloquent は考えや感情を効果的に伝えること。長く話すこと自体を指すわけではない。"],
    ["foul","A foul smell came from the drain.","排水口からひどい臭いがした。","foul は非常に不快な・汚いこと。競技では規則違反の反則という名詞にもなる。"],
    ["juvenile","The study examines juvenile birds before they leave the nest.","その研究は巣立ち前の幼鳥を調べている。","juvenile はまだ成熟していないこと。人の少年期にも動物の幼体にも使う。"],
    ["compulsory","Attendance at the safety session is compulsory.","安全講習への出席は義務だ。","compulsory は規則などで必須とされること。選べる optional と対比できる。"],
    ["prone","This area is prone to flooding.","この地域は洪水が起こりやすい。","be prone to ... は好ましくないことが起きやすいこと。to の後は名詞や -ing 形。"],
    ["arbitrary","The numbers were assigned in an arbitrary order.","番号は特に根拠のない順序で割り当てられた。","arbitrary は一定の理由や基準に基づかないこと。権力者の恣意的な判断にも使う。"],
    ["ingenious","She found an ingenious way to save space.","彼女は場所を節約する独創的な方法を見つけた。","ingenious は工夫が巧みで独創的なこと。ingenuous『純真な』とつづりが似ているが別の語。"],
    ["divine","The painting represents divine power through light.","その絵は光を通して神の力を表している。","divine は神に関する・神聖なこと。会話ではすばらしいという誇張にも使われる。"],
    ["tender","She spoke in a tender voice to the child.","彼女は子どもに優しい声で話しかけた。","tender は愛情のこもった優しさ。食べ物なら柔らかい、体の部分なら触ると痛い意味にもなる。"],
    ["outraged","Residents were outraged by the destruction of the park.","住民は公園の破壊に憤慨していた。","be outraged by/at ... は不当だと感じ強く怒ること。outrage の過去分詞で感情の状態を表す。"],
    ["intrinsic","The material has intrinsic value beyond its price.","その素材には価格だけでない本来の価値がある。","intrinsic は外から与えられたのでなく本来備わること。intrinsic to ... は～に固有の。"],
    ["paralyzed","The transport system was paralyzed by the heavy snow.","交通網は大雪で麻痺した。","paralyzed は paralyze の過去分詞。身体が動かない状態のほか、仕組みが機能しない比喩にも使う。"]
  ];
  const normalize = word => String(word || '').normalize('NFKC').trim().toLowerCase();
  const notes = new Map(rows.map(([word,example,translation,note])=>[normalize(word),{word,example,translation,note}]));
  const escape = value => String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  function get(word) { return notes.get(normalize(word)) || null; }
  function html(word) {
    const entry=get(word);
    if (!entry) return '<p class="word-note">この単語の例文・用法解説は未掲載です。まず表示された意味を確認し、苦手復習でもう一度思い出してみましょう。</p>';
    return `<details class="word-note"><summary>${escape(entry.word)} の例文・使い方</summary><p lang="en">${escape(entry.example)}</p><p>${escape(entry.translation)}</p><p>${escape(entry.note)}</p><details><summary>確認練習：例文を隠して、日本語から英語で言ってみる</summary><p lang="en">${escape(entry.example)}</p><p>答えを見ずに言えたか確認し、後で苦手復習にも取り組みましょう。この確認だけでは学習記録は変わりません。</p></details></details>`;
  }
  global.SushiWordNotes=Object.freeze({get,html,entries:()=>rows.map(([word])=>({...get(word)}))});
})(window);
